INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Política de Trabalho e Reintegração Social nas Políticas Penais', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1591', 'gratuito', 'Iniciante', 'Política de Trabalho e Reintegração Social nas Políticas Penais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 40h. O curso aborda as políticas de trabalho e emprego no Brasil, sua evolução, legislação e relação com raça, gênero, classe, direitos sociais e trabalho decente. Também analisa políticas penais, trabalho no sistema prisional, direitos humanos, estigmas e a Política Nacional de Trabalho no Sistema Prisional, com foco na reintegração social. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1591');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA e Transformação Digital', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1588', 'gratuito', 'Iniciante', 'IA e Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 15h. Descubra como a inteligência artificial e a transformação digital estão redefinindo a atuação governamental. Este curso apresenta conceitos, práticas e estratégias para o uso ético e confiável da IA, fortalecendo a gestão pública, a inovação em serviços e a geração de valor para a sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1588');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA e produtividade pessoal no serviço público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1560', 'gratuito', 'Iniciante', 'IA e produtividade pessoal no serviço público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 2h. Aprenda a usar IA para aumentar sua produtividade no setor público: automação de processos, gestão do SEI, elaboração de documentos, atendimento ao cidadão, análise de dados abertos e governança responsável. Prático e aplicável ao cotidiano do servidor. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1560');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da IA no Contexto do Serviço Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1559', 'gratuito', 'Iniciante', 'Fundamentos da IA no Contexto do Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 1h. Explore os fundamentos da IA no setor público: regulação internacional, transparência algorítmica, ética, impactos no trabalho e sustentabilidade. Ideal para servidores que querem compreender o contexto e os princípios que orientam o uso responsável da IA. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1559');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Entendendo Custos no Setor Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1552', 'gratuito', 'Iniciante', 'Entendendo Custos no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Pública. Carga horária: 16h. Neste curso, apresentamos os principais conceitos sobre o tema, como a Contabilidade de Custos Aplicada ao Setor Público, a CASP, o arcabouço legal que fundamenta a sua prática e a interação dela com a gestão e com o orçamento público. Também explicamos como a contabilidade de custos pode melhorar a aplicação dos recursos públicos e como os gestores públicos devem se engajar nessa atividade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1552');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cidades e Mudanças do Clima: informações territoriais para ação urbana climática', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1549', 'gratuito', 'Iniciante', 'Cidades e Mudanças do Clima: informações territoriais para ação urbana climática — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 10h. O curso explora estratégias de ação frente à crise climática nos municípios brasileiros, orienta sobre os impactos no território e a produção de dados locais para embasar políticas urbanas eficazes. O foco é capacitar pessoas a aplicar uma lente climática na gestão das cidades, transformando as informações técnicas em decisões governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1549');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Diretrizes básicas para contratação de construção industrializada', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1548', 'gratuito', 'Iniciante', 'Diretrizes básicas para contratação de construção industrializada — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 5h. O curso aborda os novos modelos de negócios demandados pelas rápidas e perceptíveis transformações provocadas pela introdução acelerada da construção industrializada no mercado, explorando e avaliando as alternativas e condicionantes relativas a tributação, legislação, financiamento, normas técnicas e logística. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1548');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Implementação: Orçamento Inteligente de Obras - BIM', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1547', 'gratuito', 'Iniciante', 'Implementação: Orçamento Inteligente de Obras - BIM — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 24h. Aprenda a aplicar a metodologia BIM para criar orçamentos de obras mais precisos, integrados e eficientes. Neste curso, você conhecerá práticas e ferramentas para extrair quantitativos, reduzir erros e otimizar custos ao longo do ciclo de vida dos projetos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1547');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elementos de Projeto, planejamento e gestão da construção industrializada', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1546', 'gratuito', 'Iniciante', 'Elementos de Projeto, planejamento e gestão da construção industrializada — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 5h. O curso aborda os elementos fundamentais para elaboração de projetos, destacando a coordenação modular, a padronização de componentes e o uso de ferramentas tais como o BIM, gestão de requisitos, e DfMA (Design for Manufacturing and Assembly) para promover a integração entre projeto, fábrica logística e obra, com foco em eficiência, previsibilidade e redução de desperdícios. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1546');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como escrever bons prompts com Copilot', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1544', 'gratuito', 'Iniciante', 'Como escrever bons prompts com Copilot — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Aprenda a escrever prompts eficazes e extraia o melhor da inteligência artificial com o Copilot! O curso apresenta técnicas práticas de engenharia de prompts aplicadas ao Microsoft Copilot, ensinando como formular instruções claras e precisas para obter resultados de alta qualidade em textos, análises, códigos e outros conteúdos. Destinado a profissionais e servidores que desejam usar o Copilot com mais eficácia e produtividade no trabalho. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1544');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Compartilhamento de Dados | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1543', 'gratuito', 'Iniciante', 'Eixo 3 - Compartilhamento de Dados | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 38h. O eixo aborda competências voltadas à disponibilização, integração e reutilização de dados no setor público, com base em padrões de interoperabilidade, diretrizes de abertura e uso de registros de referência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1543');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Fundamentos de Governança de Dados | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1542', 'gratuito', 'Intermediário', 'Eixo 2 - Fundamentos de Governança de Dados | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 66h. Domine os fundamentos de governança de dados e qualifique a gestão dos ativos de dados do setor público! Este eixo do Programa de Gestão e Qualidade de Ativos de Dados aborda os conceitos, estruturas e práticas de governança de dados, capacitando gestores e técnicos a implementar políticas de dados, definir papéis e responsabilidades e garantir a qualidade, a segurança e a disponibilidade dos dados nas organizações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1542');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Diretrizes Éticas e Responsabilidade no Uso de IA | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1541', 'gratuito', 'Iniciante', 'Eixo 1 - Diretrizes Éticas e Responsabilidade no Uso de IA | Programa - Gestão e Qualidade de Ativos de Dados no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 32h. Estabeleça diretrizes éticas e assuma responsabilidade no uso da inteligência artificial no setor público! Este eixo do Programa de Gestão e Qualidade de Ativos de Dados aborda os princípios éticos que devem nortear o uso de IA, as responsabilidades dos gestores e servidores na adoção de sistemas de IA e como garantir que a tecnologia seja utilizada de forma justa, transparente e alinhada aos valores do serviço público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1541');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cidades e Mudanças do Clima: Práticas de adaptação à mudança do clima nos municípios brasileiros', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1539', 'gratuito', 'Iniciante', 'Cidades e Mudanças do Clima: Práticas de adaptação à mudança do clima nos municípios brasileiros — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 10h. Conheça práticas concretas de adaptação às mudanças do clima nos municípios brasileiros! O curso apresenta estratégias de mitigação e adaptação climática aplicadas às cidades, com palestras e estudos de caso de experiências reais. Destinado a gestores, técnicos e planejadores municipais que buscam referências práticas para incorporar a agenda climática no desenvolvimento urbano e nas políticas locais de adaptação e resiliência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1539');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Centros de Acesso a Direitos e Inclusão Social na Política sobre Drogas', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1537', 'gratuito', 'Iniciante', 'Centros de Acesso a Direitos e Inclusão Social na Política sobre Drogas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Assistência Social. Carga horária: 20h. Qualifique a atuação nos Centros de Acesso a Direitos e Inclusão Social (CAIS) na política sobre drogas! O curso aborda o acolhimento, a atenção imediata e o plano de acesso a direitos nos CAIS, além do cuidado interseccional e os direitos humanos nas políticas sobre drogas. Destinado a profissionais que atuam nos CAIS e desejam fortalecer a abordagem de direitos humanos e a integração de serviços no atendimento a pessoas em situação de vulnerabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1537');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Refletir para não Repetir: Grupos com Homens Autores de Violência', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1518', 'gratuito', 'Iniciante', 'Refletir para não Repetir: Grupos com Homens Autores de Violência — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 20h. Quer fortalecer sua atuação na condução de grupos reflexivos para homens autores de violência de gênero? Neste curso, você terá acesso a conteúdos que auxiliam na compreensão de fundamentos teóricos e metodológicos, além de práticas de facilitação necessárias para promover a responsabilização e a mudança de comportamentos. Inscreva-se e fortaleça seu papel na prevenção da violência e na promoção da igualdade de gênero. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1518');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cidades e Mudanças do Clima: introdução à integração das políticas urbanas e climática nos municípios brasileiros', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1510', 'gratuito', 'Iniciante', 'Cidades e Mudanças do Clima: introdução à integração das políticas urbanas e climática nos municípios brasileiros — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 10h. Compreenda como as mudanças climáticas impactam as cidades e como integrar políticas urbanas e climáticas nos municípios brasileiros! O curso aborda os fundamentos da mudança do clima e a relação específica entre clima e cidades, preparando gestores e técnicos municipais para incorporar a perspectiva climática no planejamento urbano e nas políticas de desenvolvimento local sustentável. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1510');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Meliponicultura urbana', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1508', 'gratuito', 'Iniciante', 'Meliponicultura urbana — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 12h. Aprenda a criar abelhas sem ferrão em ambiente urbano e contribua para a biodiversidade e a sustentabilidade das cidades! O curso aborda a diversidade das abelhas, as diferenças entre espécies, como obter colônias, técnicas de manejo, colheita do mel, flora apícola, legislação e soluções para problemas frequentes. Destinado a apicultores urbanos, educadores ambientais e cidadãos interessados em meliponicultura como prática de conservação e economia solidária. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1508');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Aplicações Práticas da IA na Rotina Administrativa | Programa - IA para Otimização de Processos e Automação Inteligente no Serviço Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1507', 'gratuito', 'Intermediário', 'Eixo 2 - Aplicações Práticas da IA na Rotina Administrativa | Programa - IA para Otimização de Processos e Automação Inteligente no Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 78h. Aplique a inteligência artificial nas rotinas administrativas do serviço público com eficiência e responsabilidade! Este eixo do Programa de IA para Otimização de Processos capacita servidores a identificar e utilizar ferramentas de IA em tarefas cotidianas da administração, com foco em ganhos rápidos de produtividade, qualidade dos processos e uso ético e legal da tecnologia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1507');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Fundamentos, Ética e Estratégia de Dados | Programa - IA para Otimização de Processos e Automação Inteligente no Serviço Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1506', 'gratuito', 'Intermediário', 'Eixo 1 - Fundamentos, Ética e Estratégia de Dados | Programa - IA para Otimização de Processos e Automação Inteligente no Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 77h. Domine os fundamentos, a ética e a estratégia de dados para impulsionar a transformação do serviço público! Este eixo do Programa de IA para Otimização de Processos aborda os conceitos essenciais de ciência de dados, os princípios éticos no uso de dados e IA e como desenvolver uma estratégia de dados alinhada às necessidades e valores da administração pública, com foco em responsabilidade e impacto social positivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1506');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Resiliência Territorial: Princípios e Práticas de Planejamento', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1505', 'gratuito', 'Iniciante', 'Resiliência Territorial: Princípios e Práticas de Planejamento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 30h. Construa territórios mais resilientes com planejamento estratégico e governança sólida! O curso aborda os fundamentos sobre territórios, a importância de uma atuação territorial consistente e os princípios de resiliência, governança e contratualização territorial. Destinado a gestores, planejadores e técnicos que atuam com desenvolvimento territorial e desejam incorporar a dimensão da resiliência nos planos e políticas de seus municípios e regiões. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1505');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - IA e Gestão de Projetos | Programa - Gestão Estratégica de Tecnologia para Gestores de TIC', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1503', 'gratuito', 'Iniciante', 'Eixo 1 - IA e Gestão de Projetos | Programa - Gestão Estratégica de Tecnologia para Gestores de TIC — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 16h. Integre inteligência artificial à gestão de projetos de TIC e amplie sua capacidade de entrega! Este eixo do Programa de Gestão Estratégica de Tecnologia para Gestores de TIC aborda como a IA pode ser incorporada ao ciclo de vida dos projetos tecnológicos, apoiando o planejamento, o monitoramento e a tomada de decisão para maior eficiência, qualidade e inovação nas iniciativas de tecnologia no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1503');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Resiliência Territorial: do Planejamento à Ação Frente às Mudanças Climáticas', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1501', 'gratuito', 'Iniciante', 'Resiliência Territorial: do Planejamento à Ação Frente às Mudanças Climáticas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Construa territórios mais resilientes frente às mudanças climáticas! O curso aborda os fundamentos da resiliência territorial, as estratégias para sua construção e casos e experiências práticas que conectam teoria e ação. Destinado a gestores, técnicos e planejadores que atuam com desenvolvimento territorial e precisam incorporar a dimensão climática nas políticas, planos e projetos de suas regiões e municípios. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1501');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderança Estratégica com IA na Administração Pública', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1498', 'gratuito', 'Iniciante', 'Liderança Estratégica com IA na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 30h. Lidere com inteligência artificial e transforme a gestão pública! O curso aborda liderança pública e IA, a IA como ferramenta estratégica para gestores, produtividade com IA na gestão pública, liderança e gestão de equipes com IA e planejamento e aplicação de IA na administração pública. Destinado a líderes e gestores públicos que desejam incorporar a IA à sua estratégia de liderança e modernizar a entrega de resultados para a sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1498');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Capacitação para a Construção dos Planos Municipais de Manejo Populacional Ético de Cães e Gatos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1495', 'gratuito', 'Iniciante', 'Capacitação para a Construção dos Planos Municipais de Manejo Populacional Ético de Cães e Gatos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Saúde. Carga horária: 20h. Elabore Planos Municipais de Manejo Populacional Ético de Cães e Gatos com base técnica e legal! O curso aborda a política pública de manejo, ética e base legal, planejamento e gestão, controle populacional, captura e abrigamento, saúde pública, zoonoses, controle reprodutivo e medicina veterinária legal. Destinado a gestores municipais, veterinários e técnicos que atuam com bem-estar animal e saúde pública em municípios brasileiros. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1495');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Obras Públicas: contratação e fiscalização sob o enfoque da Lei 14.133/21', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1489', 'gratuito', 'Iniciante', 'Obras Públicas: contratação e fiscalização sob o enfoque da Lei 14.133/21 — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 30h. Contrate e fiscalize obras públicas com segurança sob o enfoque da Nova Lei de Licitações! O curso aborda o planejamento da contratação, a execução contratual e a utilização do objeto, e as principais irregularidades e possíveis sanções previstas na Lei nº 14.133/2021. Destinado a gestores, engenheiros, fiscais de obra e agentes de contratação que precisam atuar em conformidade com o novo marco legal das obras públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1489');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Instruindo o Processo de Contratação | Programa - Contratações Públicas: Planejamento da Contratação.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1486', 'gratuito', 'Intermediário', 'Eixo 1 - Instruindo o Processo de Contratação | Programa - Contratações Públicas: Planejamento da Contratação. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 100h. Instrua o processo de contratação pública com qualidade e conformidade! Este eixo do Programa de Contratações Públicas aborda os procedimentos de instrução do processo de contratação, desde o documento de formalização da demanda até os atos que compõem o planejamento da contratação. Destinado a agentes de contratação e gestores que buscam estruturar processos mais robustos e alinhados à Nova Lei de Licitações desde sua fase inicial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1486');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 5 - Conduzindo Investigação em Processos Administrativos Responsabilizatórios e Solucionando Conflitos | Programa - Contratações Públicas: Gestão do Contrato.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1482', 'gratuito', 'Iniciante', 'Eixo 5 - Conduzindo Investigação em Processos Administrativos Responsabilizatórios e Solucionando Conflitos | Programa - Contratações Públicas: Gestão do Contrato. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 29h. Conduza investigações em processos administrativos responsabilizatórios e solucione conflitos contratuais com segurança jurídica! Este eixo do Programa de Contratações Públicas aborda os procedimentos de investigação para apuração de infrações contratuais, a instrução dos processos e os mecanismos de solução de conflitos disponíveis na Nova Lei de Licitações. Essencial para gestores e fiscais de contratos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1482');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Efetuando Alteração Contratual | Programa - Contratações Públicas: Gestão do Contrato.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1481', 'gratuito', 'Iniciante', 'Eixo 4 - Efetuando Alteração Contratual | Programa - Contratações Públicas: Gestão do Contrato. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 27h. Este eixo faz parte do programa de aprendizagem Contratações Públicas: Gestão do Contrato. Ele aborda as alterações contratuais que são realizadas em contratos, de acordo com necessidades específicas, o que está disciplinado no capítulo VII da Lei n° 14.133, de 1º de abril de 2021. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1481');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Fiscalizando Contratações de Tecnologia da Informação | Programa - Contratações Públicas: Gestão do Contrato.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1480', 'gratuito', 'Iniciante', 'Eixo 3 - Fiscalizando Contratações de Tecnologia da Informação | Programa - Contratações Públicas: Gestão do Contrato. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 23h. Fiscalize contratos de TI com competência técnica e segurança jurídica! Este eixo do Programa de Contratações Públicas aborda as especificidades da fiscalização de contratos de tecnologia da informação, incluindo métricas de desempenho, análise de resultados e as principais irregularidades a serem identificadas. Destinado a fiscais e gestores de contratos de TI que buscam aprimorar sua capacidade de monitoramento e controle. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1480');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Utilizando os instrumentos auxiliares das licitações | Programa - Contratações Públicas: Seleção do Fornecedor.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1476', 'gratuito', 'Iniciante', 'Eixo 4 - Utilizando os instrumentos auxiliares das licitações | Programa - Contratações Públicas: Seleção do Fornecedor. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 22h. Utilize os instrumentos auxiliares das licitações para ampliar a eficiência das contratações! Este eixo do Programa de Contratações Públicas aborda os principais instrumentos complementares ao processo licitatório — como pré-qualificação, credenciamento e manifestação de interesse — e como utilizá-los de forma estratégica para otimizar as contratações da administração pública conforme a Nova Lei de Licitações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1476');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Contratando por dispensa ou inexigibilidade | Programa - Contratações Públicas: Seleção do Fornecedor.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1475', 'gratuito', 'Iniciante', 'Eixo 3 - Contratando por dispensa ou inexigibilidade | Programa - Contratações Públicas: Seleção do Fornecedor. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 35h. Realize contratações diretas com segurança jurídica e conformidade! Este eixo do Programa de Contratações Públicas aborda os fundamentos e os procedimentos das contratações por dispensa e inexigibilidade de licitação previstas na Lei nº 14.133/2021, incluindo as hipóteses legais, a instrução do processo e as cautelas necessárias para garantir regularidade e transparência. Essencial para agentes de contratação do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1475');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Selecionando fornecedor por licitação | Programa - Contratações Públicas: Seleção do Fornecedor.', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1473', 'gratuito', 'Intermediário', 'Eixo 1 - Selecionando fornecedor por licitação | Programa - Contratações Públicas: Seleção do Fornecedor. — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 50h. Selecione fornecedores por licitação com segurança jurídica e eficiência operacional! Este eixo do Programa de Contratações Públicas aborda os fundamentos e os procedimentos do processo licitatório conforme a Nova Lei de Licitações, capacitando agentes de contratação a conduzir processos de seleção de fornecedores com qualidade, transparência e conformidade legal desde o planejamento até a adjudicação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1473');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão para Aceleração de Equipes de Inovação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1472', 'gratuito', 'Iniciante', 'Gestão para Aceleração de Equipes de Inovação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 35h. Acelere suas equipes de inovação com fundamentos sólidos e metodologias ágeis! O curso aborda os fundamentos da inovação no setor público, o desenvolvimento pessoal e de equipes, a incorporação de metodologias ágeis, a liderança da mudança e a comunicação e engajamento baseado em dados. Destinado a gestores, líderes de inovação e servidores que desejam fortalecer a cultura e a prática inovadora em suas equipes e organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1472');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Aplicações Estratégicas em Dados e IA | Programa - Executivo de Dados e IA: Fundamentos e Estratégias no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1465', 'gratuito', 'Intermediário', 'Eixo 2 - Aplicações Estratégicas em Dados e IA | Programa - Executivo de Dados e IA: Fundamentos e Estratégias no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 125h. Aplique dados e inteligência artificial com visão estratégica no setor público! Este eixo do Programa de Executivo de Dados e IA aborda como traduzir fundamentos técnicos em estratégias concretas de uso de dados e IA, capacitando líderes públicos a identificar aplicações de alto valor, avaliar riscos e oportunidades e orientar suas organizações na construção de uma cultura data-driven responsável e orientada a resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1465');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Fundamentos para Governança e Cultura de Dados | Programa - Executivo de Dados e IA: Fundamentos e Estratégias no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1464', 'gratuito', 'Intermediário', 'Eixo 1 - Fundamentos para Governança e Cultura de Dados | Programa - Executivo de Dados e IA: Fundamentos e Estratégias no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 135h. Construa uma cultura de dados e estabeleça os fundamentos de governança de dados na sua organização! Este eixo do Programa de Executivo de Dados e IA aborda os conceitos essenciais de governança e cultura de dados, como sensibilizar e engajar as organizações para o uso estratégico dos dados e as bases para uma gestão de dados responsável, ética e orientada a resultados no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1464');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cultural Values of Nature', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1462', 'gratuito', 'Iniciante', 'Cultural Values of Nature — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Explore the cultural values of nature and their relevance for public policy and conservation! This course covers the relationship between society and nature, the evolution of cultural values of nature in the international context, and their application in the Brazilian setting. Ideal for environmental managers, researchers and policymakers who want to incorporate cultural and relational values of nature into decision-making and conservation strategies. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1462');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Innovation Management in the Public Sector', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1461', 'gratuito', 'Iniciante', 'Innovation Management in the Public Sector — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. Develop the skills to manage and foster innovation in the public sector! This course covers the context of public sector innovation, perspectives on design thinking as a tool for creative problem-solving, and strategies for building lasting innovation capacity in government organizations. Ideal for public managers, analysts and civil servants committed to transforming public services through innovative approaches and human-centered solutions. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1461');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestión de la Innovación en el Sector Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1460', 'gratuito', 'Iniciante', 'Gestión de la Innovación en el Sector Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. ¡Desarrolla la capacidad de gestionar la innovación en el sector público en español! El curso aborda la innovación y el contexto del sector público, las perspectivas sobre design thinking y cómo construir capacidad de innovación en organizaciones gubernamentales. Ideal para gestores y servidores hispanohablantes comprometidos con la transformación del sector público a través de enfoques innovadores centrados en las necesidades de los ciudadanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1460');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: NDCs: Criação e implementação', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1459', 'gratuito', 'Iniciante', 'NDCs: Criação e implementação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 7h. Compreenda e implemente as Contribuições Determinadas Nacionalmente (NDCs) no contexto climático internacional! O curso aborda o que são as NDCs, por que são importantes, como projetá-las e como implementá-las efetivamente. Destinado a gestores, técnicos e formuladores de políticas climáticas que atuam no cumprimento dos compromissos do Brasil no Acordo de Paris e na implementação de políticas de mitigação e adaptação às mudanças do clima. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1459');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Acompanhando e avaliando o planejamento e a execução orçamentária e financeira | Orçamento e Finanças', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1456', 'gratuito', 'Intermediário', 'Eixo 4 - Acompanhando e avaliando o planejamento e a execução orçamentária e financeira | Orçamento e Finanças — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 100h. Acompanhe e avalie o planejamento e a execução orçamentária e financeira com rigor e método! Este eixo do Programa de Orçamento e Finanças aborda os instrumentos de monitoramento da execução, os relatórios e demonstrativos exigidos pela legislação e as técnicas de avaliação que permitem identificar desvios, corrigir rumos e aprimorar continuamente a gestão orçamentária e financeira dos entes públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1456');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Realizando a execução orçamentária e financeira | Orçamento e Finanças', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1455', 'gratuito', 'Intermediário', 'Eixo 3 - Realizando a execução orçamentária e financeira | Orçamento e Finanças — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 55h. Execute o orçamento e as finanças públicas com segurança, controle e conformidade! Este eixo do Programa de Orçamento e Finanças aborda os procedimentos de execução orçamentária e financeira — empenho, liquidação e pagamento —, os sistemas de controle e os registros contábeis necessários para garantir a regularidade e a transparência na aplicação dos recursos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1455');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Elaborando a Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA) | Orçamento e Finanças', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1454', 'gratuito', 'Iniciante', 'Eixo 2 - Elaborando a Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA) | Orçamento e Finanças — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 30h. Elabore a Lei de Diretrizes Orçamentárias e a Lei Orçamentária Anual com competência técnica! Este eixo do Programa de Orçamento e Finanças aborda os fundamentos, as etapas e os procedimentos de elaboração da LDO e da LOA, capacitando analistas e gestores a construir os principais instrumentos de planejamento orçamentário com consistência, transparência e alinhamento às prioridades de governo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1454');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Elaborando o Plano Plurianual (PPA) | Orçamento e Finanças', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1453', 'gratuito', 'Iniciante', 'Eixo 1 - Elaborando o Plano Plurianual (PPA) | Orçamento e Finanças — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 25h. Elabore o Plano Plurianual com método, consistência e alinhamento estratégico! Este eixo do Programa de Orçamento e Finanças aborda os fundamentos do PPA como instrumento central de planejamento governamental, as etapas de elaboração, a estrutura de programas e objetivos e a articulação com a visão estratégica do governo. Destinado a analistas, técnicos e gestores responsáveis pela elaboração do PPA nos âmbitos federal, estadual e municipal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1453');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como prevenir o assédio e a violência contra a mulher', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1452', 'gratuito', 'Iniciante', 'Como prevenir o assédio e a violência contra a mulher — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 24h. Previna o assédio e a violência contra a mulher com conhecimento, empatia e ação! O curso aborda o ciclo da violência, as formas de violência e assédio, os impactos na vida das mulheres, as estratégias de combate e como reaprender padrões mais saudáveis de convivência. Destinado a servidores, líderes e profissionais que desejam contribuir para ambientes de trabalho e comunidades mais seguros, respeitosos e livres de violência de gênero. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1452');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Project Management in Education', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1450', 'gratuito', 'Iniciante', 'Project Management in Education — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. Develop skills to plan, manage and evaluate educational projects effectively! This course covers planning and management of educational projects, project development and implementation, and project management methodologies applied to education. Ideal for education managers, coordinators and professionals who want to structure more robust, sustainable and impactful educational projects, using proven methodologies to improve outcomes and maximize resources. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1450');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA para Profissionais da Justiça', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1449', 'gratuito', 'Iniciante', 'IA para Profissionais da Justiça — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Explore as aplicações da inteligência artificial para profissionais da Justiça! O curso aborda como a IA está sendo usada no sistema de justiça — na análise de documentos, jurisprudência, automação de processos e apoio à tomada de decisão — e as implicações éticas e jurídicas do uso dessas tecnologias. Destinado a magistrados, promotores, defensores, advogados e técnicos do judiciário que desejam compreender e usar a IA com responsabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1449');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Ambiental Climática e Redução de Riscos de Desastres', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1448', 'gratuito', 'Iniciante', 'Educação Ambiental Climática e Redução de Riscos de Desastres — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 40h. Desenvolva competências em educação ambiental climática e prevenção de desastres! O curso aborda os fundamentos da educação ambiental climática, a percepção e redução de riscos de desastres socioambientais, as políticas de prevenção, redução e adaptação e a educação em clima de desastres. Destinado a educadores, gestores ambientais e profissionais de defesa civil que desejam fortalecer a consciência e a preparação comunitária para riscos climáticos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1448');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA para profissionais do direito', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1447', 'gratuito', 'Iniciante', 'IA para profissionais do direito — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Utilize a inteligência artificial para potencializar sua atuação jurídica! O curso aborda as aplicações práticas de IA para profissionais do direito, incluindo análise de jurisprudência, redação assistida, pesquisa legal automatizada e uso ético dessas ferramentas no exercício da advocacia e da função pública. Destinado a advogados, procuradores, assessores jurídicos e profissionais do direito que desejam ganhar produtividade e eficiência com IA. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1447');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA e clima: contrapartidas e transformação', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1446', 'gratuito', 'Iniciante', 'IA e clima: contrapartidas e transformação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Compreenda a relação entre inteligência artificial e mudanças climáticas — dos impactos às soluções! O curso aborda a ligação entre IA e o clima, as medidas para reduzir a pegada ambiental da IA e o papel da tecnologia na aceleração de soluções climáticas. Destinado a gestores, técnicos e profissionais de TI e meio ambiente que desejam entender e equilibrar o uso da IA com a necessidade de sustentabilidade ambiental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1446');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderança climática por meio da mudança de sistemas', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1445', 'gratuito', 'Iniciante', 'Liderança climática por meio da mudança de sistemas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 4h. Lidere a transformação climática por meio da mudança de sistemas! O curso aborda a introdução à mudança de sistemas, seus fundamentos, as técnicas de facilitação e como exercer liderança nesse processo. Destinado a gestores, líderes e profissionais que atuam com políticas climáticas e desejam desenvolver as competências necessárias para catalisar mudanças sistêmicas em direção a um futuro mais sustentável e resiliente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1445');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA e o futuro dos sistemas de saúde', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1442', 'gratuito', 'Iniciante', 'IA e o futuro dos sistemas de saúde — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 5h. Compreenda o impacto da inteligência artificial nos sistemas de saúde e como navegar esse cenário! O curso aborda noções básicas sobre IA na saúde, aplicações em diagnóstico e assistência, riscos e considerações éticas, regulamentação da IA na saúde e como identificar, avaliar e implementar sistemas de IA. Destinado a gestores, profissionais de saúde e reguladores que desejam compreender e preparar suas organizações para o futuro da saúde digital. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1442');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso Diferenciado da Força', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1441', 'gratuito', 'Iniciante', 'Uso Diferenciado da Força — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 40h. Compreenda os princípios e diretrizes do uso diferenciado da força no contexto da segurança pública! O curso aborda a nova perspectiva do uso diferenciado da força, os princípios e diretrizes gerais, as circunstâncias que justificam seu emprego e os mecanismos de controle e monitoramento. Essencial para profissionais da segurança pública que precisam atuar com legalidade, proporcionalidade e respeito aos direitos humanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1441');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Violência Baseada no Gênero: Qual a nossa Responsabilidade como Rede?', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1440', 'gratuito', 'Iniciante', 'Violência Baseada no Gênero: Qual a nossa Responsabilidade como Rede? — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 10h. Compreenda a violência baseada no gênero e o papel de cada serviço na rede de proteção! O curso aborda os fundamentos da VBG, os princípios e caminhos do cuidado em rede e o papel dos serviços não especializados na proteção de vítimas. Destinado a profissionais de saúde, educação, assistência social e segurança pública que integram a rede de atenção e proteção a mulheres e precisam articular suas ações de forma coordenada e humanizada. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1440');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Entenda como a IA afeta você e o seu governo', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1437', 'gratuito', 'Iniciante', 'Entenda como a IA afeta você e o seu governo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Entenda de forma prática como a inteligência artificial transforma a vida das pessoas e o funcionamento do governo! O curso aborda o que é IA, como identificar riscos e prevenir danos, como a IA pode auxiliar em diferentes cargos e como desenvolver uma mentalidade preparada para a era da IA. Destinado a gestores, servidores e cidadãos que desejam navegar com segurança e consciência no mundo cada vez mais marcado pela inteligência artificial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1437');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Inteligência Artificial, Machine Learning e Aplicações Éticas | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1436', 'gratuito', 'Iniciante', 'Eixo 4 - Inteligência Artificial, Machine Learning e Aplicações Éticas | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 32h. Domine os fundamentos de IA e machine learning e aplique-os com ética no setor público! Este eixo do Programa de Engenharia de Dados e IA Aplicada aborda os conceitos de inteligência artificial e aprendizado de máquina, os principais algoritmos e suas aplicações, e as considerações éticas essenciais para o uso responsável dessas tecnologias em projetos governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1436');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Engenharia de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1435', 'gratuito', 'Iniciante', 'Eixo 3 - Engenharia de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 24h. Domine os fundamentos de engenharia de dados e estruture pipelines eficientes para o setor público! Este eixo do Programa de Engenharia de Dados e IA Aplicada aborda os conceitos e práticas de engenharia de dados — ingestão, transformação, armazenamento e disponibilização de dados — capacitando gestores de TIC a liderar e supervisionar projetos de dados com foco em qualidade, escalabilidade e uso estratégico das informações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1435');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Fundamentos de Ciência de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1434', 'gratuito', 'Iniciante', 'Eixo 2 - Fundamentos de Ciência de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Domine os fundamentos de ciência de dados aplicados à gestão de TIC! Este eixo do Programa de Engenharia de Dados e IA Aplicada aborda os conceitos essenciais de ciência de dados — coleta, limpeza, análise e visualização de dados — capacitando gestores de TIC a compreender e orientar projetos de dados com maior embasamento técnico, favorecendo a tomada de decisão baseada em evidências no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1434');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Análise e Consulta de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1433', 'gratuito', 'Intermediário', 'Eixo 1 - Análise e Consulta de Dados | Programa - Engenharia de Dados e IA Aplicada para Gestores de TIC — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 44h. Domine a análise e consulta de dados como fundamento para decisões estratégicas em TIC! Este eixo do Programa de Engenharia de Dados e IA Aplicada capacita gestores de TIC a estruturar processos de consulta e análise de dados, utilizando ferramentas e métodos que transformam dados brutos em informações acionáveis para apoiar a gestão tecnológica e a tomada de decisão no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1433');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderança em IA no governo', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1432', 'gratuito', 'Iniciante', 'Liderança em IA no governo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Lidere a transformação da IA no setor público com confiança e visão estratégica! O curso aborda por que formar uma força de trabalho preparada para a IA, como construir confiança, competência e segurança, como influenciar equipes e lideranças e como levar adiante uma agenda de IA responsável no governo. Destinado a líderes e gestores públicos que precisam conduzir suas equipes e organizações na adoção responsável e eficaz da inteligência artificial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1432');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Policiamento e proteção aos povos indígenas', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1431', 'gratuito', 'Intermediário', 'Policiamento e proteção aos povos indígenas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 60h. Capacite profissionais de segurança pública para o policiamento e a proteção dos povos indígenas! O curso aborda a história, cosmologias e lutas dos povos indígenas, os direitos humanos e as violências contra essas populações e as questões ambientais em terras indígenas. Destinado a policiais, agentes de segurança e gestores que atuam em territórios indígenas ou com questões relacionadas à proteção dos direitos e da integridade dos povos originários. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1431');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Jornada da Diversidade: Inclusão em Ação', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1430', 'gratuito', 'Iniciante', 'Jornada da Diversidade: Inclusão em Ação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 6h. Mergulhe em uma jornada de aprendizado sobre diversidade e inclusão! O curso aborda questões étnico-raciais, pessoas com deficiência, diversidade de gerações, pessoas LGBTQIAPN+, equidade de gênero e encerra com uma síntese integradora. Destinado a servidores, líderes e equipes que buscam desenvolver competências para criar ambientes de trabalho mais inclusivos, respeitosos e representativos da diversidade da sociedade brasileira. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1430');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Liderança, Protagonismo e Comunicação de Futuro - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1429', 'gratuito', 'Intermediário', 'Eixo 4 - Liderança, Protagonismo e Comunicação de Futuro - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 51h. Desenvolva liderança, protagonismo e comunicação de futuro para a era da inteligência artificial! Este eixo do Programa IA Estratégica capacita altas lideranças a articular visões de futuro com IA, comunicar estratégias de transformação digital com clareza e exercer protagonismo na condução de suas organizações em direção a uma administração pública mais inteligente, ágil e orientada a resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1429');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Formulação de Políticas Públicas e otimização de serviços em IA - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1428', 'gratuito', 'Iniciante', 'Eixo 3 - Formulação de Políticas Públicas e otimização de serviços em IA - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 40h. Transforme sua visão estratégica em políticas públicas, liderando com ética e gerindo riscos na aplicação da IA. Utilize análises de tendências, estudos de caso e estratégias de governança para aprimorar serviços, implementar soluções inovadoras e gerar valor real à sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1428');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Prospecção de Cenários e Oportunidades com IA - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1427', 'gratuito', 'Iniciante', 'Eixo 2 - Prospecção de Cenários e Oportunidades com IA - Programa IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 13h. Prospecte cenários e identifique oportunidades com o uso estratégico da inteligência artificial! Este eixo do Programa IA Estratégica capacita altas lideranças a utilizar ferramentas de IA para análise de tendências, construção de cenários futuros e identificação de oportunidades de transformação no setor público. Destinado a dirigentes que desejam antecipar mudanças e posicionar suas organizações estrategicamente na era da IA. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1427');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Visão Estratégica e Sistêmica de IA no Setor Público - Programa - IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1426', 'gratuito', 'Iniciante', 'Eixo 1 - Visão Estratégica e Sistêmica de IA no Setor Público - Programa - IA Estratégica e Visão de Futuro para Altas Lideranças no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 29h. Desenvolva uma visão estratégica e sistêmica sobre o uso da inteligência artificial no setor público! Este eixo do Programa IA Estratégica capacita altas lideranças a compreender o impacto transformador da IA na administração pública, identificar oportunidades de aplicação estratégica e construir uma agenda de IA responsável, alinhada aos princípios de eficiência, ética e interesse público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1426');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Aplicações Práticas da IA na Rotina Administrativa | Programa IA na Prática: Ferramentas e Soluções no dia a dia do Agente Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1424', 'gratuito', 'Intermediário', 'Eixo 2 - Aplicações Práticas da IA na Rotina Administrativa | Programa IA na Prática: Ferramentas e Soluções no dia a dia do Agente Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 73h. Aplique ferramentas de inteligência artificial nas rotinas administrativas do serviço público e ganhe eficiência! Este eixo do Programa IA na Prática capacita agentes públicos a identificar e utilizar aplicações concretas de IA no trabalho diário — de automatização de tarefas a análise de documentos — com foco em responsabilidade, qualidade e conformidade com as normas do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1424');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Fundamentos e Consciência Crítica sobre o Uso da IA | Programa IA na Prática: Ferramentas e Soluções no dia a dia do Agente Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1423', 'gratuito', 'Intermediário', 'Eixo 1 - Fundamentos e Consciência Crítica sobre o Uso da IA | Programa IA na Prática: Ferramentas e Soluções no dia a dia do Agente Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 100h. Desenvolva consciência crítica sobre o uso da inteligência artificial no serviço público! Este eixo do Programa IA na Prática aborda os fundamentos da IA — o que é, como funciona e seus limites —, os riscos e vieses associados ao seu uso e como o agente público pode adotar uma postura crítica, responsável e informada diante das ferramentas de inteligência artificial disponíveis para o trabalho cotidiano. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1423');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: FluêncIA Estudantes', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1422', 'gratuito', 'Iniciante', 'FluêncIA Estudantes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Potencialize seus estudos com a inteligência artificial! O curso ensina estudantes a usar o Copilot como assistente de aprendizado: pesquisa acadêmica, preparação para avaliações, organização dos estudos, análise de textos, simulação de práticas profissionais e aprendizado de idiomas. Ideal para estudantes de graduação e pós-graduação que desejam incorporar ferramentas de IA ao seu repertório de estudo com segurança e eficácia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1422');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestión de Proyectos Educativos', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1421', 'gratuito', 'Iniciante', 'Gestión de Proyectos Educativos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. ¡Aprende a planificar, gestionar y evaluar proyectos educativos con método y eficacia! El curso aborda la planificación y gestión de proyectos educativos, el desarrollo y aplicación de proyectos y las metodologías de gestión de proyectos aplicadas a la educación. Ideal para gestores, coordinadores y profesionales de la educación que desean estructurar proyectos educativos más sólidos, sostenibles e impactantes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1421');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: FluêncIA Educadores', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1419', 'gratuito', 'Iniciante', 'FluêncIA Educadores — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 3h. Explore o potencial da inteligência artificial no ensino superior e transforme sua prática docente! O curso aborda o papel da IA na educação superior, novas formas de ensino com IA, preparação para o futuro e casos de uso que melhoram as aulas. Destinado a professores, coordenadores e gestores do ensino superior que desejam incorporar ferramentas de IA ao processo de ensino-aprendizagem com consciência crítica e propósito pedagógico. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1419');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Equipes em PGD', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1417', 'gratuito', 'Iniciante', 'Gestão de Equipes em PGD — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Pública. Carga horária: 30h. Gerencie equipes com eficácia no contexto do Programa de Gestão e Desempenho! O curso aborda os princípios da gestão de equipes no PGD e as ferramentas e técnicas para monitorar entregas, orientar o desempenho e promover o engajamento dos servidores. Destinado a chefes de unidade que coordenam equipes no PGD e precisam de estratégias práticas para conciliar autonomia, controle de resultados e bem-estar das equipes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1417');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Empregabilidade com o Copilot', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1414', 'gratuito', 'Iniciante', 'Empregabilidade com o Copilot — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 2h. Potencialize sua busca por emprego com o Microsoft Copilot! O curso ensina a extrair palavras-chave de vagas, otimizar e reescrever o currículo, organizar o perfil profissional e se preparar para entrevistas usando a fórmula STARR. Ideal para profissionais em recolocação, jovens talentos e qualquer pessoa que deseje usar a inteligência artificial para aumentar suas chances no processo seletivo com mais clareza e estratégia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1414');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Planos de Adaptação: do monitoramento à comunicação de resultados', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1412', 'gratuito', 'Iniciante', 'Planos de Adaptação: do monitoramento à comunicação de resultados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 7h. Aprenda a monitorar, avaliar e comunicar os resultados dos Planos de Adaptação às mudanças climáticas! O curso aborda a elaboração da estratégia de monitoramento e avaliação e a construção de uma estratégia eficaz de comunicação dos planos e seus resultados. Essencial para gestores públicos e técnicos envolvidos na implementação de políticas climáticas municipais e regionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1412');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Planos de Adaptação: da governança à análise do risco', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1410', 'gratuito', 'Iniciante', 'Planos de Adaptação: da governança à análise do risco — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 17h. Estruture a governança e analise os riscos climáticos para fundamentar seus planos de adaptação! O curso aborda a formação de governança para planos de adaptação, a aplicação da lente climática e a análise de risco. Destinado a gestores, técnicos e analistas que conduzem ou participam da elaboração de planos de adaptação às mudanças climáticas em âmbito municipal, estadual ou federal, com foco em robustez metodológica. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1410');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Atualização em Gestão Financeira e Orçamentária do SUAS', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1407', 'gratuito', 'Iniciante', 'Atualização em Gestão Financeira e Orçamentária do SUAS — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 40h. Atualize-se em gestão financeira e orçamentária do Sistema Único de Assistência Social! O curso aborda orçamento público, financiamento do SUAS, os fundos de assistência social e a execução dos recursos, além da prestação de contas e o papel dos conselhos. Destinado a gestores, técnicos e conselheiros de assistência social que atuam com o financiamento e controle dos recursos do SUAS em âmbito municipal, estadual e federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1407');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratação de serviços de publicidade na administração pública', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1405', 'gratuito', 'Iniciante', 'Contratação de serviços de publicidade na administração pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 30h. Contrate serviços de publicidade na administração pública com segurança jurídica e eficácia! O curso aborda o conceito de publicidade, as diferenças entre publicidade, propaganda e marketing, o que será contratado, a legislação aplicável e as etapas internas e externas do processo. Destinado a gestores e agentes de contratação que precisam conduzir processos de contratação de agências e serviços de comunicação no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1405');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Execução e Avaliação dos Planos de Entrega e de Trabalho do PGD', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1401', 'gratuito', 'Iniciante', 'Execução e Avaliação dos Planos de Entrega e de Trabalho do PGD — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Pessoas. Carga horária: 20h. Domine a execução e avaliação dos Planos de Entrega e de Trabalho no Programa de Gestão e Desempenho! O curso aborda os procedimentos de execução dos planos e os critérios e métodos de avaliação dos resultados. Destinado a servidores, chefes de unidade e gestores que participam do PGD e precisam compreender como registrar entregas, acompanhar o desempenho e realizar avaliações com transparência e objetividade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1401');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Planos de Adaptação: dados espaciais e indicadores para análise territorial', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1399', 'gratuito', 'Iniciante', 'Planos de Adaptação: dados espaciais e indicadores para análise territorial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 9h. Use dados espaciais e indicadores territoriais para qualificar os Planos de Adaptação às mudanças climáticas! O curso aborda a importância dos dados espaciais no planejamento da adaptação, metadados e catálogos de metadados e ferramentas de visualização de dados espaciais. Destinado a técnicos, analistas e gestores que trabalham com planejamento territorial e adaptação climática e precisam incorporar dados geoespaciais às suas análises. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1399');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão Estratégica e Inovação nas Empresas Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1398', 'gratuito', 'Iniciante', 'Gestão Estratégica e Inovação nas Empresas Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 30h. Desenvolva estratégia e inovação nas empresas estatais com foco em resultados e responsabilidade! O curso aborda planejamento estratégico, plano de negócios e metas, a agenda ODS/ESG e diversidade, políticas públicas aplicadas às estatais e inovação como vetor de transformação. Destinado a diretores, conselheiros e gestores de empresas estatais que desejam alinhar a estratégia empresarial às demandas de sustentabilidade, diversidade e inovação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1398');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: IA - Aplicações no Governo Federal', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1395', 'gratuito', 'Iniciante', 'IA - Aplicações no Governo Federal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 8h. Conheça as aplicações práticas de inteligência artificial no governo federal brasileiro! O curso aborda visão computacional e biometria, IA antifraude, otimização, modelagem preditiva, processamento de linguagem natural, IA generativa e large language models. Destinado a gestores, técnicos e servidores que desejam compreender como a IA está sendo usada para modernizar serviços, combater fraudes e aprimorar a gestão pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1395');
