INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Integridade e Ética no Serviço Público - Programa de Desenvolvimento Inicial para Cargos de Nível Superior', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1385', 'gratuito', 'Iniciante', 'Eixo 1 - Integridade e Ética no Serviço Público - Programa de Desenvolvimento Inicial para Cargos de Nível Superior — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 35h. Fortaleça os fundamentos de integridade e ética necessários ao exercício da função pública! Este eixo do Programa de Desenvolvimento Inicial aborda os princípios éticos, as normas de conduta e os valores essenciais para servidores de nível superior recém-ingressos no serviço público federal. Um ponto de partida indispensável para construir uma carreira pública pautada pela transparência, responsabilidade e compromisso com o interesse coletivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1385');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratação e licitações em BIM', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1382', 'gratuito', 'Iniciante', 'Contratação e licitações em BIM — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 16h. Domine os processos de contratação e licitação de obras públicas em BIM! O curso aborda o processo de contratação em BIM, as responsabilidades dos envolvidos, os riscos e fatores mitigadores, a capacidade técnica exigida, as diretrizes de modelagem, os entregáveis, o controle de qualidade e aspectos relevantes para auditorias. Essencial para gestores, fiscais e agentes de contratação que lidam com obras e projetos em BIM. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1382');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Políticas Públicas e Orçamento Público na Implementação dos Direitos da Pessoa Idosa', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1381', 'gratuito', 'Iniciante', 'Políticas Públicas e Orçamento Público na Implementação dos Direitos da Pessoa Idosa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas Sociais. Carga horária: 30h. Compreenda as relações entre políticas públicas, orçamento e a efetivação dos direitos da pessoa idosa! O curso aborda noções gerais de políticas públicas e de orçamento público, conectando os dois campos na perspectiva da proteção e promoção dos direitos das pessoas idosas. Destinado a conselheiros, gestores e técnicos que atuam com políticas para a terceira idade e desejam fortalecer a alocação de recursos para essa agenda. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1381');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Orçamento das Empresas Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1379', 'gratuito', 'Iniciante', 'Orçamento das Empresas Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 10h. Domine o ciclo orçamentário e os indicadores de desempenho das empresas estatais! O curso aborda conceitos orçamentários e legislação aplicada, o ciclo orçamentário nas estatais e os principais indicadores orçamentários para acompanhamento e controle. Destinado a gestores financeiros, controladores e técnicos das empresas estatais que precisam compreender e operar o orçamento com qualidade, transparência e conformidade legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1379');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Integridade, gestão de riscos e controle em empresas estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1378', 'gratuito', 'Iniciante', 'Integridade, gestão de riscos e controle em empresas estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 30h. Fortaleça a governança, a integridade e o controle nas empresas estatais! O curso aborda os fundamentos de governança e integridade, gestão de riscos com foco em riscos de integridade e as funções de integridade nas empresas estatais brasileiras. Destinado a conselheiros, diretores, auditores e gestores de estatais que desejam estruturar ou aprimorar seus programas de compliance, controle interno e gestão de riscos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1378');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Capacitação em Governança de Dados', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1373', 'gratuito', 'Iniciante', 'Capacitação em Governança de Dados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 25h. Estruture e fortaleça a governança de dados na sua organização! O curso aborda a essência da governança e gestão de dados, o modelo do Poder Executivo Federal, os elementos de um programa de governança em dados e as ações práticas para sua implementação. Destinado a gestores, analistas e profissionais de dados que desejam implementar práticas consistentes de governança de dados para apoiar a tomada de decisão e a transformação digital. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1373');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Desenvolvimento de gestores em políticas para pessoas com deficiência', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1369', 'gratuito', 'Iniciante', 'Desenvolvimento de gestores em políticas para pessoas com deficiência — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 30h. Capacite-se para formular e implementar políticas para pessoas com deficiência com eficácia e sensibilidade! O curso aborda os direitos e a inclusão das PCD no Brasil, a legislação e as práticas inclusivas, a eliminação de barreiras, a participação social e a gestão estratégica das políticas de inclusão. Destinado a gestores e servidores que atuam com políticas para PCD e desejam fortalecer sua capacidade de promover a inclusão no serviço público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1369');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Inovando e enfrentando desafios na gestão das empresas estatais | Programa - Inova: Gestão e Governança de Estatais', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1363', 'gratuito', 'Iniciante', 'Eixo 3 - Inovando e enfrentando desafios na gestão das empresas estatais | Programa - Inova: Gestão e Governança de Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 37h. Inove e enfrente os desafios contemporâneos na gestão das empresas estatais! Este eixo do Programa Inova aborda estratégias de inovação, governança e desempenho aplicadas ao contexto das estatais brasileiras, combinando teoria e prática para capacitar líderes e gestores a promover transformações sustentáveis e responsáveis nas empresas sob controle estatal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1363');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo2 - Transformando a realidade tecnológica e produtiva das empresas estatais | Programa- Inova: Gestão e Governança de Estatais', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1362', 'gratuito', 'Intermediário', 'Eixo2 - Transformando a realidade tecnológica e produtiva das empresas estatais | Programa- Inova: Gestão e Governança de Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 44h. Transforme a realidade tecnológica e produtiva das empresas estatais com inovação e estratégia! Este eixo do Programa Inova aborda as estratégias e ferramentas para modernizar os processos produtivos, incorporar novas tecnologias e elevar a competitividade e o desempenho das empresas sob controle estatal, com foco em inovação responsável e orientada a resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1362');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Mapeando tendências em governança e gestão das empresas estatais | Programa - Inova: Gestão e Governança de Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1361', 'gratuito', 'Intermediário', 'Eixo 1 - Mapeando tendências em governança e gestão das empresas estatais | Programa - Inova: Gestão e Governança de Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 49h. Mapeie as tendências que estão transformando a governança e a gestão das empresas estatais! Este eixo do Programa Inova aborda as principais tendências nacionais e internacionais em governança corporativa, gestão estratégica e desempenho das estatais, capacitando líderes e gestores a antecipar mudanças e posicionar suas organizações de forma mais competitiva e responsável. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1361');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Democratizando BIM: Agentes Públicos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1360', 'gratuito', 'Iniciante', 'Democratizando BIM: Agentes Públicos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 18h. Capacite-se para contratar, fiscalizar e estruturar equipes BIM no setor público! O curso aborda os processos de licitação e contratação de projetos e obras em BIM, a fiscalização de contratos BIM e a formação de equipes BIM em entes públicos. Destinado a gestores, fiscais de contrato, engenheiros e arquitetos do setor público que precisam compreender e aplicar a metodologia BIM nas contratações e obras públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1360');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Resíduos Sólidos', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1356', 'gratuito', 'Iniciante', 'Resíduos Sólidos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Compreenda os desafios do gerenciamento de resíduos sólidos e as alternativas sustentáveis! O curso aborda os problemas dos lixões e aterros sanitários e as políticas de coleta seletiva como caminho para uma gestão mais sustentável dos resíduos urbanos. Destinado a gestores municipais, técnicos ambientais e profissionais que atuam com saneamento e desejam implementar ou aprimorar políticas de resíduos sólidos em seus municípios. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1356');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Recursos Hídricos', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1355', 'gratuito', 'Iniciante', 'Recursos Hídricos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Compreenda a gestão dos recursos hídricos e seus desafios no Brasil! O curso aborda a estrutura de gestão dos recursos hídricos, o tratamento da água, as águas subterrâneas e as questões de poluição, escassez, saúde pública e sustentabilidade. Destinado a gestores ambientais, técnicos e profissionais que atuam com políticas de recursos hídricos e precisam de uma visão integrada dos desafios e instrumentos de gestão da água no Brasil. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1355');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Políticas Públicas para o Saneamento Básico e o Desenvolvimento Sustentável', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1354', 'gratuito', 'Iniciante', 'Políticas Públicas para o Saneamento Básico e o Desenvolvimento Sustentável — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Compreenda a relação entre saneamento básico e desenvolvimento sustentável! O curso aborda como as políticas públicas de saneamento se articulam com os Objetivos do Desenvolvimento Sustentável (ODS) e as diretrizes nacionais para universalização do acesso à água e ao esgotamento sanitário. Destinado a gestores, técnicos e agentes públicos que atuam no planejamento e implementação de políticas de saneamento no âmbito municipal e estadual. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1354');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: ASG na Gestão Pública: caminhos para a sustentabilidade', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1353', 'gratuito', 'Iniciante', 'ASG na Gestão Pública: caminhos para a sustentabilidade — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Incorpore os princípios ASG (Ambiental, Social e de Governança) na gestão pública! O curso aborda as perspectivas de introdução do conceito ASG no setor público, a aplicação dos critérios ASG na gestão pública e a avaliação de impactos e resultados. Destinado a gestores, analistas e servidores que desejam alinhar a administração pública às agendas de sustentabilidade, responsabilidade social e boa governança. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1353');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderança e Gestão no Trabalho Híbrido', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1350', 'gratuito', 'Iniciante', 'Liderança e Gestão no Trabalho Híbrido — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 20h. Desenvolva sua liderança para o contexto do trabalho híbrido com estratégia e humanidade! O curso aborda o trabalho em contextos de mudança, a liderança de equipes híbridas em cenários complexos, o desenvolvimento de habilidades para a liderança 4.0 e a gestão no trabalho híbrido. Destinado a gestores, coordenadores e líderes que precisam adaptar seu estilo de liderança para inspirar e engajar equipes em ambientes presenciais, remotos e híbridos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1350');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Noções básicas de atendimento ao cidadão', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1349', 'gratuito', 'Iniciante', 'Noções básicas de atendimento ao cidadão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Qualidade de Serviços Públicos. Carga horária: 20h. Aprimore o atendimento ao cidadão e eleve a qualidade dos serviços públicos! O curso aborda marketing de serviços aplicado ao setor público, competências essenciais do servidor, ética e responsabilidade, situações extraordinárias, clima organizacional e atendimento não presencial. Destinado a servidores que interagem diretamente com o cidadão e buscam desenvolver habilidades para oferecer um atendimento mais humanizado, eficiente e de qualidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1349');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicação Assertiva: Oratória, Retórica e Técnicas de Apresentação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1347', 'gratuito', 'Intermediário', 'Comunicação Assertiva: Oratória, Retórica e Técnicas de Apresentação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 50h. Desenvolva sua comunicação com assertividade, oratória e impacto! O curso aborda fundamentos da comunicação assertiva, linguagem e contextos culturais, retórica e oratória, linguagem corporal, superação do medo de falar em público, formulação de argumentos e comunicação escrita. Destinado a gestores, servidores e profissionais que desejam se expressar com mais clareza, confiança e persuasão em apresentações, reuniões e comunicações institucionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1347');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Governança das Empresas Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1346', 'gratuito', 'Iniciante', 'Introdução à Governança das Empresas Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 10h. Compreenda os fundamentos da governança corporativa nas empresas estatais brasileiras! O curso aborda o conceito de empresa e propriedade estatal, o sistema de governança corporativa das estatais, o arcabouço legal e as estatais orientadas por missões. Destinado a conselheiros, diretores e gestores de empresas estatais que desejam compreender e fortalecer a governança de suas organizações com base em boas práticas e conformidade legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1346');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de Planos de Entregas e de Trabalho do PGD', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1344', 'gratuito', 'Iniciante', 'Elaboração de Planos de Entregas e de Trabalho do PGD — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Pessoas. Carga horária: 20h. Estruture e elabore os Planos de Entregas e de Trabalho do Programa de Gestão e Desempenho com segurança! O curso aborda a seleção de participantes e assinatura do TCR, a introdução aos planos, a estruturação do Plano de Entregas e do Plano de Trabalho. Destinado a gestores, chefes de unidade e servidores que precisam elaborar, validar e acompanhar os planos no âmbito do PGD com qualidade e conformidade às normas vigentes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1344');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Pessoas nas Empresas Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1342', 'gratuito', 'Iniciante', 'Gestão de Pessoas nas Empresas Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Pessoas. Carga horária: 20h. Inove na gestão de pessoas das empresas estatais com práticas modernas e eficazes! O curso aborda gestão de pessoas e inovação nas estatais e as práticas de gestão inovadora de pessoas aplicadas a esse contexto específico. Destinado a gestores de RH, diretores e líderes de empresas estatais que desejam modernizar seus processos de gestão de pessoas, atrair talentos e construir ambientes de trabalho mais engajadores e produtivos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1342');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Escolas ON, Violências OFF: Educação para Segurança Online de Meninas', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1341', 'gratuito', 'Iniciante', 'Escolas ON, Violências OFF: Educação para Segurança Online de Meninas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 20h. Proteja meninas de violências digitais com educação e engajamento da comunidade escolar! O curso aborda as violências contra meninas e mulheres, as violências facilitadas pela tecnologia, os comportamentos de jovens nas redes sociais, o papel das comunidades escolares no enfrentamento e a educação como ferramenta de prevenção. Destinado a educadores, gestores escolares e profissionais que atuam na proteção de crianças e adolescentes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1341');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direito de Águas à Luz da Governança', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1339', 'gratuito', 'Iniciante', 'Direito de Águas à Luz da Governança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Compreenda o direito das águas e sua governança no contexto brasileiro! O curso aborda o papel do direito na construção da governança das águas doces, a política de recursos hídricos, os instrumentos disponíveis e o Sistema Nacional de Gerenciamento de Recursos Hídricos (Singreh). Destinado a juristas, gestores ambientais e técnicos que atuam com recursos hídricos e precisam de base jurídica sólida para sua gestão e regulação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1339');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Pessoas', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1338', 'gratuito', 'Iniciante', 'Gestão de Pessoas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Pessoas. Carga horária: 20h. Compreenda a evolução e os processos essenciais da gestão de pessoas nas organizações! O curso aborda a evolução histórica da gestão de pessoas e os quatro processos fundamentais: agregar e aplicar, monitorar e desenvolver, recompensar e manter pessoas. Destinado a gestores, líderes e profissionais de RH que desejam compreender a gestão de pessoas de forma sistêmica e desenvolver competências para liderar equipes com mais eficácia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1338');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direitos da Natureza', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1335', 'gratuito', 'Iniciante', 'Direitos da Natureza — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Compreenda o movimento emergente dos Direitos da Natureza e suas implicações jurídicas e éticas! O curso aborda a mudança de paradigma que reconhece direitos à natureza, os pilares filosóficos e jurídicos desse movimento, sua relação com os direitos humanos e estudos de caso nacionais e internacionais. Destinado a juristas, gestores ambientais, educadores e cidadãos interessados em novas abordagens para a proteção do meio ambiente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1335');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratações públicas sustentáveis: da abordagem sistêmica à aplicação prática', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1334', 'gratuito', 'Iniciante', 'Contratações públicas sustentáveis: da abordagem sistêmica à aplicação prática — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Incorpore a sustentabilidade nas contratações públicas de forma sistemática e eficaz! O curso aborda os fundamentos das contratações sustentáveis, governança e instrumentos de gestão pública, princípios e procedimentos das contratações sustentáveis, com um estudo de caso aplicado. Destinado a gestores, pregoeiros e agentes de contratação que desejam alinhar as compras públicas à agenda ambiental, social e de governança. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1334');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: O Papel dos Conselhos de Administração das Empresas Estatais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1332', 'gratuito', 'Iniciante', 'O Papel dos Conselhos de Administração das Empresas Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 20h. Compreenda o papel estratégico dos Conselhos de Administração nas empresas estatais! O curso aborda os fundamentos gerais do Conselho de Administração, o apoio e funcionamento do colegiado e os comitês de assessoramento. Destinado a conselheiros, diretores e gestores de empresas estatais que desejam aprimorar a governança corporativa, fortalecer a tomada de decisão estratégica e garantir conformidade com as boas práticas de gestão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1332');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Migrações, Meio Ambiente e Mudança do Clima no Brasil', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1330', 'gratuito', 'Iniciante', 'Migrações, Meio Ambiente e Mudança do Clima no Brasil — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Compreenda a relação entre mobilidade humana, meio ambiente e mudanças climáticas no Brasil! O curso aborda mobilidade humana no contexto ambiental, dados sobre migrações internas, normativas sobre desastres e mobilidade humana, e a integração dessas temáticas em políticas públicas. Destinado a gestores, pesquisadores e técnicos envolvidos com políticas de migração, meio ambiente e adaptação climática. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1330');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Processamento de Linguagem Natural', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1328', 'gratuito', 'Iniciante', 'Processamento de Linguagem Natural — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Explore as aplicações do Processamento de Linguagem Natural e transforme texto em conhecimento! O curso aborda análise de texto, reconhecimento de fala e sintetização de voz, e automação de dispositivos inteligentes por texto. Destinado a desenvolvedores, cientistas de dados e analistas que desejam implementar soluções de PLN para automatizar processos, extrair informações de documentos e criar interfaces de linguagem natural no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1328');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: E-leadership: how to manage and lead teams in virtual environments', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1326', 'gratuito', 'Iniciante', 'E-leadership: how to manage and lead teams in virtual environments — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 20h. Develop effective leadership skills for remote and virtual work environments! This course covers self-knowledge as the foundation of leadership, the relationship between leaders and their teams, coordination with other teams and best practices in e-leadership. Ideal for managers and leaders seeking to improve their ability to inspire, motivate and coordinate high-performance teams in remote, hybrid or fully virtual contexts. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1326');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Implementando ações pedagógicas no município | Programa - Gestão Municipal: Desenvolvimento Social, Educação e Cultura', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1323', 'gratuito', 'Iniciante', 'Eixo 4 - Implementando ações pedagógicas no município | Programa - Gestão Municipal: Desenvolvimento Social, Educação e Cultura — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 12h. Neste eixo, serão abordados os passos essenciais para a implementação das ações pedagógicas no município e como podemos reconhecer os programas educacionais vigentes, ofertados pelo Governo Federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1323');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Organizando a política municipal de educação | Programa - Gestão Municipal: Desenvolvimento Social, Educação e Cultura', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1322', 'gratuito', 'Iniciante', 'Eixo 3 - Organizando a política municipal de educação | Programa - Gestão Municipal: Desenvolvimento Social, Educação e Cultura — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 10h. Organize a política municipal de educação com planejamento e gestão eficazes! Este eixo do Programa de Gestão Municipal aborda os fundamentos da gestão educacional local, o papel do município no sistema de ensino e as estratégias para estruturar políticas de educação que melhorem a qualidade do ensino, ampliem o acesso e promovam a equidade educacional no âmbito do município. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1322');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 5 - Utilizando ferramentas de gestão para promover Direitos Humanos e Justiça no município | Programa - Gestão Municipal: Justiça e Direitos Humanos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1319', 'gratuito', 'Intermediário', 'Eixo 5 - Utilizando ferramentas de gestão para promover Direitos Humanos e Justiça no município | Programa - Gestão Municipal: Justiça e Direitos Humanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 92h. Utilize ferramentas de gestão para promover Direitos Humanos e Justiça no município! Este eixo capacita gestores municipais a identificar e aplicar instrumentos práticos de gestão que fortaleçam a promoção dos direitos humanos e o acesso à justiça, articulando políticas, serviços e parcerias para uma administração local mais justa, equitativa e comprometida com a dignidade da população. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1319');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Reconhecendo os Direitos Humanos e sua aplicabilidade no município | Programa - Gestão Municipal: Justiça e Direitos Humanos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1317', 'gratuito', 'Intermediário', 'Eixo 3 - Reconhecendo os Direitos Humanos e sua aplicabilidade no município | Programa - Gestão Municipal: Justiça e Direitos Humanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 41h. Reconheça os Direitos Humanos e aplique-os na gestão municipal! Este eixo do Programa de Gestão Municipal aborda os fundamentos dos direitos humanos e como eles se traduzem em políticas, serviços e ações concretas no âmbito do município, capacitando gestores a garantir que a gestão local respeite e promova os direitos humanos de toda a população, com atenção especial aos grupos mais vulneráveis. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1317');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Gerenciando problemas de ordem pública nas cidades e estabelecendo parcerias | Programa - Gestão Municipal: Justiça e Direitos Humanos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1316', 'gratuito', 'Iniciante', 'Eixo 2 - Gerenciando problemas de ordem pública nas cidades e estabelecendo parcerias | Programa - Gestão Municipal: Justiça e Direitos Humanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 7h. Gerencie problemas de ordem pública e construa parcerias estratégicas para cidades mais seguras! Este eixo do Programa de Gestão Municipal aborda as competências e estratégias dos gestores municipais para enfrentar os desafios de segurança e ordem pública, articular parcerias com órgãos estaduais e federais e implementar ações preventivas e de mediação de conflitos no âmbito local. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1316');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da Visão Computacional - IA do Azure', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1305', 'gratuito', 'Iniciante', 'Fundamentos da Visão Computacional - IA do Azure — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 5h. Explore os fundamentos da visão computacional e suas aplicações com a IA do Azure! O curso aborda os conceitos básicos de visão computacional, reconhecimento facial e reconhecimento óptico de caracteres (OCR). Destinado a profissionais de TI, analistas e gestores que desejam compreender e aplicar tecnologias de visão computacional para automatizar processos, melhorar a segurança e modernizar serviços públicos e privados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1305');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Visão Geral da IA no Azure', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1304', 'gratuito', 'Iniciante', 'Visão Geral da IA no Azure — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Explore o universo da Inteligência Artificial na plataforma Azure da Microsoft! O curso aborda o que é inteligência artificial, os princípios básicos do aprendizado de máquina e os conceitos e serviços de IA disponíveis no Azure. Destinado a profissionais de TI, analistas e gestores que desejam compreender as capacidades de IA oferecidas pela nuvem Azure e como aplicá-las para modernizar processos e serviços no setor público e privado. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1304');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Desenvolvendo Pessoas | Programa - Engajamento de Pessoas e Equipes', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1303', 'gratuito', 'Iniciante', 'Eixo 4 - Desenvolvendo Pessoas | Programa - Engajamento de Pessoas e Equipes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 33h. O eixo 4 busca que a liderança desenvolva uma cultura de aprendizagem contínua, promovendo feedback e escuta ativa para identificar e suprir lacunas de competências. Ao oferecer mentoria e oportunidades de troca, fortalece o desenvolvimento da equipe e os resultados organizacionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1303');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Liderando equipes | Programa - Engajamento de Pessoas e Equipes', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1301', 'gratuito', 'Iniciante', 'Eixo 2 - Liderando equipes | Programa - Engajamento de Pessoas e Equipes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 19h. O eixo 2 aborda a capacidade das lideranças em engajar a equipe, inspirar confiança, promover interação e dar autonomia para fortalecer a motivação e os resultados por meio da construção de um ambiente inclusivo e cooperativo, que promova a diversidade, a valorização das individualidades e do senso pertencimento dos colaboradores. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1301');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Conduzindo pessoas | Programa - Engajamento de Pessoas e Equipes', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1300', 'gratuito', 'Iniciante', 'Eixo 1 - Conduzindo pessoas | Programa - Engajamento de Pessoas e Equipes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 32h. O eixo de aprendizagem 1 aborda a capacidade das lideranças públicas em compartilhar o propósito organizacional, alinhar seu estilo de liderança às características da equipe, analisar fatores contextuais e aderir à estratégia institucional, conduzindo as pessoas de forma eficaz ao alcance da visão, missão e objetivos organizacionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1300');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Adotando práticas e estratégias social e ambientalmente responsáveis | Programa - Visão de Futuro', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1299', 'gratuito', 'Intermediário', 'Eixo 3 - Adotando práticas e estratégias social e ambientalmente responsáveis | Programa - Visão de Futuro — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 53h. Adote práticas e estratégias social e ambientalmente responsáveis na gestão pública! Este eixo do Programa de Visão de Futuro aborda como incorporar critérios de responsabilidade social e ambiental às estratégias organizacionais, alinhando a atuação dos gestores públicos às demandas da sustentabilidade e às expectativas da sociedade por uma administração mais ética e comprometida com o futuro. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1299');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: E-liderazgo: cómo gestionar y liderar equipos en ambientes remotos', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1295', 'gratuito', 'Iniciante', 'E-liderazgo: cómo gestionar y liderar equipos en ambientes remotos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 20h. ¡Desarrolla tu liderazgo en entornos remotos y virtuales con efectividad! El curso aborda el autoconocimiento como base del liderazgo, la relación entre líder y liderados, la gestión del equipo y la relación con otros equipos, además de las buenas prácticas del e-liderazgo. Ideal para gestores y líderes hispanohablantes que desean mejorar su capacidad de influir, motivar y coordinar equipos en contextos de trabajo remoto e híbrido. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1295');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Construindo a identidade de líder | Programa - Autoconhecimento e desenvolvimento pessoal', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1294', 'gratuito', 'Intermediário', 'Eixo 3 - Construindo a identidade de líder | Programa - Autoconhecimento e desenvolvimento pessoal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 53h. Construa sua identidade de líder com autoconhecimento e propósito! Este eixo do Programa de Autoconhecimento e Desenvolvimento Pessoal aborda como os gestores podem definir e fortalecer sua identidade de liderança, articulando valores pessoais, estilo de atuação e visão de futuro para exercer uma liderança autêntica, inspiradora e alinhada às demandas contemporâneas do serviço público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1294');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Construindo narrativas de políticas públicas ("policy narratives") | Programa - Comunicação estratégica', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1286', 'gratuito', 'Iniciante', 'Eixo 4 - Construindo narrativas de políticas públicas ("policy narratives") | Programa - Comunicação estratégica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 38h. Construa narrativas poderosas para suas políticas públicas e amplie seu impacto! Este eixo do Programa de Comunicação Estratégica aborda como criar narrativas — policy narratives — que articulam fatos, valores e contexto para persuadir, engajar e mobilizar atores em torno de agendas de políticas públicas. Destinado a gestores, técnicos e comunicadores que precisam comunicar políticas com clareza e poder de convencimento. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1286');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Estabelecendo uma comunicação empática, persuasiva, influente e que inspire confiança | Programa - Comunicação estratégica', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1285', 'gratuito', 'Intermediário', 'Eixo 3 - Estabelecendo uma comunicação empática, persuasiva, influente e que inspire confiança | Programa - Comunicação estratégica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 71h. Estabeleça uma comunicação empática, persuasiva e que inspire confiança! Este eixo do Programa de Comunicação Estratégica aborda as competências relacionais da comunicação — escuta ativa, empatia, persuasão ética e construção de credibilidade —, fundamentais para líderes e gestores que precisam influenciar positivamente suas equipes, parceiros e a sociedade com autenticidade e consistência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1285');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Comunicando propósitos, planos e estratégias | Programa - Comunicação estratégica', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1284', 'gratuito', 'Iniciante', 'Eixo 2 - Comunicando propósitos, planos e estratégias | Programa - Comunicação estratégica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 40h. Comunique propósitos, planos e estratégias com clareza, coerência e impacto! Este eixo do Programa de Comunicação Estratégica aborda como articular e transmitir a visão estratégica da organização de forma que inspire engajamento, alinhe expectativas e mobilize equipes e partes interessadas. Destinado a líderes e gestores que precisam comunicar estratégias complexas de maneira acessível, convincente e orientada a resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1284');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Desenvolvendo e expressando conceitos e ideias | Programa - Comunicação estratégica', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1283', 'gratuito', 'Iniciante', 'Eixo 1 - Desenvolvendo e expressando conceitos e ideias | Programa - Comunicação estratégica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 40h. Desenvolva e expresse conceitos e ideias com clareza e impacto estratégico! Este eixo do Programa de Comunicação Estratégica aborda as bases da comunicação eficaz no contexto da gestão pública: como estruturar o pensamento, articular ideias com coerência e transmitir conceitos de forma clara e persuasiva para diferentes audiências dentro e fora da administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1283');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Orientação para resultados | Programa - Gestão para Resultados', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1282', 'gratuito', 'Intermediário', 'Eixo 2 - Orientação para resultados | Programa - Gestão para Resultados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Pública. Carga horária: 235h. O eixo 2 desenvolve as habilidades relacionadas à alocação de recursos de forma eficaz e gerenciamento de processos e projetos para alcançar as metas institucionais. Aborda a criação de estruturas de monitoramento e avaliação, garantindo ajustes contínuos e transparência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1282');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Políticas Públicas para a Infraestrutura', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1280', 'gratuito', 'Iniciante', 'Políticas Públicas para a Infraestrutura — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Infraestrutura. Carga horária: 20h. Compreenda as políticas públicas de infraestrutura e seu papel no desenvolvimento do Brasil! O curso aborda a introdução à infraestrutura, as políticas de desenvolvimento, a estruturação de projetos de infraestrutura e a relação entre infraestrutura e sustentabilidade. Destinado a gestores, técnicos e formuladores de políticas que atuam com planejamento e implementação de projetos de infraestrutura pública em diferentes setores. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1280');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Agindo na crise | Programa - Gestão de Crises', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1279', 'gratuito', 'Intermediário', 'Eixo 3 - Agindo na crise | Programa - Gestão de Crises — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 62h. O eixo 3 aborda as habilidades de atuar em situações de imprevisibilidade e escassez, utilizar lições apreendidas e demonstrar resiliência quando sob pressão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1279');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Gerindo riscos | Programa - Gestão de Crises', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1277', 'gratuito', 'Intermediário', 'Eixo 1 - Gerindo riscos | Programa - Gestão de Crises — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 85h. O eixo 1 analisa o contexto da organização para realizar o diagnóstico das crises, identificando os riscos e as estratégias para mitigação ou redução dos riscos mapeados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1277');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 6 - Apoiando a implementação das políticas públicas no município | Programa - Gestão Municipal: Tudo o que você precisa saber para os primeiros 100 dias de mandato', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1269', 'gratuito', 'Iniciante', 'Eixo 6 - Apoiando a implementação das políticas públicas no município | Programa - Gestão Municipal: Tudo o que você precisa saber para os primeiros 100 dias de mandato — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 18h. Apoie a implementação das políticas públicas no município com estratégia e articulação! Este eixo do Programa de Gestão Municipal dos primeiros 100 dias aborda como gestores municipais podem articular recursos, parcerias e mecanismos de monitoramento para garantir que as políticas planejadas sejam efetivamente implementadas, superando obstáculos burocráticos e construindo as condições necessárias para a entrega de resultados à população. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1269');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Organizando o orçamento e as finanças para executar o planejamento municipal | Programa - Gestão Municipal: Tudo o que você precisa saber para os primeiros 100 dias de mandato', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1267', 'gratuito', 'Iniciante', 'Eixo 4 - Organizando o orçamento e as finanças para executar o planejamento municipal | Programa - Gestão Municipal: Tudo o que você precisa saber para os primeiros 100 dias de mandato — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 18h. Organize o orçamento e as finanças municipais para executar o planejamento com eficiência! Este eixo do Programa de Gestão Municipal dos primeiros 100 dias capacita prefeitos e gestores a estruturar as finanças locais, compreender os instrumentos orçamentários e garantir que os recursos disponíveis sejam alocados de forma estratégica para viabilizar as prioridades do mandato. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1267');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governo Data-Driven: transformação orientada por dados em governos', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1263', 'gratuito', 'Iniciante', 'Governo Data-Driven: transformação orientada por dados em governos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Transforme seu governo com uma cultura orientada por dados! O curso aborda a construção de um governo transformacional data-driven, a infraestrutura necessária, a tomada de decisão baseada em dados, a governança tecnológica e a transição para um governo mais ágil e adaptável. Essencial para gestores, analistas e líderes do setor público que desejam liderar ou apoiar a transformação digital orientada por dados em suas organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1263');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Redes Complexas', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1258', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Redes Complexas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Explore o mundo das redes complexas e descubra padrões nas conexões entre pessoas, sistemas e organizações! O curso aborda análise de redes, laços fortes e fracos, homofilia, relacionamentos positivos e negativos, análise de links e tipos de redes complexas. Ideal para cientistas de dados, analistas e pesquisadores que desejam aplicar teoria de grafos e análise de redes a problemas reais em ciência de dados e políticas públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1258');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Tratamento de Dados', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1257', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Tratamento de Dados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 2h. Prepare seus dados para análise com técnicas eficazes de tratamento! O curso aborda limpeza de dados — remoção de inconsistências e dados ausentes —, redução de dimensionalidade e técnicas de normalização e discretização. Essencial para analistas e cientistas de dados que desejam garantir qualidade e confiabilidade nos dados antes de aplicar modelos analíticos e de machine learning em projetos de ciência de dados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1257');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança da Informação para Todos', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1256', 'gratuito', 'Iniciante', 'Segurança da Informação para Todos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 24h. Proteja seus dados e sua vida digital com conhecimento em segurança da informação! O curso aborda privacidade e proteção de dados, códigos maliciosos e como se proteger, proteção de dispositivos, cuidados com dados pessoais e corporativos, vida digital e trabalho remoto seguro. Destinado a todos os servidores e profissionais que desejam adotar práticas seguras no uso de tecnologias digitais no trabalho e no cotidiano. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1256');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 6 - Respondendo a um incidente de segurança | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1254', 'gratuito', 'Iniciante', 'Eixo 6 - Respondendo a um incidente de segurança | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 16h. Responda a incidentes de segurança da informação com agilidade e eficácia! Este eixo do Programa de Privacidade e Segurança da Informação aborda os procedimentos de resposta a incidentes de segurança, incluindo detecção, contenção, erradicação, recuperação e comunicação, capacitando equipes de TI e gestores a minimizar danos e restaurar a normalidade com rapidez e conformidade legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1254');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 5 - Protegendo os ativos institucionais e o ambiente tecnológico da organização | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1253', 'gratuito', 'Iniciante', 'Eixo 5 - Protegendo os ativos institucionais e o ambiente tecnológico da organização | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 10h. Proteja os ativos institucionais e o ambiente tecnológico da sua organização contra ameaças digitais! Este eixo do Programa de Privacidade e Segurança da Informação aborda as estratégias, controles e boas práticas para proteger dados, sistemas e infraestruturas críticas, garantindo a continuidade das operações e a segurança das informações no contexto da transformação digital do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1253');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Criando uma estrutura básica em segurança da informação | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1252', 'gratuito', 'Intermediário', 'Eixo 4 - Criando uma estrutura básica em segurança da informação | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 127h. Crie uma estrutura básica de segurança da informação na sua organização! Este eixo do Programa de Privacidade e Segurança da Informação orienta sobre como estabelecer os fundamentos de uma política de segurança da informação, definindo controles, responsabilidades e processos essenciais para proteger os dados e os sistemas da organização contra ameaças internas e externas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1252');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Detalhando as atribuições do encarregado pelo tratamento de dados pessoais | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1251', 'gratuito', 'Iniciante', 'Eixo 3 - Detalhando as atribuições do encarregado pelo tratamento de dados pessoais | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 5h. Compreenda em profundidade as atribuições do encarregado pelo tratamento de dados pessoais! Este eixo do Programa de Privacidade e Segurança da Informação detalha o papel do DPO/Encarregado, suas responsabilidades junto à ANPD, aos titulares e aos agentes de tratamento, e como exercer essa função com competência técnica e jurídica no contexto da LGPD. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1251');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Atuando na governança e na aplicação de medidas de proteção de dados pessoais | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1250', 'gratuito', 'Iniciante', 'Eixo 2 - Atuando na governança e na aplicação de medidas de proteção de dados pessoais | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 34h. Atue com excelência na governança de dados pessoais e na aplicação de medidas de proteção! Este eixo do Programa de Privacidade e Segurança da Informação aborda como estruturar a governança de dados nas organizações, definir papéis e responsabilidades e implementar medidas técnicas e organizacionais para garantir a conformidade com a LGPD e a proteção efetiva dos dados pessoais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1250');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Conhecendo a legislação de proteção de dados pessoais | Programa - Privacidade e Segurança da Informação', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1249', 'gratuito', 'Iniciante', 'Eixo 1 - Conhecendo a legislação de proteção de dados pessoais | Programa - Privacidade e Segurança da Informação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 20h. Conheça a legislação de proteção de dados pessoais e fundamente sua atuação com segurança jurídica! Este eixo do Programa de Privacidade e Segurança da Informação apresenta os marcos legais da proteção de dados — especialmente a LGPD —, os direitos dos titulares e as obrigações dos agentes de tratamento, capacitando servidores e gestores a atuar em conformidade com a legislação vigente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1249');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Expressando ideias e conceitos | Programa - Comunicação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1241', 'gratuito', 'Intermediário', 'Eixo 1 - Expressando ideias e conceitos | Programa - Comunicação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação. Carga horária: 105h. Para desenvolver a competência de comunicação entre servidores públicos, é essencial identificar o contexto da comunicação, compreendendo o ambiente organizacional e o papel que o servidor desempenha, assim como as particularidades do interlocutor. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1241');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Escutar de forma efetiva | Programa - Comunicação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1240', 'gratuito', 'Intermediário', 'Eixo 2 - Escutar de forma efetiva | Programa - Comunicação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação. Carga horária: 80h. A escuta efetiva, fundamental para uma comunicação eficiente, requer que o servidor atue com inteligência emocional, sabendo gerenciar suas próprias emoções e responder de forma equilibrada e adequada às interações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1240');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Interagir de forma produtiva | Programa - Comunicação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1239', 'gratuito', 'Intermediário', 'Eixo 3 - Interagir de forma produtiva | Programa - Comunicação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação. Carga horária: 59h. Para desenvolver a competência de comunicação, é essencial interagir de forma produtiva, o que inclui cultivar relações interpessoais saudáveis e respeitar a diversidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1239');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Adotando conduta moral adequada | Programa - Ética e integridade pública', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1238', 'gratuito', 'Iniciante', 'Eixo 2 - Adotando conduta moral adequada | Programa - Ética e integridade pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 22h. Adote uma conduta moral adequada e fortaleça a integridade no serviço público! Este eixo do Programa de Ética e Integridade Pública aborda os princípios e dilemas éticos da vida pública, os padrões de conduta esperados dos servidores e as estratégias para tomar decisões alinhadas aos valores da ética pública, contribuindo para uma administração mais íntegra, confiável e comprometida com o interesse coletivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1238');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Tomando decisões com base na ética | Programa - Ética e integridade pública', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1237', 'gratuito', 'Intermediário', 'Eixo 1 - Tomando decisões com base na ética | Programa - Ética e integridade pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 60h. Tome decisões com base na ética e fortaleça a integridade no serviço público! Este eixo do Programa de Ética e Integridade Pública desenvolve a capacidade de identificar dilemas éticos, aplicar princípios morais às decisões do cotidiano profissional e construir uma cultura de integridade nas organizações públicas. Destinado a todos os servidores que desejam aprimorar sua capacidade de agir com ética, responsabilidade e compromisso com o interesse coletivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1237');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Avaliação Econômica de EE das Energias Renováveis', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1233', 'gratuito', 'Iniciante', 'Introdução à Avaliação Econômica de EE das Energias Renováveis — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Aprenda a avaliar economicamente projetos de eficiência energética e energias renováveis! O curso aborda avaliação de ciclo de vida, análise econômica, metodologias de análise de investimento e estratégias de melhoria em eficiência energética. Ideal para engenheiros, analistas e gestores que atuam com projetos de energia renovável e eficiência energética e precisam embasar decisões de investimento com rigor técnico e econômico. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1233');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cómo ser más productivo usando Copilot', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1232', 'gratuito', 'Iniciante', 'Cómo ser más productivo usando Copilot — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. ¡Descubre cómo el Copilot puede transformar tu productividad con inteligencia artificial! El curso presenta los primeros pasos para mejorar la productividad usando el Copilot, explora el potencial democratizador de la IA y ofrece consejos prácticos para aprovechar al máximo la herramienta en el trabajo diario. Ideal para profesionales hispanohablantes que desean incorporar la IA de Microsoft de forma eficiente en su rutina laboral. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1232');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de editais em BIM', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1231', 'gratuito', 'Iniciante', 'Elaboração de editais em BIM — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 16h. Elabore editais robustos para contratações de projetos e obras em BIM! O curso aborda a legislação aplicável, os elementos mínimos do edital conforme a Lei nº 14.133/2021, as modalidades de licitação em BIM, a importância dos fluxos de processos BIM no edital, os itens básicos do Termo de Referência e a gestão de contratos BIM. Destinado a agentes de contratação, engenheiros e gestores públicos que conduzem licitações com BIM. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1231');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Analisando dados e evidências | Programa - Resolução de problemas com base em dados', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1225', 'gratuito', 'Intermediário', 'Eixo 1 - Analisando dados e evidências | Programa - Resolução de problemas com base em dados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 87h. O eixo 1 busca aprimorar o letramento em dados, garantindo a disponibilidade e a qualidade das informações e permitindo uma interpretação precisa dos dados disponíveis. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1225');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão e Fiscalização de Contratos, sob o enfoque da Lei nº 14.133/21', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1221', 'gratuito', 'Iniciante', 'Gestão e Fiscalização de Contratos, sob o enfoque da Lei nº 14.133/21 — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 30h. Domine a gestão e fiscalização de contratos administrativos sob o enfoque da Nova Lei de Licitações! O curso aborda a evolução normativa e o planejamento na Lei nº 14.133/21, as prerrogativas administrativas nos contratos e as melhores práticas de gestão contratual. Destinado a fiscais e gestores de contratos que precisam atualizar suas competências e garantir a conformidade e a eficácia na execução dos contratos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1221');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ética en IA', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1219', 'gratuito', 'Iniciante', 'Ética en IA — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 2h. ¡Reflexiona sobre los dilemas éticos de la inteligencia artificial y úsala con responsabilidad! El curso aborda la introducción a la ética en IA, su uso con ética y responsabilidad social, la historia de la IA y sus recursos de accesibilidad, los principios de IA responsable y el uso ético de la IA generativa. Destinado a gestores, servidores y ciudadanos que desean comprender los desafíos éticos y sociales del uso de la IA en el sector público y privado. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1219');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Integrando comunicação e tecnologias digitais | Programa - Mentalidade Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1217', 'gratuito', 'Intermediário', 'Eixo 3 - Integrando comunicação e tecnologias digitais | Programa - Mentalidade Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 95h. Integre comunicação e tecnologias digitais para ampliar o alcance e o impacto da administração pública! Este eixo do Programa de Mentalidade Digital aborda como as ferramentas digitais transformam a comunicação institucional, possibilitando interações mais eficazes, transparentes e centradas no cidadão. Destinado a servidores e gestores que desejam modernizar a comunicação de seus órgãos com uso estratégico das tecnologias disponíveis. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1217');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Integrando processo de gestão e tecnologias digitais | Programa - Mentalidade Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1216', 'gratuito', 'Intermediário', 'Eixo 2 - Integrando processo de gestão e tecnologias digitais | Programa - Mentalidade Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 124h. Integre processos de gestão e tecnologias digitais para modernizar a administração pública! Este eixo do Programa de Mentalidade Digital capacita servidores a identificar como as tecnologias digitais podem ser incorporadas aos processos de gestão, promovendo maior eficiência, transparência e orientação a resultados na entrega de serviços públicos de qualidade para os cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1216');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Aplicando tecnologias digitais na geração de produtos e serviços | Programa - Mentalidade Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1215', 'gratuito', 'Intermediário', 'Eixo 1 - Aplicando tecnologias digitais na geração de produtos e serviços | Programa - Mentalidade Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 227h. Aplique tecnologias digitais para criar e inovar em produtos e serviços públicos! Este eixo do Programa de Mentalidade Digital capacita servidores a identificar oportunidades de uso de tecnologias digitais na geração de valor, explorando ferramentas e práticas para transformar processos e serviços com base em uma mentalidade orientada à inovação e à entrega de melhores resultados para o cidadão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1215');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: La evolución de las búsquedas online', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1213', 'gratuito', 'Iniciante', 'La evolución de las búsquedas online — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. ¡Descubre cómo la inteligencia artificial está transformando las búsquedas en internet! El curso explica qué es la búsqueda online, cómo funcionan los motores de búsqueda, qué cambia con los recursos de IA y cómo usar el Bing Chat para búsquedas más eficientes. Ideal para profesionales y servidores hispanohablantes que desean aprovechar al máximo las herramientas de búsqueda modernas con más agilidad y precisión. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1213');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Estatística Essencial', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1211', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Estatística Essencial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 6h. Domine os fundamentos estatísticos indispensáveis para a ciência de dados! O curso aborda estatística descritiva — medidas de posição, dispersão e visualização de dados — e testes de hipótese para análise inferencial. Essencial para analistas, cientistas de dados e profissionais que trabalham com dados e precisam de base estatística sólida para interpretar resultados, validar conclusões e apoiar decisões baseadas em evidências. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1211');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Disseminadores dos Direitos da Pessoa Idosa', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1209', 'gratuito', 'Iniciante', 'Disseminadores dos Direitos da Pessoa Idosa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Torne-se um disseminador dos direitos da pessoa idosa e contribua para um envelhecimento com dignidade! O curso aborda características sociodemográficas da população idosa brasileira, políticas públicas de direitos humanos e cidadania para a pessoa idosa, e estratégias de prevenção e enfrentamento da violência. Destinado a profissionais, conselheiros e cidadãos que atuam na promoção e defesa dos direitos das pessoas idosas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1209');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Migração e Direitos Humanos na Fronteira', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1208', 'gratuito', 'Iniciante', 'Migração e Direitos Humanos na Fronteira — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda os direitos humanos dos migrantes nas regiões de fronteira e contribua para um atendimento mais digno! O curso aborda os desafios específicos das migrações nas zonas de fronteira, os direitos garantidos pela legislação nacional e internacional e as formas de atuação para proteção e inclusão dos migrantes nessas regiões. Destinado a gestores, profissionais de saúde, educação e assistência social que atuam em municípios fronteiriços. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1208');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Bem viver indígena: Caminhos para a cidadania e o futuro do planeta', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1205', 'gratuito', 'Iniciante', 'Bem viver indígena: Caminhos para a cidadania e o futuro do planeta — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Explore as filosofias do bem viver indígena e sua contribuição para a cidadania e o futuro do planeta! O curso apresenta os saberes, valores e formas de organização dos povos indígenas, conectando-os às discussões contemporâneas sobre sustentabilidade, direitos e cidadania. Destinado a gestores, educadores e cidadãos interessados em compreender as perspectivas indígenas como caminhos alternativos para um desenvolvimento mais justo e sustentável. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1205');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Violência de gênero contra mulheres e meninas: prevenção em três níveis', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1204', 'gratuito', 'Iniciante', 'Violência de gênero contra mulheres e meninas: prevenção em três níveis — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda e previna a violência de gênero contra mulheres e meninas em três níveis de ação! O curso aborda o que é a violência de gênero, sua situação atual, os instrumentos legais de prevenção e as políticas públicas de enfrentamento. Destinado a gestores, profissionais de saúde, educação e segurança pública que desejam atuar na prevenção primária, secundária e terciária da violência de gênero com base em evidências e direitos humanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1204');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direitos Humanos e Meio Ambiente', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1203', 'gratuito', 'Iniciante', 'Direitos Humanos e Meio Ambiente — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda a relação entre direitos humanos e proteção ambiental no contexto brasileiro e internacional! O curso aborda os fundamentos da proteção ambiental e dos direitos humanos, seus impactos e interdependências, as políticas nacionais articuladas e as novas perspectivas dessa relação. Destinado a gestores, juristas e profissionais do meio ambiente que buscam compreender como a proteção ambiental se conecta aos direitos humanos e à justiça socioambiental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1203');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão dos Fundos dos Direitos das Crianças e dos Adolescentes', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1202', 'gratuito', 'Iniciante', 'Gestão dos Fundos dos Direitos das Crianças e dos Adolescentes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 30h. Aprenda a gerir os Fundos dos Direitos da Criança e do Adolescente com eficácia e transparência! O curso aborda as políticas para infâncias e adolescências, o orçamento público, o funcionamento do FDCA e as ferramentas de gestão e controle do fundo. Destinado a gestores, conselheiros e técnicos que gerenciam ou fiscalizam os fundos municipais e estaduais dos direitos da criança e do adolescente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1202');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Trabalho Escravo Doméstico: o que devemos saber?', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1200', 'gratuito', 'Iniciante', 'Trabalho Escravo Doméstico: o que devemos saber? — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda o trabalho escravo doméstico e contribua para seu enfrentamento! O curso aborda o antes e o depois da abolição legal da escravidão, a interseccionalidade no trabalho doméstico remunerado, a escravidão contemporânea e o trabalho doméstico e a política nacional de erradicação do trabalho escravo. Destinado a gestores, profissionais de saúde, educação e assistência social que buscam reconhecer e enfrentar situações de exploração no trabalho doméstico. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1200');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Memória, Escravidão e Reparação Histórica', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1197', 'gratuito', 'Iniciante', 'Memória, Escravidão e Reparação Histórica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos e Cidadania. Carga horária: 30h. O curso "Memória, Escravidão e Reparação Histórica" propõe uma reflexão sobre os processos de reparação como instrumentos de justiça histórica. Ao compreender a história da escravidão e seus impactos no presente, você poderá reconhecer os desafios e as possibilidades de construção de um futuro mais justo e comprometido com a superação das desigualdades raciais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1197');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Enfrentamento e Prevenção ao Discurso de Ódio e Extremismo', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1194', 'gratuito', 'Iniciante', 'Enfrentamento e Prevenção ao Discurso de Ódio e Extremismo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Combata o discurso de ódio e o extremismo com conhecimento, legislação e ação! O curso aborda o conceito de discurso de ódio e extremismo, seus aspectos históricos e normativos, a relação com a democracia e os direitos humanos, como identificar manifestações de ódio, o extremismo no ambiente digital e a legislação e ações governamentais no Brasil. Essencial para gestores, educadores e servidores comprometidos com a democracia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1194');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Letramento Racial aplicado ao Setor Público', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1192', 'gratuito', 'Iniciante', 'Letramento Racial aplicado ao Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 30h. Desenvolva seu letramento racial e contribua para um serviço público mais antirracista! O curso aborda as origens do racismo e das desigualdades raciais no Brasil, os conceitos básicos sobre discriminação, a análise de dados estatísticos sobre desigualdades raciais, o papel do Estado no combate ao racismo e a conduta antirracista no serviço público. Destinado a todos os servidores que desejam atuar com mais consciência e responsabilidade racial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1192');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: O conceito contemporâneo da deficiência e o modelo biopsicossocial', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1191', 'gratuito', 'Iniciante', 'O conceito contemporâneo da deficiência e o modelo biopsicossocial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 30h. Compreenda a deficiência sob uma perspectiva contemporânea baseada nos direitos humanos! O curso aborda a história e os modelos conceituais de deficiência, a deficiência como questão de direitos fundamentais, a avaliação biopsicossocial e os conceitos intrínsecos às suas dimensões. Destinado a gestores, técnicos, profissionais de saúde e servidores que atuam com pessoas com deficiência e desejam uma abordagem mais inclusiva e baseada em direitos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1191');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Seleção, Contratação e Inclusão de Pessoas com Deficiência no Mundo do Trabalho', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1188', 'gratuito', 'Iniciante', 'Seleção, Contratação e Inclusão de Pessoas com Deficiência no Mundo do Trabalho — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 30h. Promova a inclusão de pessoas com deficiência no mercado de trabalho com conhecimento e responsabilidade! O curso aborda a visão geral do tema, as normas de empregabilidade da PCD, a acessibilidade do processo de seleção ao ambiente laboral e o apoio governamental à empregabilidade. Destinado a gestores de RH, líderes e profissionais que desejam estruturar processos inclusivos e ambientes de trabalho acessíveis para pessoas com deficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1188');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Padronização dos Procedimentos de Contratação', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1185', 'gratuito', 'Iniciante', 'Padronização dos Procedimentos de Contratação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Estruture e padronize os processos de contratação pública com segurança jurídica! O curso aborda todas as etapas do planejamento de contratação: documento de formalização da demanda, estudo técnico preliminar, gerenciamento de riscos, pesquisa de preços, termo de referência, minutas de edital e contrato, sistema de registro de preços e checklist de autorização. Essencial para agentes de contratação e gestores de compras públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1185');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: PDCA Aplicado à Educação Básica', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1184', 'gratuito', 'Iniciante', 'PDCA Aplicado à Educação Básica — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 25h. Aplique o ciclo PDCA na gestão educacional e promova a melhoria contínua das escolas! O curso aborda a introdução ao PDCA como método de gestão escolar, o planejamento educacional, a transformação de planos em ações, a verificação dos processos e a ação corretiva, com exemplos práticos aplicados à educação básica. Destinado a gestores escolares, coordenadores pedagógicos e técnicos de secretarias de educação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1184');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de Projetos Escolares com Educação Financeira', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1181', 'gratuito', 'Iniciante', 'Elaboração de Projetos Escolares com Educação Financeira — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 30h. Elabore projetos escolares de educação financeira que promovam o protagonismo dos estudantes! O curso aborda a pedagogia de projetos, os projetos do Aprender Valor, o protocolo de orientação para discussão coletiva e o template para estruturação dos projetos. Destinado a professores e coordenadores pedagógicos que desejam desenvolver projetos de educação financeira significativos, conectados à realidade dos estudantes e alinhados ao currículo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1181');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicando sobre a Mudança do Clima', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1179', 'gratuito', 'Iniciante', 'Comunicando sobre a Mudança do Clima — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 8h. Comunique a mudança do clima com estratégia, clareza e impacto! O curso aborda a construção de uma estratégia de comunicação climática, o conhecimento do público-alvo, a criação de mensagens eficazes e as estratégias para garantir impacto e engajamento. Destinado a comunicadores, gestores e técnicos que precisam sensibilizar audiências diversas sobre os riscos climáticos e promover ações de mitigação e adaptação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1179');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligencia artificial generativa - ESPAÑOL', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1177', 'gratuito', 'Iniciante', 'Inteligencia artificial generativa - ESPAÑOL — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Explore el universo de la Inteligencia Artificial Generativa en español! El curso aborda qué es la IA generativa, sus diferencias respecto a la IA tradicional, la generación de lenguaje natural, la conversión de textos a imágenes y el impacto de la IA en el futuro del mercado laboral. Ideal para profesionales hispanohablantes que desean comprender y comenzar a utilizar herramientas de IA generativa con seguridad y responsabilidad. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1177');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Modelos de Agrupamento', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1174', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Modelos de Agrupamento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Aprenda a identificar grupos e padrões nos dados com técnicas de agrupamento! O curso apresenta os fundamentos do agrupamento não supervisionado e o algoritmo K-Means, amplamente utilizado para segmentação de dados. Ideal para analistas, cientistas de dados e profissionais de tecnologia que desejam aplicar técnicas de clusterização para explorar dados e descobrir estruturas ocultas em conjuntos de dados complexos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1174');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Modelos de Regressão', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1173', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Modelos de Regressão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Domine os modelos de regressão e faça previsões a partir de dados! O curso apresenta os fundamentos dos modelos de regressão aplicados à ciência de dados, essenciais para predição de valores contínuos em análises quantitativas. Ideal para analistas, cientistas de dados e profissionais de TI que desejam ampliar seu repertório de técnicas de aprendizado de máquina para suporte à tomada de decisão baseada em dados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1173');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Descoberta de Tópicos em Texto', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1172', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Descoberta de Tópicos em Texto — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 5h. Extraia conhecimento de textos com técnicas de mineração e descoberta de tópicos! O curso aborda o pré-processamento de texto — limpeza, tokenização e normalização — e técnicas de descoberta de tópicos para identificar padrões e temas em grandes volumes de documentos. Ideal para analistas, cientistas de dados e profissionais que trabalham com análise de documentos, pesquisas e dados textuais não estruturados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1172');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Gerando serviços públicos inclusivos - Programa - Diversidade e Inclusão', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1171', 'gratuito', 'Intermediário', 'Eixo 3 - Gerando serviços públicos inclusivos - Programa - Diversidade e Inclusão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 122h. Gere serviços públicos mais inclusivos e acessíveis para todos! Este eixo do Programa de Diversidade e Inclusão capacita servidores a identificar barreiras, adaptar processos e incorporar a perspectiva da inclusão na entrega de serviços públicos, garantindo que cidadãos de todos os perfis sejam atendidos com dignidade, respeito e equidade. Essencial para equipes que lidam diretamente com o atendimento ao público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1171');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Conjuntos Frequentes', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1166', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Conjuntos Frequentes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Descubra padrões ocultos nos dados com técnicas de conjuntos frequentes e regras de associação! O curso apresenta os fundamentos teóricos e práticos dessa técnica de mineração de dados, amplamente usada para identificar relações entre variáveis em grandes volumes de dados. Ideal para analistas e cientistas de dados que querem ampliar seu repertório de técnicas exploratórias para extração de conhecimento a partir de dados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1166');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gerenciar Projetos com o Microsoft 365', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1162', 'gratuito', 'Iniciante', 'Gerenciar Projetos com o Microsoft 365 — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 4h. Organize e gerencie projetos com eficiência usando as ferramentas do Microsoft 365! O curso apresenta o Lists para gestão de listas e tarefas, o Microsoft Planner para organização de equipes e o Microsoft Project para projetos mais complexos. Ideal para gestores, coordenadores e profissionais que precisam planejar, acompanhar e entregar projetos com mais organização, colaboração e visibilidade sobre prazos e responsabilidades. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1162');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gerenciar Dados com o Microsoft 365', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1160', 'gratuito', 'Iniciante', 'Gerenciar Dados com o Microsoft 365 — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Aprenda a gerenciar e analisar dados com as ferramentas do Microsoft 365! O curso apresenta o Forms para coleta de dados, o Power Automate para automação de processos, o Excel para análise e o Power BI Desktop para visualização. Ideal para servidores e profissionais que desejam usar a suite Microsoft para transformar dados em informação estratégica, com ganho de produtividade e tomada de decisão mais qualificada. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1160');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Políticas Públicas e Governança para a Primeira Infância', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1157', 'gratuito', 'Intermediário', 'Políticas Públicas e Governança para a Primeira Infância — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas Sociais. Carga horária: 45h. Fortaleça as políticas e a governança para a primeira infância com método e evidências! O curso aborda a primeira infância na gestão pública, o plano municipal pela primeira infância, a tomada de decisões baseada em evidências, o monitoramento de políticas, a participação infantil e a comunicação sobre a primeira infância. Destinado a gestores municipais e técnicos que formulam ou implementam políticas para crianças de 0 a 6 anos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1157');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança Cibernética: Controles 13 a 18 do CIS Controls', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1154', 'gratuito', 'Iniciante', 'Segurança Cibernética: Controles 13 a 18 do CIS Controls — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Complete sua formação em segurança cibernética com os controles 13 a 18 do CIS Controls! O curso aborda defesa de rede e conscientização sobre segurança, gestão de provedor de serviços e segurança de aplicações, resposta a incidentes e testes de invasão. Destinado a gestores de TI e analistas de segurança que buscam uma abordagem abrangente e sistemática para proteger os ativos digitais da organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1154');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da Segurança Cibernética - Introdução ao CIS Controls', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1153', 'gratuito', 'Iniciante', 'Fundamentos da Segurança Cibernética - Introdução ao CIS Controls — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Construa uma base sólida em segurança cibernética com os CIS Controls! O curso aborda fundamentos de segurança da informação, a estrutura e fundamentação dos controles, gestão de segurança da informação, principais frameworks e uma visão geral dos CIS Controls. Destinado a gestores, analistas de TI e servidores que desejam entender e aplicar as melhores práticas de segurança cibernética na administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1153');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Utilizando os instrumentos auxiliares das licitações - Programa - Contratações Públicas: Seleção do Fornecedor', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1151', 'gratuito', 'Iniciante', 'Eixo 4 - Utilizando os instrumentos auxiliares das licitações - Programa - Contratações Públicas: Seleção do Fornecedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 22h. Utilize os instrumentos auxiliares das licitações com segurança e eficácia! Este eixo do programa de Contratações Públicas aborda os principais instrumentos que complementam os processos licitatórios, como ata de registro de preços, sistemas de credenciamento e outros mecanismos previstos na Nova Lei de Licitações. Destinado a agentes de contratação, pregoeiros e gestores de compras públicas que buscam ampliar seu repertório técnico. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1151');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 5 - Aplicando sanções administrativas - Programa - Contratações Públicas: Gestão do Contrato', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1149', 'gratuito', 'Iniciante', 'Eixo 5 - Aplicando sanções administrativas - Programa - Contratações Públicas: Gestão do Contrato — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 29h. Aplique sanções administrativas com segurança jurídica e proporcionalidade! Este eixo do Programa de Contratações Públicas aborda os fundamentos e os procedimentos para a aplicação de sanções a fornecedores que descumprem obrigações contratuais, incluindo advertências, multas, impedimento e declaração de inidoneidade, conforme a Nova Lei de Licitações. Essencial para fiscais e gestores de contratos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1149');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Contratando por dispensa ou inexigibilidade - Programa - Contratações Públicas: Seleção do Fornecedor', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1148', 'gratuito', 'Iniciante', 'Eixo 3 - Contratando por dispensa ou inexigibilidade - Programa - Contratações Públicas: Seleção do Fornecedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 38h. Realize contratações diretas por dispensa ou inexigibilidade com segurança jurídica! Este eixo do Programa de Contratações Públicas aborda os fundamentos e os procedimentos das contratações diretas previstas na Nova Lei de Licitações, incluindo as hipóteses legais, a instrução do processo e os cuidados para garantir conformidade e transparência. Essencial para agentes de contratação e gestores de compras. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1148');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Firmando ata de registro de preços - Programa - Contratações Públicas: Seleção do Fornecedor', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1147', 'gratuito', 'Iniciante', 'Eixo 2 - Firmando ata de registro de preços - Programa - Contratações Públicas: Seleção do Fornecedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 6h. Firme atas de registro de preços com segurança jurídica e operacional! Este eixo do Programa de Contratações Públicas aborda os procedimentos para formalização de atas de registro de preços, suas especificidades em relação ao processo licitatório convencional, o gerenciamento da ata e as obrigações das partes. Essencial para agentes de contratação e gestores que utilizam o sistema de registro de preços nas compras da administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1147');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Selecionando fornecedor por licitação -Programa - Contratações Públicas: Seleção do Fornecedor', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1146', 'gratuito', 'Intermediário', 'Eixo 1 - Selecionando fornecedor por licitação -Programa - Contratações Públicas: Seleção do Fornecedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 74h. Selecione fornecedores por licitação com competência e segurança jurídica! Este eixo do Programa de Contratações Públicas: Seleção do Fornecedor capacita agentes de contratação a planejar e conduzir processos licitatórios em conformidade com a Nova Lei de Licitações, garantindo transparência, isonomia e competitividade na escolha dos fornecedores de bens e serviços para a administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1146');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Efetuando Alteração Contratual - Programa - Contratações Públicas: Gestão do Contrato', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1145', 'gratuito', 'Iniciante', 'Eixo 4 - Efetuando Alteração Contratual - Programa - Contratações Públicas: Gestão do Contrato — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 27h. Este eixo faz parte do programa de aprendizagem Contratações Públicas: Gestão do Contrato. Ele aborda as alterações contratuais que são realizadas em contratos, de acordo com necessidades específicas, o que está disciplinado no capítulo VII da Lei n° 14.133, de 1º de abril de 2021 Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1145');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Fiscalizando Contratações de Tecnologia da Informação - Programa - Contratações Públicas: Gestão do Contrato', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1144', 'gratuito', 'Iniciante', 'Eixo 3 - Fiscalizando Contratações de Tecnologia da Informação - Programa - Contratações Públicas: Gestão do Contrato — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 23h. Fiscalize contratos de Tecnologia da Informação com competência técnica e jurídica! Este eixo do Programa de Contratações Públicas aborda as especificidades da fiscalização de contratos de TI, incluindo os principais indicadores de desempenho, os riscos característicos e as boas práticas para garantir que as soluções tecnológicas contratadas atendam aos requisitos de qualidade, segurança e eficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1144');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Instruindo o Processo de Contratação - Programa - Contratações Públicas: Planejamento da Contratação', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1141', 'gratuito', 'Intermediário', 'Eixo 1 - Instruindo o Processo de Contratação - Programa - Contratações Públicas: Planejamento da Contratação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 100h. Instrua o processo de contratação pública com qualidade técnica e conformidade legal! Este eixo do Programa de Contratações Públicas aborda os procedimentos de instrução do processo de contratação, desde a elaboração dos documentos iniciais até a formalização dos atos que compõem o planejamento da contratação, com base na Nova Lei de Licitações e nas normativas do órgão central de compras. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1141');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Seleção de lideranças: como escolher as melhores pessoas', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1135', 'gratuito', 'Iniciante', 'Seleção de lideranças: como escolher as melhores pessoas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Pessoas. Carga horária: 20h. Aprimore seus processos de seleção e escolha os melhores líderes para sua equipe! O curso aborda a contextualização da seleção de lideranças, o planejamento do processo seletivo, as técnicas de entrevista comportamental e a condução do processo de seleção. Destinado a gestores de pessoas, RH e líderes que precisam estruturar processos seletivos mais justos, eficazes e alinhados às necessidades estratégicas da organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1135');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança Cibernética: Controles 7 a 12 do CIS Controls', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1132', 'gratuito', 'Iniciante', 'Segurança Cibernética: Controles 7 a 12 do CIS Controls — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Fortaleça a segurança cibernética da sua organização com os controles 7 a 12 do CIS Controls! O curso aborda gestão de vulnerabilidades e registros de auditoria, proteção contra ameaças de internet e recuperação de dados e gestão da infraestrutura de rede. Destinado a gestores de TI, analistas de segurança e profissionais de tecnologia que desejam implementar boas práticas de segurança cibernética no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1132');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como trabalhar e colaborar On-line', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1131', 'gratuito', 'Iniciante', 'Como trabalhar e colaborar On-line — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 6h. Desenvolva habilidades digitais para colaborar com segurança e eficiência no ambiente online! O curso aborda acesso à informação na internet, participação online com responsabilidade, colaboração usando Outlook e Word, compartilhamento de conteúdo com OneDrive e uso de chat e videochamadas. Indicado para quem deseja ampliar sua capacidade de trabalhar em equipe em ambientes remotos e híbridos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1131');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como Trabalhar com Computadores e Dispositivos Móveis', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1130', 'gratuito', 'Iniciante', 'Como Trabalhar com Computadores e Dispositivos Móveis — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 6h. Desenvolva habilidades digitais fundamentais para o mundo do trabalho atual! O curso aborda noções básicas de computadores e dispositivos, sistemas operacionais, aplicativos, segurança digital, acesso online e criação de conteúdo com Microsoft Office, incluindo Word, Excel e PowerPoint. Ideal para quem está ingressando no mercado de trabalho ou deseja consolidar competências digitais essenciais para a empregabilidade e a produtividade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1130');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Mulheres na liderança: potencialize suas habilidades e impulsione a mudança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1120', 'gratuito', 'Iniciante', 'Mulheres na liderança: potencialize suas habilidades e impulsione a mudança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 30h. Potencialize sua liderança e impulsione a mudança como mulher no espaço público e profissional! O curso aborda a liderança sob perspectiva de gênero, o autoconhecimento, a inteligência emocional, a confiança, a resiliência e a comunicação persuasiva de alto impacto. Destinado a mulheres que exercem ou aspiram a posições de liderança e desejam desenvolver competências para liderar com autenticidade, influência e transformação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1120');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Desenvolvendo a liderança inclusiva - Programa - Fortalecendo Lideranças Antirracistas no Serviço Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1119', 'gratuito', 'Intermediário', 'Eixo 3 - Desenvolvendo a liderança inclusiva - Programa - Fortalecendo Lideranças Antirracistas no Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 140h. Desenvolva sua liderança inclusiva e antirracista no serviço público! Este eixo do Programa de Fortalecimento de Lideranças Antirracistas aborda as competências de liderança necessárias para construir ambientes de trabalho mais equitativos, representativos e livres de discriminação racial, capacitando líderes a promover a diversidade com intencionalidade e consistência em suas equipes e organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1119');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Reconhecendo a construção do racismo no Brasil - Programa - Fortalecendo Lideranças Antirracistas no Serviço Público', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1116', 'gratuito', 'Iniciante', 'Eixo 1 - Reconhecendo a construção do racismo no Brasil - Programa - Fortalecendo Lideranças Antirracistas no Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 18h. Reconheça a construção histórica do racismo no Brasil como passo fundamental para uma liderança antirracista! Este eixo do Programa de Fortalecimento de Lideranças Antirracistas aborda como o racismo foi estruturado ao longo da história brasileira, seus impactos nas instituições e nas relações sociais, e como servidores públicos podem reconhecer e enfrentar essas dinâmicas em suas atuações profissionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1116');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Prevenção e Enfrentamento do Assédio Sexual e Moral', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1115', 'gratuito', 'Iniciante', 'Prevenção e Enfrentamento do Assédio Sexual e Moral — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 6h. Previna e enfrente o assédio sexual e moral no ambiente de trabalho com conhecimento e responsabilidade! O curso aborda o assédio sexual, o processo administrativo disciplinar, o assédio moral, o assédio contra mulheres e a integridade como valor institucional. Destinado a servidores, líderes e gestores que desejam construir ambientes de trabalho mais seguros, respeitosos e livres de qualquer forma de assédio ou violência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1115');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 4 - Gerindo a mudança - Programa - Inovação e Mudança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1096', 'gratuito', 'Iniciante', 'Eixo 4 - Gerindo a mudança - Programa - Inovação e Mudança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 15h. Este eixo aborda o desenvolvimento de habilidades necessárias para a gestão de processos permanentes e sistemáticos de inovação e mudança. Considera os seguintes aspectos a serem desenvolvidos: patrocínio de ideias de vanguarda e de novas formas de trabalhar; responsabilidade assumida pelo líder para a implementação da inovação e as formas de condução de processos de mudança, adotando mudanças incrementais e/ou disruptivas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1096');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 3 - Criando o ambiente para inovação - Programa - Inovação e Mudança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1095', 'gratuito', 'Iniciante', 'Eixo 3 - Criando o ambiente para inovação - Programa - Inovação e Mudança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 40h. Crie o ambiente organizacional propício para a inovação florescer! Este eixo do Programa de Inovação e Mudança aborda como cultivar uma cultura de inovação, remover barreiras sistêmicas, engajar equipes e estruturar processos que incentivem a criatividade e a experimentação. Destinado a gestores e líderes que desejam transformar o ambiente de trabalho em um espaço onde novas ideias sejam bem-vindas, testadas e implementadas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1095');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 2 - Concebendo soluções inovadoras - Programa - Inovação e Mudança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1094', 'gratuito', 'Intermediário', 'Eixo 2 - Concebendo soluções inovadoras - Programa - Inovação e Mudança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 70h. Este eixo possibilita o desenvolvimento de requisitos necessários para a geração e concepção de soluções inovadoras. Para isso, aborda os caminhos para cocriação de soluções com a participação dos usuários dos serviços prestados e, ainda, para desenho, elaboração de protótipos, teste e implementação de soluções inovadoras. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1094');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: A Evolução das buscas Online', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1092', 'gratuito', 'Iniciante', 'A Evolução das buscas Online — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Entenda como a inteligência artificial está transformando as buscas na internet! O curso explica o que é busca online, como funcionam os mecanismos de busca, o que muda com os recursos de IA e como usar o Bing Chat para buscas mais eficientes. Ideal para profissionais, servidores e cidadãos que desejam aproveitar ao máximo as ferramentas de busca modernas, com mais agilidade e precisão na obtenção de informações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1092');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligência Artificial Generativa', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1091', 'gratuito', 'Iniciante', 'Inteligência Artificial Generativa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Explore o universo da Inteligência Artificial Generativa e seu impacto no mundo do trabalho! O curso aborda o que é IA generativa, as diferenças entre IA e IA generativa, geração de linguagem natural, conversão de textos em imagens e as perspectivas da IA para o futuro do mercado de trabalho. Ideal para profissionais, gestores e servidores que desejam compreender e começar a utilizar ferramentas de IA generativa com segurança e consciência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1091');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ética em IA', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1090', 'gratuito', 'Iniciante', 'Ética em IA — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 2h. Reflita sobre os dilemas éticos da inteligência artificial e use a tecnologia com responsabilidade! O curso aborda a introdução à ética em IA, o uso responsável com impacto social, a história da IA e seus recursos de acessibilidade, os princípios de IA responsável e o uso ético da IA generativa. Destinado a gestores, servidores e cidadãos que lidam com ou são impactados por sistemas de inteligência artificial no setor público e privado. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1090');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: A História da IA', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1088', 'gratuito', 'Iniciante', 'A História da IA — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 2h. Compreenda a evolução histórica da inteligência artificial e seus fundamentos tecnológicos! O curso aborda o que são sistemas inteligentes, machine learning, deep learning, processamento de linguagem natural, robôs, internet das coisas, padrões de análise de dados e algoritmos. Destinado a gestores, servidores e profissionais que desejam entender a trajetória da IA e seus principais conceitos para tomar decisões mais informadas sobre o uso dessas tecnologias. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1088');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Eixo 1 - Questionando o convencional - Programa - Inovação e Mudança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1086', 'gratuito', 'Iniciante', 'Eixo 1 - Questionando o convencional - Programa - Inovação e Mudança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 40h. A competência de Inovação e Mudança demanda a curiosidade na busca de experimentação de novas ideias e serviços, questionando-se abordagens convencionais de como trabalhar e conduzir suas ações. Para isso, o eixo aborda a necessidade de identificar as situações que demandam soluções inovadoras. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1086');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Financeira Pessoal', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1076', 'gratuito', 'Iniciante', 'Educação Financeira Pessoal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 40h. Transforme sua relação com o dinheiro e construa uma vida financeira mais equilibrada! O curso aborda a relação pessoal com o dinheiro, estratégias para planejar, poupar e usar o crédito de forma consciente. Indicado para servidores, trabalhadores e cidadãos que desejam desenvolver hábitos financeiros saudáveis, reduzir dívidas e construir uma reserva para o futuro com mais segurança e autonomia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1076');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança Cibernética: Controles 1 a 6 do CIS Controls', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1073', 'gratuito', 'Iniciante', 'Segurança Cibernética: Controles 1 a 6 do CIS Controls — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Implemente controles essenciais de segurança cibernética na sua organização! O curso aborda inventário e controle de ativos corporativos e de software, proteção de dados e configuração segura de ativos, além de gestão de contas e controle de acesso. Destinado a gestores de TI, analistas de segurança e servidores que buscam estruturar uma defesa cibernética robusta com base nas melhores práticas dos CIS Controls. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1073');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Formação de Professores do Programa Aprender Valor', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1072', 'gratuito', 'Iniciante', 'Formação de Professores do Programa Aprender Valor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 40h. Capacite-se para implementar o Programa Aprender Valor em sala de aula! O curso aborda a introdução ao programa e o percurso de Aprender Valor na sala de aula, com conteúdos e estratégias para integrar a educação financeira ao currículo. Destinado a professores da educação básica que desejam desenvolver a autonomia financeira e a cidadania de seus alunos por meio de projetos pedagógicos inovadores e contextualizados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1072');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Formação de Gestores Escolares do Programa Aprender Valor', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1071', 'gratuito', 'Iniciante', 'Formação de Gestores Escolares do Programa Aprender Valor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 40h. Capacite gestores escolares para implementar o Programa Aprender Valor com excelência! O curso aborda a gestão da aprendizagem e o trabalho colaborativo, a gestão do currículo com ênfase em temas contemporâneos transversais e os projetos escolares com educação financeira. Destinado a diretores, coordenadores pedagógicos e gestores escolares que desejam integrar a educação financeira ao currículo de forma pedagógica e transformadora. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1071');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Planejamento e Orçamento: Primeira Infância', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1069', 'gratuito', 'Iniciante', 'Planejamento e Orçamento: Primeira Infância — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 25h. Incorpore a primeira infância no planejamento e orçamento público com método e evidências! O curso aborda a introdução à primeira infância, os Planos Plurianuais estaduais, as questões relevantes no planejamento e orçamento para esse público e como estruturar a primeira infância no orçamento. Destinado a gestores, analistas e técnicos de planejamento e orçamento que desejam garantir a prioridade à primeira infância nos instrumentos de planejamento governamental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1069');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Prevenção e Detecção de Cartéis em Licitações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1068', 'gratuito', 'Iniciante', 'Prevenção e Detecção de Cartéis em Licitações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Previna e detecte cartéis nas licitações públicas com conhecimento e método! O curso aborda concorrência e cartéis em licitações, a identificação e denúncia de práticas anticompetitivas e as estratégias de prevenção. Destinado a agentes de contratação, gestores de compras, controladores e auditores que buscam identificar sinais de cartel nos processos licitatórios e adotar medidas preventivas para garantir a competitividade e a lisura das contratações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1068');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança Pública e Violência contra Mulheres e Meninas: do Enfrentamento ao Protagonismo Feminino na Prevenção e Redução da Violência', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1066', 'gratuito', 'Iniciante', 'Segurança Pública e Violência contra Mulheres e Meninas: do Enfrentamento ao Protagonismo Feminino na Prevenção e Redução da Violência — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 40h. Fortaleça a atuação da segurança pública no enfrentamento da violência contra mulheres e meninas! O curso aborda o protagonismo feminino, as estruturas de governança, as políticas baseadas em evidência e os aspectos operacionais para o enfrentamento da violência. Destinado a profissionais de segurança pública que buscam aprimorar sua atuação com base em direitos humanos, perspectiva de gênero e estratégias efetivas de prevenção e resposta. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1066');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Tecnologias Aplicadas à Segurança Pública', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1061', 'gratuito', 'Intermediário', 'Tecnologias Aplicadas à Segurança Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 50h. Explore as tecnologias que estão transformando a segurança pública no Brasil! O curso aborda reconhecimento facial, policiamento preditivo, câmeras corporais e as principais ferramentas tecnológicas disponíveis no MJSP. Destinado a gestores, comandantes e profissionais de segurança pública que desejam compreender e utilizar tecnologias de forma estratégica, ética e eficaz para melhorar a prevenção ao crime e a resposta policial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1061');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Boas Práticas para o Licenciamento Municipal de Obras e Construções', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1060', 'gratuito', 'Iniciante', 'Boas Práticas para o Licenciamento Municipal de Obras e Construções — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Pública. Carga horária: 10h. Aprimore o licenciamento municipal de obras com boas práticas e simplificação! O curso aborda a legislação e a regulação urbana, o mapeamento e melhoria dos fluxos do processo de licenciamento e a racionalização dos exames documentais. Destinado a gestores, técnicos de fiscalização e analistas municipais que buscam simplificar e modernizar os processos de licenciamento de obras, reduzindo custos para os cidadãos e aumentando a eficiência da máquina pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1060');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Turismo Cultural', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1057', 'gratuito', 'Iniciante', 'Educação Patrimonial e Turismo Cultural — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Integre educação patrimonial e turismo cultural para valorizar o patrimônio e desenvolver os territórios! O curso aborda a relação entre educação patrimonial e turismo cultural, explorando como o patrimônio pode ser dinamizado de forma sustentável e pedagógica para o desenvolvimento local e a formação de visitantes mais conscientes e respeitosos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1057');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Soluções Preditivas Baseadas em Dados com o Uso do R e do Python', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1049', 'gratuito', 'Iniciante', 'Soluções Preditivas Baseadas em Dados com o Uso do R e do Python — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Desenvolva soluções preditivas com aprendizado de máquina usando R e Python! O curso aborda os principais tipos de aprendizado de máquina, critérios para seleção de técnicas e algoritmos e o desenvolvimento prático de soluções preditivas. Destinado a cientistas de dados, analistas e profissionais de tecnologia que desejam aplicar machine learning para geração de predições e suporte à tomada de decisão baseada em dados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1049');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Análise de Negócios no Desenvolvimento de Soluções Baseadas em Dados', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1048', 'gratuito', 'Iniciante', 'Análise de Negócios no Desenvolvimento de Soluções Baseadas em Dados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Aplique a análise de negócios no desenvolvimento de soluções baseadas em dados! O curso aborda o que é análise de negócios, noções básicas e técnicas de elicitação de requisitos e a análise de negócios na prática. Destinado a analistas, cientistas de dados e gestores de projetos que buscam estruturar melhor os requisitos e necessidades do negócio antes de desenvolver soluções de dados, garantindo que as soluções entregues realmente resolvam os problemas reais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1048');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Orçamento e Finanças Públicas Municipais', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1045', 'gratuito', 'Iniciante', 'Orçamento e Finanças Públicas Municipais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 20h. Domine os fundamentos do orçamento e das finanças públicas municipais! O curso aborda aspectos gerais das finanças públicas municipais, o sistema orçamentário brasileiro, o processo orçamentário e as contribuições do Legislativo Municipal. Destinado a vereadores, gestores, técnicos e assessores municipais que precisam compreender e atuar com qualidade no ciclo orçamentário e na gestão financeira do município. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1045');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução ao Processamento de Linguagem Natural', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1043', 'gratuito', 'Iniciante', 'Introdução ao Processamento de Linguagem Natural — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Domine os fundamentos do Processamento de Linguagem Natural e suas aplicações! O curso aborda a introdução ao PLN, a preparação de dados, as principais aplicações e implementações em Python e R. Destinado a cientistas de dados, analistas e desenvolvedores que desejam aplicar técnicas de PLN para automatizar a análise de textos, extrair informações de documentos e desenvolver soluções de linguagem natural no setor público e privado. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1043');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Atuação do Encarregado na LGPD: A Função de Orientar', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1041', 'gratuito', 'Iniciante', 'Atuação do Encarregado na LGPD: A Função de Orientar — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 15h. Exerça com excelência a função de Encarregado pelo tratamento de dados pessoais! O curso aborda o papel estratégico do encarregado, como orientar sobre gestão da privacidade, orientações para as áreas de TI e de gestão de pessoas. Destinado a DPOs, encarregados de dados e profissionais que exercem ou assumirão essa função nas organizações, capacitando-os a cumprir com eficácia e segurança suas responsabilidades perante a LGPD e a ANPD. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1041');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como Produzir Cursos à Distância com Inteligência Artificial Generativa', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1039', 'gratuito', 'Iniciante', 'Como Produzir Cursos à Distância com Inteligência Artificial Generativa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 25h. Produza cursos à distância de qualidade com o apoio da IA generativa! O curso aborda os fundamentos e possibilidades da IA, o uso da IA generativa na produção de cursos EaD e a ética e o futuro dessa prática. Destinado a designers instrucionais, professores e gestores de educação corporativa que buscam incorporar ferramentas de IA generativa no processo de criação de cursos online, acelerando a produção sem abrir mão da qualidade pedagógica e da responsabilidade ética. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1039');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Caminhos para a Sustentabilidade: ESG e Políticas Públicas', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1038', 'gratuito', 'Iniciante', 'Caminhos para a Sustentabilidade: ESG e Políticas Públicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Incorpore a agenda ESG na gestão pública e avance rumo à sustentabilidade! O curso aborda os conceitos e trajetórias ligados ao ESG, os aspectos ambientais, sociais e de governança na administração pública, o desenvolvimento sustentável como política pública e os desafios da implementação da pauta ESG no setor público. Destinado a gestores e analistas que desejam alinhar a atuação pública às agendas internacionais de sustentabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1038');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Marco Legal das Startups - Gerenciando Contratos Públicos para Solução Inovadora', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1034', 'gratuito', 'Iniciante', 'Marco Legal das Startups - Gerenciando Contratos Públicos para Solução Inovadora — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 25h. Gerencie contratos públicos para soluções inovadoras com segurança e eficácia! O curso aborda o processo do edital à celebração do Contrato Público de Solução Inovadora, a gestão do CPSI celebrado, como criar produtos inovadores e as responsabilidades e decisões dos envolvidos. Destinado a gestores e agentes de contratação que conduzem ou acompanham contratos de inovação com startups no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1034');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Educação Museal: Relações e Interconexões possíveis', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1026', 'gratuito', 'Iniciante', 'Educação Patrimonial e Educação Museal: Relações e Interconexões possíveis — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 10h. Explore as relações e interconexões entre educação patrimonial e educação museal! O curso apresenta os pontos de convergência e complementaridade entre esses dois campos, mostrando como as práticas museais e patrimoniais se articulam para enriquecer os processos educativos e a valorização do patrimônio cultural. Destinado a educadores, museólogos e gestores culturais que atuam em museus, escolas e espaços culturais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1026');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Arte', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1025', 'gratuito', 'Iniciante', 'Educação Patrimonial e Arte — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Integre arte e patrimônio cultural no processo educativo! O curso aborda a relação entre educação patrimonial e arte, explorando como as expressões artísticas — visuais, cênicas, musicais — podem ser utilizadas como ferramentas pedagógicas para a valorização e o reconhecimento do patrimônio cultural brasileiro. Destinado a professores, educadores culturais e gestores que desejam enriquecer o processo de ensino-aprendizagem com a dimensão artística do patrimônio. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1025');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cerrado: eixo pedagógico e patrimônio', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1024', 'gratuito', 'Iniciante', 'Cerrado: eixo pedagógico e patrimônio — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 10h. Valorize o Cerrado como patrimônio natural e recurso pedagógico! O curso aborda o Cerrado como eixo pedagógico e patrimônio cultural e ambiental, apresentando sua biodiversidade, importância ecológica e potencial educativo para a formação de cidadãos mais conscientes e comprometidos com a preservação desse bioma único e ameaçado. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1024');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Instrumentos de Desenvolvimento Urbano Sustentável - Financiamento', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1023', 'gratuito', 'Iniciante', 'Instrumentos de Desenvolvimento Urbano Sustentável - Financiamento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 20h. Domine os instrumentos de financiamento do desenvolvimento urbano sustentável! O curso aborda o contexto federal e a experiência brasileira no financiamento fiscal do DUS, o planejamento e execução do orçamento público, os tipos de fundos e as fontes complementares de recursos para projetos urbanos sustentáveis. Destinado a gestores, técnicos e especialistas em desenvolvimento urbano que buscam ampliar o financiamento para projetos de cidades mais sustentáveis. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1023');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governança Colaborativa para a Primeira Infância', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1022', 'gratuito', 'Iniciante', 'Governança Colaborativa para a Primeira Infância — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas Sociais. Carga horária: 25h. Implemente a governança colaborativa para a primeira infância nos estados e municípios! O curso aborda a introdução às políticas de primeira infância, o tripé da governança colaborativa e a implementação da política estadual colaborativa. Destinado a gestores, articuladores e técnicos que atuam com a agenda da primeira infância e buscam estruturar modelos de governança que integrem diferentes órgãos e políticas em torno das necessidades das crianças de 0 a 6 anos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1022');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Patrimônio Material', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1021', 'gratuito', 'Iniciante', 'Educação Patrimonial e Patrimônio Material — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Incorpore o patrimônio material na educação e valorize a herança cultural brasileira! O curso aborda os fundamentos da educação patrimonial aplicados ao patrimônio material — edificações, monumentos, sítios arqueológicos — e suas potencialidades pedagógicas para escolas e comunidades. Destinado a professores, agentes culturais e gestores do patrimônio que desejam utilizar o patrimônio material como recurso educativo e de valorização da identidade cultural. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1021');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Diversidade', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1020', 'gratuito', 'Iniciante', 'Educação Patrimonial e Diversidade — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Incorpore a diversidade na educação patrimonial e valorize a pluralidade cultural brasileira! O curso aborda a relação entre educação patrimonial e diversidade, reconhecendo as diferentes perspectivas culturais, étnicas e sociais que compõem o patrimônio brasileiro. Destinado a professores, agentes culturais e gestores que desejam desenvolver práticas educativas que valorizem e celebrem a diversidade cultural como componente fundamental do patrimônio nacional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1020');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Instrumentos de Desenvolvimento Urbano Sustentável - Informações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1018', 'gratuito', 'Iniciante', 'Instrumentos de Desenvolvimento Urbano Sustentável - Informações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Políticas Públicas. Carga horária: 25h. Utilize sistemas de informação e dados abertos para qualificar o desenvolvimento urbano sustentável! O curso aborda conceitos e definições, aquisição de dados, sistemas de informações geográficas e dados abertos aplicados ao desenvolvimento urbano. Destinado a gestores, técnicos e analistas urbanos que buscam incorporar dados geoespaciais e abertos na análise, no planejamento e no monitoramento das políticas de desenvolvimento urbano nos municípios. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1018');
