INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Modelo de Cinco Dimensões Aplicado a Projetos de Investimento', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1014', 'gratuito', 'Iniciante', 'Modelo de Cinco Dimensões Aplicado a Projetos de Investimento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 20h. Avalie projetos de investimento com rigor e completude usando o Modelo de Cinco Dimensões! O curso apresenta o contexto e aplicabilidade do modelo e sua aplicação às dimensões estratégica, econômica, comercial, financeira e gerencial. Essencial para analistas, gestores e técnicos de planejamento que precisam avaliar a viabilidade e a qualidade de projetos de investimento público com critérios estruturados e consistentes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1014');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Serviços no Portal Gov.br: Conceitos e Gestão de Cadastros', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1013', 'gratuito', 'Iniciante', 'Serviços no Portal Gov.br: Conceitos e Gestão de Cadastros — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Gerencie os serviços no Portal Gov.br com qualidade e precisão! O curso aborda os aspectos gerais da transformação digital, a Carta de Serviços na APF, os serviços no portal e a gestão dos cadastros. Destinado a servidores e gestores responsáveis pelo cadastramento e atualização de serviços públicos no Portal Gov.br, garantindo que as informações estejam completas, claras e úteis para o cidadão que acessa o portal em busca de orientações sobre os serviços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1013');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Metodologias Educacionais Aplicadas à Temática Água e Sustentabilidade', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1012', 'gratuito', 'Iniciante', 'Metodologias Educacionais Aplicadas à Temática Água e Sustentabilidade — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 25h. Aplique metodologias educacionais inovadoras para trabalhar água e sustentabilidade! O curso aborda o cenário global da temática hídrica, fundamentos das metodologias educacionais para a sustentabilidade, programas ambientais na escola, água como matriz ecopedagógica e a Agenda 2030 e o Desenvolvimento Sustentável. Ideal para educadores, técnicos de meio ambiente e gestores que promovem educação ambiental em contextos formais e não formais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1012');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educación Museística: Marco Teórico, Conceptos e Investigación', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/1009', 'gratuito', 'Iniciante', 'Educación Museística: Marco Teórico, Conceptos e Investigación — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 25h. ¡Profundice en los fundamentos teóricos y la investigación en educación museística en español! El curso aborda las principales teorías y conceptos de la educación en museos y las posibilidades y métodos de investigación en el campo. Ideal para educadores, museólogos y profesionales de museos hispanohablantes que desean fortalecer su práctica pedagógica con base en referentes teóricos actualizados del ámbito de la educación museal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/1009');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Ciência de Dados - Conceitos e Ferramentas', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/976', 'gratuito', 'Iniciante', 'Introdução à Ciência de Dados - Conceitos e Ferramentas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 4h. Dê os primeiros passos na ciência de dados com uma visão completa de seus conceitos e ferramentas! O curso aborda o papel do cientista de dados, diferenças entre BI, DW e mineração de dados, aprendizado de máquina, fontes e preparação de dados, e ferramentas como o KNIME. Ideal para profissionais que desejam ingressar na área de dados ou aprofundar sua compreensão do ecossistema de ciência de dados aplicado ao setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/976');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos de governança e boas práticas da regulação', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/975', 'gratuito', 'Iniciante', 'Fundamentos de governança e boas práticas da regulação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Regulação. Carga horária: 30h. Aprofunde-se nos fundamentos da governança regulatória e nas boas práticas internacionais! O curso aborda a introdução à governança regulatória, sua avaliação e mensuração, as dimensões e princípios da boa regulação, com aplicação ao Novo Marco do Saneamento e estudos de caso de boas práticas nacionais e internacionais. Essencial para dirigentes, técnicos e analistas de agências reguladoras e órgãos de regulação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/975');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Patrimônio Imaterial', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/973', 'gratuito', 'Iniciante', 'Educação Patrimonial e Patrimônio Imaterial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Valorize o patrimônio imaterial por meio da educação patrimonial! O curso aborda as especificidades do patrimônio cultural imaterial — saberes, festas, formas de expressão, lugares e celebrações — e as práticas pedagógicas que promovem seu reconhecimento e transmissão. Destinado a professores, técnicos do IPHAN e agentes culturais que desejam integrar o patrimônio imaterial ao processo educativo como forma de valorizar e preservar as tradições culturais vivas do Brasil. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/973');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial e Inventários Participativos', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/972', 'gratuito', 'Iniciante', 'Educação Patrimonial e Inventários Participativos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Realize inventários participativos do patrimônio cultural com método e engajamento comunitário! O curso aborda a educação patrimonial como base metodológica para os inventários participativos e as estratégias de envolvimento das comunidades na identificação e registro do patrimônio cultural local. Destinado a educadores, agentes culturais, técnicos e gestores do patrimônio que buscam metodologias participativas para valorizar e proteger a memória e a identidade cultural. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/972');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Patrimonial: currículo, conceito e temas', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/971', 'gratuito', 'Iniciante', 'Educação Patrimonial: currículo, conceito e temas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Incorpore a educação patrimonial ao currículo escolar com consistência teórica e prática! O curso aborda os fundamentos da educação patrimonial, seus conceitos centrais e os temas transversais que a conectam às diferentes áreas do conhecimento. Destinado a professores, coordenadores pedagógicos e gestores culturais que desejam integrar o patrimônio cultural ao processo educativo, promovendo o reconhecimento, a valorização e a preservação da identidade cultural brasileira. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/971');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicação para Reguladores - GR6', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/959', 'gratuito', 'Iniciante', 'Comunicação para Reguladores - GR6 — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 25h. Aprimore a comunicação estratégica no contexto regulatório! O curso aborda a importância da comunicação para reguladores, as competências e responsabilidades comunicacionais, o planejamento e a gestão estratégica do relacionamento e as boas práticas de comunicação para agências reguladoras. Destinado a dirigentes, técnicos e assessores de agências reguladoras que desejam fortalecer a transparência e o engajamento com a sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/959');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Equipes Híbridas e Desafios para a Cultura Organizacional', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/957', 'gratuito', 'Iniciante', 'Gestão de Equipes Híbridas e Desafios para a Cultura Organizacional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 25h. Lidere equipes híbridas e construa uma cultura organizacional forte em tempos de transformação! O curso aborda a transição do mundo do trabalho, a cultura organizacional como diferencial, a jornada da liderança híbrida e o bem-estar de times e líderes. Destinado a gestores, líderes e profissionais de RH que precisam adaptar sua liderança e a cultura de suas organizações para o novo contexto híbrido de trabalho com foco em engajamento e desempenho. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/957');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inovando na Gestão de Projetos', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/956', 'gratuito', 'Iniciante', 'Inovando na Gestão de Projetos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 25h. Inove na gestão de projetos com abordagens ágeis e ferramentas modernas! O curso combina a jornada de conhecimento — aspectos conceituais sobre inovação em projetos — com a jornada prática e ferramental, com aplicação direta de metodologias. Destinado a gestores e profissionais que desejam modernizar sua gestão de projetos, incorporando práticas ágeis, design thinking e outras abordagens inovadoras para entregar valor com mais velocidade e eficácia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/956');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direitos dos Imigrantes e Orientações para o Atendimento', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/955', 'gratuito', 'Iniciante', 'Direitos dos Imigrantes e Orientações para o Atendimento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Qualifique o atendimento a imigrantes com base em seus direitos e na legislação vigente! O curso aborda as migrações internacionais, os direitos no contexto internacional e brasileiro, as vulnerabilidades específicas dos imigrantes e as orientações práticas para um atendimento digno e eficaz. Destinado a servidores, assistentes sociais e gestores que atendem imigrantes e buscam uma abordagem mais humanizada, informada e baseada em direitos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/955');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Museal II - Histórico e Práticas', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/954', 'gratuito', 'Iniciante', 'Educação Museal II - Histórico e Práticas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 25h. Aprofunde-se no histórico e nas práticas da educação museal! O curso aborda a história da educação museal no Brasil e no mundo e apresenta experiências e práticas educativas realizadas em museus, destacando abordagens inovadoras e inclusivas. Destinado a educadores, museólogos e profissionais de museus que desejam aprimorar sua prática pedagógica com base em referências históricas e experiências concretas do campo da educação museal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/954');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Museal I - Referencial Teórico', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/953', 'gratuito', 'Iniciante', 'Educação Museal I - Referencial Teórico — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 25h. Aprofunde-se nos fundamentos teóricos da educação museal! O curso aborda as principais teorias e conceitos que sustentam a prática educativa em museus, além das possibilidades e métodos de pesquisa em educação museal. Destinado a educadores, museólogos e profissionais de museus que desejam aprimorar sua prática pedagógica com base em referenciais teóricos sólidos e atualizados do campo da educação museal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/953');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Marco Legal das Startups - Contratando Inovação no Setor Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/951', 'gratuito', 'Iniciante', 'Marco Legal das Startups - Contratando Inovação no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 25h. Utilize o Marco Legal das Startups para contratar inovação no setor público! O curso aborda os aspectos relevantes sobre inovação, o Contrato Público de Solução Inovadora com suas previsões normativas e etapas, e as boas práticas nas contratações de inovação. Essencial para gestores e técnicos de compras públicas que desejam explorar o potencial do ecossistema de startups para modernizar serviços e soluções governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/951');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Business Intelligence no Sistema Integrado de Planejamento e Orçamento - Siop BI', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/946', 'gratuito', 'Iniciante', 'Business Intelligence no Sistema Integrado de Planejamento e Orçamento - Siop BI — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 30h. Utilize o poder do Business Intelligence para qualificar o planejamento e o orçamento público! O curso apresenta conceitos de BI, o funcionamento do SIOP-BI, uma introdução ao SIOP e as funcionalidades do extrator para consultas e análises. Essencial para analistas, técnicos e gestores de planejamento e orçamento que desejam explorar dados orçamentários com mais agilidade, precisão e capacidade analítica. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/946');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Novo Regime Fiscal e o Teto de Gastos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/945', 'gratuito', 'Iniciante', 'Novo Regime Fiscal e o Teto de Gastos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 30h. Compreenda o Novo Regime Fiscal e as regras do teto de gastos públicos! O curso aborda noções de finanças públicas e as regras fiscais aplicadas ao Novo Regime Fiscal. Destinado a gestores, analistas de orçamento e servidores que atuam com planejamento e execução financeira e precisam compreender os fundamentos e as implicações práticas das regras fiscais vigentes para a gestão responsável dos recursos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/945');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Despesas por Função COFOG', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/944', 'gratuito', 'Iniciante', 'Despesas por Função COFOG — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 40h. Compreenda a classificação funcional das despesas públicas segundo o padrão internacional COFOG! O curso aborda a Classificação das Funções de Governo, a comparação com a Portaria SOF nº 42/1999, a classificação econômica da despesa conforme o GFSM 2014, a classificação institucional e a experiência brasileira com comparações internacionais. Essencial para analistas de orçamento e finanças públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/944');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Formação de Pregoeiros - Teoria', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/942', 'gratuito', 'Iniciante', 'Formação de Pregoeiros - Teoria — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Capacite-se para atuar com excelência como pregoeiro no pregão eletrônico! O curso aborda os fundamentos do pregão como modalidade licitatória, as fases do pregão eletrônico e a operação do sistema em suas partes 1 e 2. Destinado a pregoeiros, agentes de contratação e servidores que desejam dominar os procedimentos do pregão eletrônico e conduzir processos licitatórios com segurança jurídica e eficiência operacional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/942');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de termos de referência para contratação de bens e serviços na Nova Lei de Licitações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/941', 'gratuito', 'Iniciante', 'Elaboração de termos de referência para contratação de bens e serviços na Nova Lei de Licitações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Elabore Termos de Referência robustos e conformes à Nova Lei de Licitações! O curso aborda o processo de contratação pública e as técnicas e requisitos para elaboração de termos de referência para bens e serviços. Destinado a gestores, agentes de contratação e servidores que precisam dominar a elaboração desse instrumento essencial para garantir contratações mais claras, precisas e alinhadas à Lei nº 14.133/2021. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/941');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso de dados para a gestão do transporte público coletivo', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/937', 'gratuito', 'Iniciante', 'Uso de dados para a gestão do transporte público coletivo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Transportes e Mobilidade Urbana. Carga horária: 10h. Utilize dados abertos para qualificar a gestão do transporte público coletivo! O curso aborda por que usar e abrir dados de transporte, as boas práticas de contratos para gestão de dados e os dados abertos e a segurança de dados no transporte público. Destinado a gestores, técnicos e analistas de mobilidade urbana que buscam usar dados operacionais para melhorar o planejamento, o monitoramento e a qualidade dos serviços de transporte coletivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/937');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governo Integrado: Como Construí-lo?', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/935', 'gratuito', 'Iniciante', 'Governo Integrado: Como Construí-lo? — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Construa um governo integrado com interoperabilidade, dados e normativas alinhadas! O curso aborda o que é um governo digital, os conceitos de integração e interoperabilidade, os normativos e orientações para um governo integrado e as arquiteturas de referência. Destinado a gestores, analistas de TI e técnicos que precisam compreender e implementar a integração entre sistemas e serviços do governo para melhorar a eficiência e a experiência do cidadão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/935');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Controle em 5 Dimensões', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/931', 'gratuito', 'Iniciante', 'Controle em 5 Dimensões — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 30h. Estruture um sistema de controle interno robusto com base no modelo das 5 Dimensões! O curso aborda a visão global do modelo, o ambiente de controle, a avaliação de riscos, as atividades de controle, a informação e comunicação e as atividades de monitoramento. Destinado a auditores, controladores e gestores que buscam implementar práticas de controle interno consistentes e alinhadas às melhores referências nacionais e internacionais de governança e integridade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/931');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Estatística para Análise de Dados na Administração Pública', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/930', 'gratuito', 'Iniciante', 'Estatística para Análise de Dados na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Aplique a estatística na análise de dados da administração pública com a linguagem R! O curso aborda os princípios da estatística básica, a introdução ao R, a modelagem de dados e gráficos e a análise de dados no contexto governamental. Destinado a analistas, técnicos e gestores que desejam usar a estatística e o R como ferramentas para transformar dados públicos em informações acionáveis para melhorar a tomada de decisão no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/930');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Suprimento de fundos e cartão de pagamento', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/928', 'gratuito', 'Iniciante', 'Suprimento de fundos e cartão de pagamento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Utilize o suprimento de fundos e o Cartão de Pagamento do Governo Federal com segurança jurídica e controle! O curso aborda a contextualização do instrumento, as regras da Lei nº 14.133 aplicadas ao cartão de pagamento e o gerenciamento do CPGF. Destinado a ordenadores de despesa, supridos e gestores que utilizam o cartão de pagamento governamental e precisam garantir conformidade, rastreabilidade e uso eficiente dos recursos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/928');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Procedimentos Auxiliares na Nova Lei de Licitações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/927', 'gratuito', 'Iniciante', 'Procedimentos Auxiliares na Nova Lei de Licitações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Compreenda os procedimentos auxiliares das contratações previstos na Nova Lei de Licitações! O curso aborda os instrumentos auxiliares das licitações e contratações no âmbito da Lei nº 14.133/2021, suas características e formas de utilização. Destinado a agentes de contratação, pregoeiros e gestores de compras que desejam ampliar seu repertório de instrumentos para otimizar as contratações públicas com base no novo marco legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/927');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratações Diretas na Nova Lei de Licitações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/926', 'gratuito', 'Iniciante', 'Contratações Diretas na Nova Lei de Licitações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 30h. Realize contratações diretas com segurança jurídica na Nova Lei de Licitações! O curso aborda a introdução à contratação direta, a inexigibilidade, a dispensa e a licitação dispensada, com as novidades trazidas pela Lei nº 14.133/2021. Destinado a agentes de contratação, gestores e técnicos que precisam conduzir contratações diretas com conformidade legal, compreendendo claramente as hipóteses e os requisitos de cada modalidade prevista no novo marco. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/926');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Licitação por concorrência, concurso, leilão e diálogo competitivo', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/925', 'gratuito', 'Iniciante', 'Licitação por concorrência, concurso, leilão e diálogo competitivo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Domine as modalidades de licitação previstas na Nova Lei: concorrência, concurso, leilão e diálogo competitivo! O curso aborda a visão geral e as especificidades de cada modalidade, com ênfase nas novidades trazidas pela Lei nº 14.133/2021. Destinado a agentes de contratação, gestores e técnicos de compras que precisam compreender e aplicar corretamente as diferentes modalidades licitatórias conforme o novo marco legal das contratações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/925');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inclusão de gênero na ponta da língua', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/924', 'gratuito', 'Iniciante', 'Inclusão de gênero na ponta da língua — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 8h. Transforme sua comunicação com o uso inclusivo da linguagem de gênero! O curso desmistifica resistências e mitos sobre o uso inclusivo da língua portuguesa e apresenta estratégias práticas para fazer a diferença na comunicação cotidiana. Indicado para servidores, comunicadores e profissionais que desejam promover a igualdade de gênero por meio da linguagem, contribuindo para ambientes mais respeitosos e representativos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/924');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Gestão de Riscos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/923', 'gratuito', 'Iniciante', 'Introdução à Gestão de Riscos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 40h. Estruture a gestão de riscos na sua organização com método e eficácia! O curso aborda governança e gestão, os benefícios da gestão de riscos, as etapas do processo, a identificação e o cálculo do nível de risco e as respostas adequadas. Destinado a gestores, auditores e analistas que desejam implementar ou aprimorar a gestão de riscos como ferramenta essencial para a melhoria da governança e o alcance dos objetivos institucionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/923');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Aspectos básicos no enfrentamento ao contrabando de migrantes', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/921', 'gratuito', 'Iniciante', 'Aspectos básicos no enfrentamento ao contrabando de migrantes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 20h. Desenvolva competências para o enfrentamento ao contrabando de migrantes! O curso aborda o marco legal, os conceitos relacionados ao contrabando de migrantes, os modelos de operação, os riscos do percurso e as violações de direitos humanos envolvidas. Destinado a profissionais de segurança pública, gestores de fronteira e servidores que atuam no controle migratório e buscam compreender as dinâmicas do crime organizado transnacional voltado ao contrabando de pessoas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/921');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Escuta qualificada para vulneráveis ao tráfico de pessoas', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/920', 'gratuito', 'Iniciante', 'Escuta qualificada para vulneráveis ao tráfico de pessoas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 15h. Desenvolva competências para uma escuta qualificada com vítimas e vulneráveis ao tráfico de pessoas! O curso aborda o conceito de escuta qualificada, suas etapas e as vulnerabilidades específicas das vítimas de tráfico de pessoas. Destinado a assistentes sociais, profissionais de saúde, psicólogos e servidores que atuam no atendimento a pessoas vulneráveis ao tráfico humano e precisam aprimorar sua capacidade de acolhimento e escuta sem revitimização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/920');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Docência Plural - Formação em Interculturalidade e Bilinguismo', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/918', 'gratuito', 'Iniciante', 'Docência Plural - Formação em Interculturalidade e Bilinguismo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 40h. Desenvolva competências para uma docência plural em contextos linguísticos e culturais diversos! O curso aborda fronteiras linguísticas e culturais, interculturalidade e educação linguística plural, fenômenos linguísticos das fronteiras hispano-brasileiras e a gestão de línguas na escola em contextos plurais. Destinado a professores, formadores e gestores educacionais que atuam em regiões de fronteira ou com populações multilíngues e multiculturais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/918');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Facilitação para Inovação e Transformação Governamental', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/917', 'gratuito', 'Iniciante', 'Introdução à Facilitação para Inovação e Transformação Governamental — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 30h. Aprenda a facilitação como ferramenta de inovação e transformação no setor público! O curso aborda o que é facilitação e sua relevância para a inovação governamental, as etapas e técnicas fundamentais e a facilitação na prática. Destinado a gestores, servidores e líderes de inovação que desejam desenvolver competências de facilitação para conduzir processos participativos, workshops e laboratórios de inovação com mais eficácia e engajamento. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/917');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos de Segurança da Informação na Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/916', 'gratuito', 'Iniciante', 'Fundamentos de Segurança da Informação na Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 25h. Construa bases sólidas de segurança da informação para a transformação digital do setor público! O curso aborda a contextualização da segurança na transformação digital, privacidade e segurança digital, a prevenção de riscos sistêmicos e o tratamento de incidentes de segurança. Destinado a gestores, analistas de TI e profissionais que precisam compreender e aplicar os fundamentos de segurança da informação no contexto da digitalização dos serviços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/916');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Atuação do Conselho de Administração em Cooperativas de Crédito', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/912', 'gratuito', 'Iniciante', 'Atuação do Conselho de Administração em Cooperativas de Crédito — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 4h. Fortaleça a atuação do Conselho de Administração das cooperativas de crédito! O curso aborda as atribuições do CA, as fontes de informação para os trabalhos do Conselho e como receber e processar informações para as reuniões. Destinado a membros de Conselhos de Administração de cooperativas de crédito que buscam exercer sua função de forma mais qualificada, contribuindo para a governança, a transparência e a solidez das cooperativas sob sua supervisão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/912');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Financeira e Cooperativismo', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/903', 'gratuito', 'Iniciante', 'Educação Financeira e Cooperativismo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 4h. Compreenda a educação financeira no contexto do cooperativismo e tome decisões mais conscientes! O curso aborda o conceito de educação financeira, sua relevância, a atuação do Banco Central no tema e a relação entre educação financeira e cooperativismo de crédito. Destinado a cooperados, servidores e cidadãos que buscam desenvolver competências financeiras e compreender como o cooperativismo de crédito pode contribuir para o bem-estar financeiro individual e coletivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/903');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Atuação do Conselho Fiscal em Cooperativas de Crédito', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/900', 'gratuito', 'Iniciante', 'Atuação do Conselho Fiscal em Cooperativas de Crédito — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 3h. Fortaleça a atuação do Conselho Fiscal nas cooperativas de crédito! O curso aborda as atribuições do Conselho Fiscal e as fontes de informação utilizadas nos trabalhos de fiscalização e controle. Destinado a membros de Conselhos Fiscais de cooperativas de crédito que desejam exercer sua função com mais conhecimento técnico, contribuindo para a governança, a transparência e a solidez financeira das cooperativas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/900');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova Lei de Licitações e Contratos: aspectos gerais e pontos de atenção', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/887', 'gratuito', 'Iniciante', 'Nova Lei de Licitações e Contratos: aspectos gerais e pontos de atenção — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 40h. Domine os aspectos gerais da Nova Lei de Licitações e Contratos (Lei nº 14.133/2021)! O curso percorre as fases de planejamento, seleção de fornecedores e gestão contratual, além de procedimentos auxiliares, contratação direta e controle. Destinado a gestores, pregoeiros e agentes de contratação que precisam atualizar seus conhecimentos e garantir conformidade com o novo marco legal das compras públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/887');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Suborno Transnacional', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/886', 'gratuito', 'Iniciante', 'Suborno Transnacional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 40h. Compreenda o suborno transnacional e os mecanismos internacionais de combate! O curso aborda a origem histórica, os conceitos e as convenções sobre suborno transnacional, as autoridades tributárias como atores de combate, as unidades de inteligência financeira e a jurisprudência do CADE. Destinado a auditores, procuradores, gestores de compliance e técnicos que atuam no combate à corrupção internacional e na implementação das convenções anticorrupção. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/886');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Participação e Controle Social na Execução de Penas', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/884', 'gratuito', 'Iniciante', 'Participação e Controle Social na Execução de Penas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 30h. Compreenda o papel da participação e do controle social na execução penal! O curso aborda as relações entre Estado, Direito e prisão, os mecanismos de participação social na execução de penas no Brasil e o fortalecimento institucional para a prevenção à tortura. Destinado a profissionais do sistema de justiça, defensores públicos, conselheiros da comunidade e servidores comprometidos com a humanização e o controle social do sistema prisional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/884');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direitos Humanos e saúde mental - Curso permanente Damião Ximenes Lopes', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/881', 'gratuito', 'Iniciante', 'Direitos Humanos e saúde mental - Curso permanente Damião Ximenes Lopes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Aplique os direitos humanos na atenção à saúde mental com base legal e ética! O curso aborda o direito internacional dos direitos humanos, a relação entre saúde e DH, os direitos das pessoas sob cuidados em saúde, a jurisprudência interamericana e a aplicação prática. Destinado a profissionais de saúde, gestores e operadores do sistema de saúde mental que buscam alinhar suas práticas aos padrões internacionais de direitos humanos na atenção psicossocial. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/881');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Aplicação do Plano de Contratação Anual', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/871', 'gratuito', 'Iniciante', 'Introdução à Aplicação do Plano de Contratação Anual — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Elabore e aplique o Plano de Contratação Anual com eficácia e conformidade! O curso aborda a introdução ao planejamento de contratações anual, as etapas do PCA e seu processo de aplicação e o Sistema de Planejamento e Gerenciamento das Contratações (SPGC). Destinado a gestores, agentes de contratação e técnicos de compras que precisam estruturar o planejamento anual de contratações de forma integrada, transparente e alinhada à Nova Lei de Licitações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/871');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Plano Diretor de Logística Sustentável: metodologia de construção, implementação e monitoramento', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/868', 'gratuito', 'Iniciante', 'Plano Diretor de Logística Sustentável: metodologia de construção, implementação e monitoramento — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 40h. Elabore, implemente e monitore o Plano Diretor de Logística Sustentável da sua organização! O curso aborda o percurso conceitual e normativo da sustentabilidade, os fundamentos do PLS, a metodologia de elaboração e as etapas de implantação e monitoramento. Destinado a gestores, analistas e servidores que atuam na área de logística sustentável e buscam estruturar ou aprimorar o PLS de seu órgão com base em metodologia sólida e alinhada à A3P. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/868');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligência Artificial para simplificar o dia a dia', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/861', 'gratuito', 'Iniciante', 'Inteligência Artificial para simplificar o dia a dia — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 4h. Simplifique tarefas do dia a dia com o uso prático da inteligência artificial! O curso aborda a IA para tarefas criativas, os modelos de geração de texto com o GPT-3 e as tecnologias de geração de imagem. Destinado a servidores, profissionais e cidadãos que desejam conhecer e experimentar as ferramentas de IA disponíveis para automatizar tarefas, criar conteúdos e ganhar produtividade com soluções acessíveis e de uso cotidiano. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/861');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Compras sustentáveis e a nova lei de licitações', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/860', 'gratuito', 'Iniciante', 'Compras sustentáveis e a nova lei de licitações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Incorpore critérios de sustentabilidade nas contratações públicas com base na Nova Lei de Licitações! O curso aborda sustentabilidade aplicada às compras, o planejamento da contratação pública sustentável, as licitações à luz da Lei nº 14.133/2021 e os requisitos de sustentabilidade aplicáveis. Destinado a gestores, pregoeiros e agentes de contratação que desejam promover compras mais responsáveis, ambientalmente corretas e socialmente justas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/860');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso responsável das TICs', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/859', 'gratuito', 'Iniciante', 'Uso responsável das TICs — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 10h. Use as Tecnologias da Informação e Comunicação de forma responsável e segura! O curso aborda a história da internet, o uso responsável das TICs e as boas práticas digitais para um ambiente online mais ético e seguro. Destinado a servidores, estudantes e cidadãos que desejam compreender as responsabilidades no uso das tecnologias digitais, promovendo uma postura mais consciente, ética e segura no ambiente virtual. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/859');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão e preservação de documentos digitais', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/857', 'gratuito', 'Iniciante', 'Gestão e preservação de documentos digitais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 26h. Gerencie e preserve documentos digitais com segurança e conformidade! O curso aborda a gestão de documentos digitais — ciclo de vida, formatos e metadados — e a preservação digital com os conceitos de Repositório Digital Confiável e Arquivamento (RDC-ARQ). Destinado a arquivistas, gestores documentais e técnicos de TI que precisam garantir a autenticidade, integridade e acessibilidade a longo prazo dos documentos digitais nas organizações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/857');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Economia criativa, empreendedorismo e inovação', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/849', 'gratuito', 'Iniciante', 'Economia criativa, empreendedorismo e inovação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. Explore a relação entre economia criativa, inovação e empreendedorismo no setor público! O curso aborda o tripé que sustenta a economia criativa, as ferramentas de inovação e empreendedorismo aplicadas ao setor público e a execução prática de projetos de economia criativa. Destinado a gestores, técnicos e empreendedores que desejam desenvolver iniciativas criativas e inovadoras com impacto econômico e cultural em seus territórios. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/849');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Avaliação de Políticas em Economia Criativa', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/846', 'gratuito', 'Iniciante', 'Avaliação de Políticas em Economia Criativa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Políticas Públicas. Carga horária: 20h. Avalie políticas públicas de economia criativa com rigor metodológico e visão estratégica! O curso aborda inovação e economia criativa, territórios criativos e desenvolvimento sustentável, os processos de elaboração de políticas públicas, a construção de dados e a avaliação de políticas culturais e criativas. Destinado a gestores culturais, pesquisadores e formuladores de políticas que desejam monitorar e avaliar o impacto de suas iniciativas no campo criativo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/846');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão Compartilhada no Projeto Orla', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/845', 'gratuito', 'Iniciante', 'Gestão Compartilhada no Projeto Orla — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Políticas Públicas. Carga horária: 20h. Promova a gestão compartilhada e sustentável das orlas e praias com o Projeto Orla! O curso aborda a zona costeira e os instrumentos de gestão, a gestão de orlas e praias, a construção e a implementação do Plano de Gestão Integrada da Orla. Destinado a gestores municipais, técnicos ambientais e profissionais que atuam na zona costeira e buscam implementar o Projeto Orla como instrumento de gestão participativa e sustentável das praias brasileiras. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/845');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Produção de Vídeos: uma introdução', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/844', 'gratuito', 'Iniciante', 'Produção de Vídeos: uma introdução — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 6h. Produza vídeos de qualidade do roteiro à pós-produção! O curso aborda a introdução à produção de vídeo, o roteiro, a pré-produção, a gravação e a pós-produção. Destinado a comunicadores, educadores, servidores e profissionais que desejam desenvolver competências básicas em produção audiovisual para criar conteúdos institucionais, educativos e de comunicação pública com mais qualidade e impacto. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/844');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Agenda 2030 para o desenvolvimento sustentável: desafios para a implementação', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/841', 'gratuito', 'Iniciante', 'Agenda 2030 para o desenvolvimento sustentável: desafios para a implementação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 24h. Compreenda a Agenda 2030 e contribua para a implementação dos Objetivos de Desenvolvimento Sustentável no Brasil! O curso aborda os ODS relacionados a combate à pobreza, educação, saúde, saneamento, inovação, cidades, energia limpa, trabalho, igualdade, clima, biodiversidade, justiça e parcerias. Destinado a gestores, técnicos e servidores que desejam integrar os ODS às políticas, programas e projetos de suas organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/841');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso de Dados Raciais Aplicados às Políticas Públicas — Intermediário', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/838', 'gratuito', 'Iniciante', 'Uso de Dados Raciais Aplicados às Políticas Públicas — Intermediário — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Utilize dados raciais para formular políticas públicas mais equitativas! O curso aborda conceitos sobre raça, racismo e ações afirmativas, estatística aplicada a dados raciais, análise de indicadores sociais e raciais com interseccionalidade e políticas com ou sem recorte racial. Destinado a gestores, analistas e formuladores de políticas que desejam incorporar a perspectiva racial na coleta, análise e uso de dados para combater desigualdades. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/838');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Assédio Moral: O que saber e fazer', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/836', 'gratuito', 'Iniciante', 'Assédio Moral: O que saber e fazer — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 12h. Identifique, previna e combata o assédio moral no ambiente de trabalho! O curso aborda o que é o assédio moral, como ele ocorre, a legislação e regulamentação vigentes e suas consequências. Destinado a servidores, líderes e profissionais que buscam compreender suas responsabilidades individuais e institucionais na prevenção ao assédio moral e na construção de ambientes de trabalho mais saudáveis, éticos e respeitosos para todos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/836');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução ao Manejo da Irrigação: como, quando e quanto irrigar', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/829', 'gratuito', 'Iniciante', 'Introdução ao Manejo da Irrigação: como, quando e quanto irrigar — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 4h. Domine o manejo eficiente da irrigação para aumentar a produtividade e economizar água! O curso aborda as vantagens do manejo, os fundamentos da irrigação, os métodos via solo e via clima e a programação de fertirrigação. Destinado a agricultores, técnicos agrícolas e gestores que desejam otimizar o uso da água na irrigação com base técnica, promovendo a eficiência hídrica e a sustentabilidade da produção agropecuária. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/829');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicações Processuais', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/820', 'gratuito', 'Iniciante', 'Comunicações Processuais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direito e Legislação. Carga horária: 10h. Domine as comunicações processuais com segurança jurídica e precisão! O curso aborda a comunicação processual inicial, a intimação e citação, as formas de entrega da comunicação em suas diferentes modalidades. Destinado a servidores, procuradores, técnicos jurídicos e gestores que atuam em processos administrativos e precisam garantir a regularidade e a eficácia das comunicações processuais nos procedimentos da administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/820');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Admissibilidade Correcional', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/819', 'gratuito', 'Iniciante', 'Admissibilidade Correcional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 20h. Domine os fundamentos da admissibilidade correcional e atue com segurança nos processos disciplinares! O curso aborda a visão geral da admissibilidade, a matriz de responsabilização, os elementos fato, conduta e agente, e os elementos de informação, tipificação e avaliação de provas. Destinado a corregedores, membros de comissões disciplinares e gestores que precisam avaliar a viabilidade e a procedência de denúncias antes da instauração de procedimentos correcionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/819');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Storytelling com Dados para Comunicação Profissional de Sucesso', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/815', 'gratuito', 'Iniciante', 'Storytelling com Dados para Comunicação Profissional de Sucesso — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 25h. Conte histórias com dados e transforme informação em comunicação de impacto! O curso aborda a introdução ao storytelling, como comunicar com imagens, a construção de narrativas no trabalho e o storytelling com dados aplicado. Destinado a gestores, analistas e comunicadores que buscam aprimorar sua capacidade de apresentar dados de forma clara, convincente e memorável, usando narrativas visuais e analíticas para influenciar decisões e engajar audiências. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/815');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: UX Writing para Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/813', 'gratuito', 'Iniciante', 'UX Writing para Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Aplique o UX Writing para criar textos mais claros, úteis e centrados no usuário nos serviços digitais! O curso aborda o contexto do UX Design, os fundamentos do UX Writing, como aplicá-lo na prática e sua aplicação na administração pública. Destinado a redatores, designers, analistas e gestores de produtos digitais do governo que buscam criar interfaces e textos mais compreensíveis, acessíveis e orientados às necessidades reais dos cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/813');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Soft Skills na Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/812', 'gratuito', 'Iniciante', 'Soft Skills na Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Desenvolva as soft skills essenciais para prosperar na transformação digital do serviço público! O curso aborda a contextualização das soft skills, as competências no ambiente de trabalho digital, a comunicação na transformação digital e a atitude de aprendizado contínuo. Destinado a gestores, analistas e servidores que buscam desenvolver as competências comportamentais e relacionais necessárias para navegar com eficácia no ambiente de trabalho em constante transformação digital. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/812');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Metodologia Cost Model aplicada à Administração Pública', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/811', 'gratuito', 'Iniciante', 'Metodologia Cost Model aplicada à Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 25h. Aplique a metodologia Cost Model para mensurar custos e investimentos na administração pública! O curso aborda a aplicação do Cost Model, a identificação de custos e a mensuração de investimentos na gestão pública. Destinado a gestores, analistas e servidores que buscam uma metodologia estruturada para calcular os custos dos processos e serviços públicos, apoiando decisões de alocação de recursos, precificação de serviços e avaliação da eficiência do gasto público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/811');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Desvendando a Inteligência Artificial na Administração Pública', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/810', 'gratuito', 'Iniciante', 'Desvendando a Inteligência Artificial na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 25h. Desvende o potencial da inteligência artificial para modernizar a administração pública! O curso aborda o contexto e os conceitos de IA, as oportunidades e limitações de sua implementação no setor público e casos de aplicação prática. Destinado a gestores, analistas e servidores que desejam compreender como a IA pode ser usada para melhorar serviços, processos e a tomada de decisão na administração pública brasileira. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/810');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gerenciamento de Portfólio de Projetos de Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/809', 'gratuito', 'Iniciante', 'Gerenciamento de Portfólio de Projetos de Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Gerencie portfólios de projetos de transformação digital com método e visão estratégica! O curso aborda os fundamentos do gerenciamento de portfólio, sua aplicação nos contextos de transformação digital e o kit de ferramentas disponível para a gestão. Destinado a gestores de TI, líderes de transformação digital e analistas que precisam priorizar, acompanhar e equilibrar múltiplos projetos digitais de forma estratégica, garantindo alinhamento e entrega de valor. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/809');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gamificação aplicada à Transformação Digital na Administração Pública', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/807', 'gratuito', 'Iniciante', 'Gamificação aplicada à Transformação Digital na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Aplique a gamificação para engajar servidores e cidadãos na transformação digital! O curso aborda os conceitos fundamentais, motivação e engajamento, os elementos de gamificação, a modelagem de ambientes gamificados e os exemplos de aplicação na administração pública. Destinado a gestores, designers de serviços e analistas que desejam usar a gamificação como estratégia para estimular comportamentos desejados, aprendizado e adesão a processos digitais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/807');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Estratégias de Marketing Digital para a Administração Pública', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/806', 'gratuito', 'Iniciante', 'Estratégias de Marketing Digital para a Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 25h. Aplique o marketing digital na administração pública com estratégia e eficácia! O curso aborda as noções de comunicação para o setor público, o marketing digital e suas ferramentas, o uso dos dados dos canais digitais e estratégias de marketing nas redes sociais. Destinado a gestores de comunicação, assessores e servidores que atuam na presença digital dos órgãos públicos e buscam ampliar o alcance e o impacto da comunicação institucional por meio das plataformas digitais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/806');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Design de Aplicativos na Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/803', 'gratuito', 'Iniciante', 'Design de Aplicativos na Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Projete aplicativos mais úteis, acessíveis e centrados no usuário para a transformação digital do setor público! O curso aborda o design centrado no humano, a pesquisa com usuários, a criação e prototipação de aplicativos, os testes de usabilidade e o design mobile na prática. Destinado a gestores, designers, analistas e desenvolvedores que desejam criar aplicativos públicos com melhor experiência de uso e impacto real para os cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/803');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Visualização de Dados Aplicada à Transformação Digital', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/802', 'gratuito', 'Iniciante', 'Visualização de Dados Aplicada à Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Transforme dados em histórias visuais impactantes para a transformação digital! O curso aborda os limites e possibilidades do data visualization, o data storytelling, a construção de painéis para análise e casos reais de uso na transformação digital. Destinado a gestores, analistas e técnicos que desejam comunicar informações complexas de forma clara e visualmente atraente, usando dashboards e narrativas de dados para apoiar decisões estratégicas no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/802');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Criação de Indicadores de Desempenho para a Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/801', 'gratuito', 'Iniciante', 'Criação de Indicadores de Desempenho para a Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Crie indicadores de desempenho robustos para acompanhar a transformação digital do seu órgão! O curso aborda os fundamentos dos indicadores, seu uso no processo de transformação digital, o sistema de medição de desempenho e como construir e avaliar indicadores práticos. Destinado a gestores, analistas e técnicos de TI que precisam medir e demonstrar os resultados das iniciativas de transformação digital com dados confiáveis e indicadores bem estruturados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/801');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Big Data em Apoio à Tomada de Decisão', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/800', 'gratuito', 'Iniciante', 'Big Data em Apoio à Tomada de Decisão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 25h. Utilize Big Data para qualificar a tomada de decisão no setor público! O curso aborda o que é Big Data, a gestão de dados em Big Data, o uso prático dos dados e o Big Data aplicado às decisões no serviço público. Destinado a gestores, analistas e técnicos que buscam compreender como volumes massivos de dados podem ser coletados, processados e utilizados para melhorar a eficiência, a transparência e a eficácia das decisões na administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/800');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Arquitetura de Soluções para Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/799', 'gratuito', 'Iniciante', 'Arquitetura de Soluções para Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Projete arquiteturas de soluções para a transformação digital com visão estratégica! O curso aborda a arquitetura de soluções a serviço da transformação digital, o que ela pode fazer, as plataformas de serviços e tecnologia e as equipes DevOps. Destinado a gestores de TI, arquitetos de soluções e analistas que precisam compreender como estruturar soluções tecnológicas escaláveis, seguras e orientadas ao valor público na jornada de transformação digital do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/799');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Internet do Comportamento (loB) em Serviços Públicos Digitais', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/798', 'gratuito', 'Iniciante', 'Internet do Comportamento (loB) em Serviços Públicos Digitais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 16h. Explore o potencial da Internet do Comportamento para melhorar os serviços públicos digitais! O curso aborda a era digital e a transformação digital, a transição da IoT para a IoB e as aplicações da IoB no contexto das organizações públicas. Destinado a gestores, analistas de TI e inovadores do setor público que buscam compreender como os dados comportamentais podem ser utilizados de forma ética para personalizar e melhorar a entrega de serviços digitais aos cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/798');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Automação de Processos através da RPA para Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/797', 'gratuito', 'Iniciante', 'Automação de Processos através da RPA para Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Automatize processos com RPA e impulsione a transformação digital do setor público! O curso aborda a introdução à automação por Robotic Process Automation, a aplicação prática da RPA e os casos de hiperautomação no governo. Destinado a gestores, analistas de TI e profissionais que buscam automatizar tarefas repetitivas e de baixo valor agregado, liberando recursos humanos para atividades mais estratégicas e elevando a eficiência dos processos governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/797');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: BIM - Projetos, Planejamento, Orçamentos e Contratos de Construção', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/796', 'gratuito', 'Iniciante', 'BIM - Projetos, Planejamento, Orçamentos e Contratos de Construção — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Infraestrutura. Carga horária: 16h. Domine o BIM aplicado a projetos, orçamentos, planejamento e contratos de construção! O curso aborda os projetos em BIM, os orçamentos e planejamento, as contratações e responsabilidades e as tendências contratuais. Destinado a engenheiros, arquitetos, gestores de obras e técnicos que buscam aprofundar sua compreensão sobre como o BIM transforma os processos de orçamentação, planejamento e gestão contratual nas obras públicas e privadas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/796');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de projetos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/787', 'gratuito', 'Iniciante', 'Gestão de projetos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 10h. Desenvolva competências em gestão de projetos e entregue resultados com eficiência e método! O curso aborda a introdução ao gerenciamento de projetos, os conceitos básicos, a influência da estrutura organizacional, o ciclo de vida do projeto e as boas práticas para sua realização. Destinado a gestores, coordenadores e servidores que desejam estruturar e executar projetos com planejamento sólido, gestão de riscos e foco na entrega de resultados para a organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/787');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Assinatura Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/775', 'gratuito', 'Iniciante', 'Assinatura Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 15h. Utilize a assinatura digital com segurança e eficácia nos processos públicos e privados! O curso aborda a introdução à assinatura digital, o primeiro contato com o recurso, os tipos de assinaturas — individuais, coassinaturas e carimbo de tempo —, o selo da assinatura digital e o token como ferramenta. Destinado a servidores, advogados, notários e profissionais que precisam compreender e utilizar a assinatura digital para dar validade jurídica a documentos eletrônicos com segurança e conformidad Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/775');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inovação em Compras Governamentais para a Segurança Pública', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/774', 'gratuito', 'Iniciante', 'Inovação em Compras Governamentais para a Segurança Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. Inove nas compras governamentais para a segurança pública e obtenha melhores resultados! O curso aborda inovação no setor público, inovação em segurança pública e as possibilidades de inovação nas compras governamentais para a área. Destinado a gestores de compras, comandantes e técnicos que atuam com aquisições para a segurança pública e buscam soluções mais modernas, eficientes e orientadas à melhoria dos resultados operacionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/774');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: E-liderança: como gerenciar e liderar equipes em ambientes remotos', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/773', 'gratuito', 'Iniciante', 'E-liderança: como gerenciar e liderar equipes em ambientes remotos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 20h. Desenvolva sua e-liderança e gerencie equipes remotas com eficácia e humanidade! O curso aborda o autoconhecimento como base da liderança, o relacionamento entre líder e liderados, a gestão da equipe e o relacionamento com outras equipes e boas práticas da liderança em ambientes remotos. Destinado a gestores e líderes que precisam adaptar seu estilo de liderança para inspirar, engajar e coordenar equipes em contextos de trabalho remoto e híbrido com qualidade e empatia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/773');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicação Pública e Gestão de Relacionamento com Cidadão', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/772', 'gratuito', 'Iniciante', 'Comunicação Pública e Gestão de Relacionamento com Cidadão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 20h. Qualifique a comunicação pública e fortaleça o relacionamento com o cidadão! O curso aborda os fundamentos da comunicação pública, a comunicação online e offline e as estratégias de relacionamento com os diferentes públicos da organização. Destinado a gestores de comunicação, assessores de imprensa e servidores que atuam na interface com o cidadão e buscam aprimorar a qualidade e a eficácia da comunicação institucional do seu órgão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/772');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Mídias para Educação: produção de vídeos e lives com qualidade', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/771', 'gratuito', 'Iniciante', 'Mídias para Educação: produção de vídeos e lives com qualidade — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 20h. Produza vídeos e lives educacionais com qualidade técnica e pedagógica! O curso aborda a linguagem audiovisual, os recursos técnicos necessários e as plataformas de publicação. Destinado a professores, tutores e gestores de educação que buscam desenvolver competências para produzir conteúdo audiovisual educacional de qualidade — aulas gravadas, lives e transmissões — com domínio técnico e clareza pedagógica para engajar os estudantes no ambiente digital. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/771');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fotografia e Audiovisual para Produção de Janelas de Libras', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/769', 'gratuito', 'Iniciante', 'Fotografia e Audiovisual para Produção de Janelas de Libras — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 20h. Capacite-se para produzir conteúdo audiovisual acessível com janelas de Libras! O curso aborda os fundamentos da acessibilidade audiovisual, os padrões e técnicas para comunicação acessível e as técnicas específicas para captação e edição de janelas de Libras. Essencial para profissionais de comunicação, audiovisual e tecnologia que desejam garantir a acessibilidade de conteúdos para pessoas surdas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/769');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Era Digital, Planejamento Estratégico e Inovação na Gestão Pública', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/768', 'gratuito', 'Iniciante', 'Era Digital, Planejamento Estratégico e Inovação na Gestão Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Combine era digital, planejamento estratégico e inovação para modernizar a gestão pública! O curso aborda as revoluções industriais e a era digital, a importância dos princípios de gestão, o planejamento estratégico e as metodologias de inovação aplicadas à gestão pública. Destinado a gestores, líderes e servidores que buscam integrar a perspectiva da era digital ao planejamento estratégico e à inovação para modernizar e aprimorar continuamente a atuação do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/768');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Criatividade e Novas Tecnologias para facilitar o seu dia a dia no trabalho', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/766', 'gratuito', 'Iniciante', 'Criatividade e Novas Tecnologias para facilitar o seu dia a dia no trabalho — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 10h. Explore ferramentas criativas e tecnológicas para otimizar sua rotina de trabalho! O curso apresenta aplicações como WhatsApp, CrystalKnows, YouCanBook, Whereby, Beautiful.ai e outras que aumentam a produtividade e a criatividade no ambiente profissional. Destinado a servidores e profissionais que desejam descobrir e experimentar novas ferramentas digitais para simplificar tarefas, melhorar a comunicação e tornar o dia a dia no trabalho mais ágil e eficiente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/766');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Análise de dados: uma leitura crítica das informações', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/764', 'gratuito', 'Iniciante', 'Análise de dados: uma leitura crítica das informações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 23h. Desenvolva uma leitura crítica e competente dos dados e informações! O curso aborda as ferramentas básicas de análise de dados, a representação, ajuste e correlação e a visão sistêmica sobre análise de dados. Destinado a gestores, analistas e servidores que buscam desenvolver um olhar mais crítico e fundamentado sobre os dados, compreendendo suas limitações, possibilidades e as armadilhas comuns na interpretação e comunicação de informações quantitativas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/764');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à orçamentação de obras rodoviárias', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/761', 'gratuito', 'Iniciante', 'Introdução à orçamentação de obras rodoviárias — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Infraestrutura. Carga horária: 40h. Aprenda a orçar obras rodoviárias com precisão e conformidade técnica! O curso aborda as considerações gerais, a composição de custos, o custo unitário de insumos com pesquisa de mercado e reajustamento, e as operações de terraplenagem e pavimentação. Destinado a engenheiros, técnicos e gestores de infraestrutura viária que precisam elaborar e analisar orçamentos de obras rodoviárias com base nos referenciais técnicos e normativos vigentes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/761');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: BIM - Fluxos de Trabalho', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/757', 'gratuito', 'Iniciante', 'BIM - Fluxos de Trabalho — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Infraestrutura. Carga horária: 16h. Estruture fluxos de trabalho eficientes em projetos BIM! O curso aborda contratos e fluxos de trabalho em BIM, os entregáveis esperados e a interoperabilidade e Open BIM como bases para a colaboração entre diferentes plataformas e agentes. Destinado a engenheiros, arquitetos, coordenadores de projetos e gestores de obras que precisam estruturar fluxos de trabalho colaborativos e padronizados em projetos que utilizam a metodologia BIM. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/757');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Riscos em Projetos de Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/724', 'gratuito', 'Iniciante', 'Gestão de Riscos em Projetos de Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 10h. Gerencie riscos em projetos de transformação digital com método e visão estratégica! O curso aborda a introdução à gestão de riscos em projetos digitais, as fases do ciclo de gestão de riscos e o caso de uso prático. Destinado a gestores de projetos, analistas e técnicos de TI que conduzem iniciativas de transformação digital no setor público e precisam identificar, avaliar e mitigar os riscos que podem comprometer o sucesso das entregas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/724');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: PRINCE2 - Outra maneira de gerenciar projetos na administração pública', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/723', 'gratuito', 'Iniciante', 'PRINCE2 - Outra maneira de gerenciar projetos na administração pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 25h. Gerencie projetos na administração pública com o PRINCE2! O curso aborda o conceito e a aplicabilidade do PRINCE2, seus princípios, os temas, os processos e os métodos ágeis integrados ao PRINCE2. Destinado a gestores, coordenadores e profissionais que buscam uma alternativa estruturada de gerenciamento de projetos, alinhando o PRINCE2 à realidade da administração pública brasileira e aos contextos que exigem maior governança e controle dos projetos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/723');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de políticas, programas e projetos para o desenvolvimento humano e sustentável', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/722', 'gratuito', 'Iniciante', 'Elaboração de políticas, programas e projetos para o desenvolvimento humano e sustentável — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Políticas Públicas. Carga horária: 10h. Elabore políticas, programas e projetos alinhados à Agenda 2030 e ao desenvolvimento humano sustentável! O curso aborda a Agenda 2030 e os ODS, as metodologias e ferramentas de integração dos ODS e a elaboração prática de políticas, programas e projetos orientados ao desenvolvimento humano e sustentável. Destinado a gestores, analistas e formuladores de políticas que buscam alinhar suas iniciativas aos compromissos globais de sustentabilidade e desenvolvimento. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/722');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Agenda para o desenvolvimento sustentável: conceitos, mobilização e articulação', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/719', 'gratuito', 'Iniciante', 'Agenda para o desenvolvimento sustentável: conceitos, mobilização e articulação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 8h. Compreenda a Agenda 2030 e mobilize atores para o desenvolvimento sustentável! O curso aborda a Agenda 2030, os ODS, os indicadores utilizados e a implementação da agenda nos âmbitos estadual e municipal. Destinado a gestores, técnicos e articuladores de políticas públicas que buscam incorporar os Objetivos de Desenvolvimento Sustentável às políticas, programas e projetos de suas organizações, mobilizando parceiros e atores relevantes para a agenda. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/719');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: 2030 Agenda for Sustainable Development and e-Learning Design Basics', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/713', 'gratuito', 'Iniciante', '2030 Agenda for Sustainable Development and e-Learning Design Basics — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 10h. Integrate the 2030 Agenda for Sustainable Development into your e-learning design practice! This course covers the content of the 2030 Agenda with its SDGs and the basic principles of instructional design for digital learning environments. Ideal for educators, instructional designers and professionals who want to embed the sustainable development goals into digital learning experiences. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/713');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestión Personal - Base del Liderazgo', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/707', 'gratuito', 'Intermediário', 'Gestión Personal - Base del Liderazgo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 50h. ¡Desarrolla tu liderazgo desde adentro con autoconocimiento y crecimiento personal! El curso aborda el desarrollo biopsicosocial, las dimensiones psicológica y el perfil comportamental, la dimensión social e integrativa, la mentalidad y la psicología positiva, las virtudes y valores personales y las técnicas de coaching. Ideal para gestores y líderes hispanohablantes que desean fortalecer las bases personales de su liderazgo con autoconocimiento, propósito y equilibrio. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/707');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Comportamento nas Organizações', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/702', 'gratuito', 'Iniciante', 'Gestão de Comportamento nas Organizações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 10h. Compreenda o comportamento organizacional com base na ética e na gestão sustentável! O curso aborda o histórico da gestão do comportamento, o código de ética como ferramenta, o consumo verde e as definições aplicadas à gestão organizacional. Destinado a gestores, líderes e profissionais que buscam compreender como o comportamento organizacional se articula com a ética, a sustentabilidade e a responsabilidade social para construir organizações mais íntegras e responsáveis. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/702');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Creatividad y Nuevas Tecnologías en el Servicio Público', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/698', 'gratuito', 'Iniciante', 'Creatividad y Nuevas Tecnologías en el Servicio Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 10h. ¡Descubre herramientas creativas y tecnologías innovadoras para el servicio público en español! El curso presenta aplicaciones como WhatsApp, CrystalKnows, YouCanBook, Whereby y otras que pueden aumentar la productividad y creatividad en el trabajo. Ideal para servidores, gestores y profesionales hispanohablantes que desean explorar nuevas herramientas digitales para optimizar procesos, mejorar la comunicación y estimular la creatividad en el ambiente gubernamental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/698');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão dos recursos da educação básica pública e o Novo Fundeb', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/691', 'gratuito', 'Iniciante', 'Gestão dos recursos da educação básica pública e o Novo Fundeb — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 25h. Gerencie os recursos da educação básica pública com base no Novo Fundeb! O curso aborda os recursos disponíveis para investimento, o financiamento da educação básica e o Novo Fundeb com suas regras de distribuição, gestão e acompanhamento. Destinado a gestores educacionais, diretores de escola, secretários de educação e conselheiros que precisam compreender as mudanças do Novo Fundeb e garantir o uso eficiente e transparente dos recursos destinados à educação pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/691');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderando para o Desenvolvimento - Novos Prefeitos', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/688', 'gratuito', 'Iniciante', 'Liderando para o Desenvolvimento - Novos Prefeitos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 30h. Lidere o desenvolvimento do seu município com visão estratégica e competência gestora! O curso aborda políticas públicas, gestão governamental, probidade administrativa, mobilização de recursos, planejamento e gestão de cidades e os novos paradigmas da liderança municipal. Destinado a novos prefeitos e gestores municipais que precisam de uma formação abrangente para exercer a liderança local com responsabilidade, eficácia e compromisso com o desenvolvimento do município. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/688');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso de Dados Raciais Aplicado às Políticas Públicas: Básico', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/682', 'gratuito', 'Iniciante', 'Uso de Dados Raciais Aplicado às Políticas Públicas: Básico — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Utilize dados raciais para formular políticas públicas mais equitativas! O curso aborda raça e categorização racial, os processos para produção de dados raciais, os dados em pesquisas domiciliares e em registros administrativos. Destinado a gestores, analistas e formuladores de políticas que estão iniciando no uso de dados raciais e buscam compreender as bases conceituais e os protocolos para produzir, analisar e aplicar essas informações no combate às desigualdades raciais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/682');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gerenciamento de Projetos na Prática', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/680', 'gratuito', 'Iniciante', 'Gerenciamento de Projetos na Prática — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 40h. Aplique o gerenciamento de projetos na prática com método e eficácia! O curso aborda os conceitos básicos, as práticas de iniciação e planejamento, a execução e o controle dos projetos. Destinado a gestores, coordenadores e servidores que precisam planejar e executar projetos com maior organização, controle de prazos e entregas, aplicando as melhores práticas de gestão de projetos na realidade do serviço público e corporativo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/680');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Type I Environmental Labeling course: Sustainability and Competitiveness for Brazilian Products and Services', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/677', 'gratuito', 'Iniciante', 'Type I Environmental Labeling course: Sustainability and Competitiveness for Brazilian Products and Services — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Implement Type I Environmental Labeling to boost sustainability and competitiveness! This course covers the contextualization of ecolabelling, its principles and requirements, case studies and the strategy for implementing Type I ecolabels for products and services in Brazil and Latin America. Ideal for managers, producers and technical professionals who want to demonstrate environmental commitment with credibility and market differentiation. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/677');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Etiquetado Ambiental Tipo I: sostenibilidad y competitividad para productos y servicios brasileños', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/676', 'gratuito', 'Iniciante', 'Etiquetado Ambiental Tipo I: sostenibilidad y competitividad para productos y servicios brasileños — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. ¡Incorpora el etiquetado ambiental tipo I en la estrategia de sus productos y servicios! El curso aborda la contextualización del ecoetiquetado, sus principios y requisitos, estudios de caso y la estrategia para su implementación en el mercado brasileño y latinoamericano. Ideal para gestores, productores y técnicos hispanohablantes que desean demostrar el compromiso ambiental de sus productos con credibilidad y diferenciación competitiva. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/676');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Métodos e Ferramentas para Inovação em Políticas Públicas', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/664', 'gratuito', 'Iniciante', 'Métodos e Ferramentas para Inovação em Políticas Públicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 25h. Inove nas políticas públicas com métodos e ferramentas modernas! O curso aborda linguagem simples, ciências comportamentais, ciência de dados, design de serviços e etnografia aplicados à inovação em políticas públicas. Destinado a gestores, analistas e servidores que buscam incorporar abordagens inovadoras à formulação e implementação de políticas, tornando-as mais centradas nas necessidades reais dos cidadãos e mais eficazes em seus resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/664');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Modelo de Governança e Gestão – Gestaopublicagov.br: Visão Geral e Sistema', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/662', 'gratuito', 'Iniciante', 'Modelo de Governança e Gestão – Gestaopublicagov.br: Visão Geral e Sistema — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 20h. Implemente o modelo de governança e gestão pública com eficácia! O curso apresenta o Gestaopublicagov.br, seus conceitos teóricos, a implementação prática, a avaliação dos critérios de maturidade e a elaboração de planos de melhoria da governança e gestão. Destinado a gestores e servidores que atuam na estruturação ou avaliação de práticas de governança, com foco na melhoria contínua da administração pública federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/662');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Casos de Violência Baseada no Gênero', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/653', 'gratuito', 'Iniciante', 'Gestão de Casos de Violência Baseada no Gênero — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 20h. Qualifique o atendimento e a gestão de casos de violência baseada no gênero! O curso aborda os fundamentos da VBG, a rede de proteção e a política nacional de enfrentamento, os padrões mínimos de atendimento humanizado e a metodologia de gestão de casos em seis etapas. Destinado a profissionais da rede de atenção à mulher — assistentes sociais, psicólogos, agentes de saúde e educação — que buscam aprimorar sua atuação com vítimas de VBG. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/653');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Módulo de Obras: Cadastro do Projeto Básico', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/645', 'gratuito', 'Iniciante', 'Módulo de Obras: Cadastro do Projeto Básico — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transferências Voluntárias. Carga horária: 10h. Registre e analise o Projeto Básico de obras no Transferegov.br! O curso aborda o módulo de obras na plataforma, o registro do Projeto Básico pelo convenente e a análise pelo concedente ou mandatária. Destinado a gestores e técnicos convenentes e concedentes que precisam operacionalizar o Módulo de Obras do Transferegov.br, garantindo o correto registro e análise do Projeto Básico como etapa essencial para o início da execução das obras financiadas com recursos federais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/645');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Fiscal e Cidadania', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/635', 'gratuito', 'Iniciante', 'Educação Fiscal e Cidadania — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Participação e Cidadania. Carga horária: 25h. Compreenda o papel do Estado, o sistema tributário e o orçamento público para exercer uma cidadania fiscal ativa! O curso aborda a relação entre Estado, sociedade e democracia, o sistema tributário brasileiro e o orçamento público como dinheiro de todos. Destinado a servidores, educadores e cidadãos que desejam compreender como os tributos são arrecadados e aplicados, fortalecendo a consciência fiscal e o controle social sobre os gastos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/635');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Conhecendo o Programa de Voluntariado do ICMBio', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/634', 'gratuito', 'Iniciante', 'Conhecendo o Programa de Voluntariado do ICMBio — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 40h. Conheça e contribua com o Programa de Voluntariado do ICMBio! O curso aborda a contextualização do trabalho voluntário no ICMBio, o funcionamento do programa e as orientações para conduzir atividades voluntárias nas Unidades de Conservação. Destinado a cidadãos, profissionais e estudantes que desejam contribuir voluntariamente com a conservação da biodiversidade e a gestão das Unidades de Conservação Federais do Brasil. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/634');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Aprendendo com Python', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/629', 'gratuito', 'Iniciante', 'Aprendendo com Python — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Inicie sua jornada na programação com Python e abra novas possibilidades profissionais! O curso aborda variáveis, operações e condições, loops e funções, estruturas básicas de dados, programação orientada a objetos e o uso de bibliotecas. Destinado a profissionais, servidores e estudantes que desejam aprender programação do zero com Python, uma das linguagens mais versáteis e utilizadas no mundo para ciência de dados, automação e desenvolvimento de soluções. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/629');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligencia Emocional', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/627', 'gratuito', 'Intermediário', 'Inteligencia Emocional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 50h. ¡Desarrolla tu inteligencia emocional y transforma tus relaciones profesionales y personales! El curso aborda el manejo de las emociones personales, la gestión emocional en las relaciones interpersonales, la construcción de un ambiente de trabajo positivo y el liderazgo positivo. Ideal para gestores, líderes y profesionales hispanohablantes que desean mejorar su autoconocimiento, su capacidad de influencia y el clima de sus equipos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/627');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Emotional Intelligence', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/626', 'gratuito', 'Intermediário', 'Emotional Intelligence — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 50h. Develop your emotional intelligence and transform your professional and personal relationships! This course covers the management of personal emotions, emotional management in interpersonal relationships, building a positive work environment and positive leadership. Ideal for managers, leaders and professionals seeking to improve their self-awareness, capacity for influence and team climate through the development of emotional competencies. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/626');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Garantia de Direitos e Atenção à Pessoa Idosa', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/624', 'gratuito', 'Iniciante', 'Garantia de Direitos e Atenção à Pessoa Idosa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Garanta os direitos e qualifique a atenção à pessoa idosa com humanidade e método! O curso aborda a pessoa idosa como sujeito de direitos, o fortalecimento de vínculos e a valorização da pessoa idosa e as redes de proteção e instrumentos de garantia de direitos. Destinado a profissionais de saúde, assistência social e gestores que buscam qualificar o cuidado e o atendimento à pessoa idosa, garantindo respeito à dignidade, à autonomia e aos direitos fundamentais dessa população. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/624');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direito e Atenção à Saúde da Pessoa Idosa', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/623', 'gratuito', 'Iniciante', 'Direito e Atenção à Saúde da Pessoa Idosa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Saúde. Carga horária: 35h. Compreenda o direito à saúde da pessoa idosa e as estratégias para um envelhecimento ativo e saudável! O curso aborda o envelhecimento no contexto das crises sanitárias, os determinantes sociais de saúde, as relações sociais e a integração comunitária e a rede de atenção à saúde da pessoa idosa. Destinado a profissionais de saúde, gestores e servidores que atuam na atenção à pessoa idosa e buscam qualificar o cuidado com base em direitos e evidências. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/623');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Monitoramento e Avaliação de Políticas Públicas de Educação Ambiental', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/617', 'gratuito', 'Iniciante', 'Monitoramento e Avaliação de Políticas Públicas de Educação Ambiental — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão de Políticas Públicas. Carga horária: 20h. Fortaleça o monitoramento e a avaliação das políticas de educação ambiental no Brasil! O curso aborda as políticas públicas de educação ambiental, metodologias de monitoramento e avaliação, as dimensões e indicadores do Sistema MonitoraEA e suas ferramentas tecnológicas. Destinado a gestores, técnicos e educadores ambientais que desejam acompanhar e avaliar sistematicamente o impacto das políticas de educação ambiental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/617');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Acessibilidade na Comunicação', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/615', 'gratuito', 'Iniciante', 'Acessibilidade na Comunicação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 30h. Promova a acessibilidade na comunicação e garanta que todos os cidadãos sejam alcançados! O curso aborda o conceito biopsicossocial e a legislação sobre deficiência, as atribuições dos gestores na comunicação acessível, os recursos e técnicas de acessibilidade — Libras, audiodescrição, Braille e outros. Destinado a comunicadores, gestores e servidores que produzem ou gerenciam conteúdos institucionais e desejam garantir o acesso à informação para todos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/615');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratações de Encomendas Tecnológicas', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/609', 'gratuito', 'Iniciante', 'Contratações de Encomendas Tecnológicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 30h. Contrate Encomendas Tecnológicas (ETEC) com segurança e eficácia! O curso aborda a importância e o contexto da ETEC, sua caracterização, o monitoramento e controle e a instrução processual. Destinado a gestores, técnicos e agentes de contratação que atuam com contratações de pesquisa e desenvolvimento tecnológico no setor público e buscam utilizar o instrumento da ETEC para fomentar a inovação com base legal sólida. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/609');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Avaliação em Processos de Aprendizagem e Modelos de Feedback', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/606', 'gratuito', 'Iniciante', 'Avaliação em Processos de Aprendizagem e Modelos de Feedback — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. Avalie a aprendizagem com rigor e promova o feedback como instrumento de desenvolvimento! O curso aborda os conceitos de avaliação da aprendizagem, os tipos de avaliação, a avaliação nas organizações e as metodologias ativas e modelos de feedback. Destinado a professores, tutores e gestores de T&D que buscam aprimorar suas práticas de avaliação e feedback nos processos de aprendizagem, tornando-os mais formativos, orientados ao desenvolvimento e alinhados às metodologias ativas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/606');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da Lei Geral de Proteção de Dados (LGPD)', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/603', 'gratuito', 'Iniciante', 'Fundamentos da Lei Geral de Proteção de Dados (LGPD) — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 15h. Compreenda a LGPD e garanta a proteção dos dados pessoais na sua organização! O curso aborda os conceitos básicos, os direitos do titular, o tratamento de dados pessoais sensíveis, dados de crianças e adolescentes, compartilhamento e transferência, segurança da informação, penalidades e a implementação da LGPD. Destinado a servidores, gestores e encarregados que precisam compreender e aplicar a LGPD em suas organizações para garantir conformidade legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/603');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Habilidades de Resolução de Problemas', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/600', 'gratuito', 'Iniciante', 'Habilidades de Resolução de Problemas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 25h. Desenvolva habilidades essenciais para resolver problemas com eficácia e liderança! O curso aborda a estrutura LEADS, liderança, comunicação efetiva, pensamento analítico, desenvolvimento do pensamento e solução de problemas em equipe. Destinado a gestores, líderes e profissionais que desejam aprimorar sua capacidade de enfrentar desafios complexos com método, criatividade e colaboração no ambiente de trabalho. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/600');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: ForRisco - Gestão de Riscos para IES', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/599', 'gratuito', 'Iniciante', 'ForRisco - Gestão de Riscos para IES — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 20h. Implemente a gestão de riscos nas Instituições de Ensino Superior com a metodologia ForRisco! O curso aborda os princípios e conceitos, as metodologias da administração pública brasileira, a metodologia ForRisco e a plataforma. Destinado a gestores, auditores e técnicos de IES que buscam estruturar a gestão de riscos institucionais com base em uma metodologia específica para o contexto das instituições públicas de ensino superior. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/599');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Redação Oficial e Noções de SEI e suas aplicações', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/563', 'gratuito', 'Iniciante', 'Redação Oficial e Noções de SEI e suas aplicações — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 10h. Domine a redação oficial e utilize o SEI com segurança no serviço público! O curso aborda as características da redação oficial, os tipos de documentos e suas estruturas, a composição de texto e as noções de uso do SEI. Destinado a servidores que precisam redigir documentos oficiais com qualidade técnica — ofícios, memorandos, atas, relatórios — e operar o SEI de forma eficiente na rotina administrativa do serviço público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/563');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Sandbox Regulatório: do Regulamento à Inovação na Rua', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/556', 'gratuito', 'Iniciante', 'Sandbox Regulatório: do Regulamento à Inovação na Rua — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Regulação. Carga horária: 20h. Implemente um Sandbox Regulatório para fomentar a inovação com segurança jurídica! O curso aborda os fundamentos do sandbox regulatório, sua governança e os impactos e resultados esperados. Destinado a reguladores, gestores e analistas de agências reguladoras e ministérios que buscam criar ambientes controlados de experimentação para testar inovações antes de regulamentá-las definitivamente, equilibrando a promoção da inovação com a proteção do interesse público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/556');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Personal Management - Basis of Leadership', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/552', 'gratuito', 'Intermediário', 'Personal Management - Basis of Leadership — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 50h. Build your leadership from the inside out with self-knowledge and personal growth! This course covers biopsychosocial development, psychological dimensions and behavioral profile, social and integrative development, mindset, positive psychology, virtues and personal values, and coaching techniques. Ideal for managers and leaders seeking to strengthen the personal foundations of their leadership with greater self-awareness, purpose and balance. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/552');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Administration of Government Cloud Services', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/551', 'gratuito', 'Iniciante', 'Administration of Government Cloud Services — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 30h. Administer government cloud services with security and efficiency! This course covers cloud computing overview, basic infrastructure items, mechanisms of cloud information security, technological imprisonment (lock-in) and cost management. Ideal for IT managers and technical professionals in the public sector seeking to understand and manage government cloud infrastructure, ensuring data security, service continuity and prevention of vendor lock-in situations. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/551');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: SEI! Usar para Deficientes Visuais', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/545', 'gratuito', 'Iniciante', 'SEI! Usar para Deficientes Visuais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 20h. Utilize o SEI com autonomia e acessibilidade para usuários com deficiência visual! O curso aborda a introdução ao sistema, as operações com processos e documentos, o uso de blocos, a recuperação de informações e o acesso por usuários externos, tudo com foco em acessibilidade para pessoas com deficiência visual. Destinado a servidores com deficiência visual que precisam operar o SEI com tecnologias assistivas e autonomia no cumprimento de suas funções. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/545');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Creativity and new Technologies at the Work Environment', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/542', 'gratuito', 'Iniciante', 'Creativity and new Technologies at the Work Environment — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 10h. Explore creative tools and new technologies to optimize your work routine! This course presents applications like WhatsApp, CrystalKnows, YouCanBook, Appear.in, Beautiful.AI and other tools that enhance productivity and creativity. Ideal for professionals and public servants seeking to discover and use digital tools to simplify tasks, improve communication and make daily work more agile and effective. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/542');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: UX: Como Melhorar a Experiência do Usuário no Serviço Público Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/537', 'gratuito', 'Iniciante', 'UX: Como Melhorar a Experiência do Usuário no Serviço Público Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Melhore a experiência do usuário nos serviços públicos digitais com design centrado nas pessoas! O curso aborda a introdução à UX, a prática da experiência do usuário e a aplicação nos serviços públicos digitais. Destinado a gestores, analistas, designers e desenvolvedores que atuam na concepção ou melhoria de serviços digitais do governo e desejam colocar o cidadão no centro do processo de design com empatia e método. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/537');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governança de Dados na Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/536', 'gratuito', 'Iniciante', 'Governança de Dados na Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 25h. Estruture a governança de dados e transforme a administração pública com decisões baseadas em informação! O curso aborda a introdução à gestão de dados, a governança de dados na administração pública, a estrutura de apoio necessária e a governança de dados na prática. Destinado a gestores, analistas e profissionais de TI que desejam implementar práticas consistentes de governança de dados para apoiar a transformação digital do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/536');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gerenciamento de serviços de TIC focado na Administração Pública', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/535', 'gratuito', 'Iniciante', 'Gerenciamento de serviços de TIC focado na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Desenvolva uma visão estratégica sobre o gerenciamento de serviços de TIC na administração pública! O curso aborda a visão sobre gerenciamento de serviços, a geração de valor público mediante serviços, o dimensionamento da organização e a gestão de serviços de TIC no contexto governamental. Destinado a gestores e técnicos de TI que buscam alinhar os serviços de tecnologia às necessidades dos órgãos e à entrega de valor para o cidadão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/535');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Internet das coisas (IoT) aplicada para resolução de desafios', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/534', 'gratuito', 'Iniciante', 'Internet das coisas (IoT) aplicada para resolução de desafios — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Explore o potencial da Internet das Coisas para resolver desafios no setor público! O curso aborda o histórico e os conceitos da IoT, a conexão, segurança e privacidade, as novas tecnologias aliadas à IoT e sua utilização na solução de problemas governamentais. Destinado a gestores, analistas e técnicos de TI que buscam compreender como os dispositivos conectados e os dados gerados pela IoT podem ser aplicados para modernizar processos e serviços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/534');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Como implementar a LGPD: bases, mecanismos e processos', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/529', 'gratuito', 'Iniciante', 'Como implementar a LGPD: bases, mecanismos e processos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 25h. Implemente a LGPD na sua organização com método e segurança! O curso aborda as bases para aplicação da LGPD, os mecanismos de implementação, as etapas práticas e as infrações e penalidades. Destinado a encarregados de dados, gestores de TI e jurídicos que precisam conduzir o processo de adequação das organizações à Lei Geral de Proteção de Dados, garantindo conformidade legal e proteção efetiva dos dados pessoais de servidores e cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/529');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Design Sprint em Projetos de Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/528', 'gratuito', 'Iniciante', 'Design Sprint em Projetos de Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Acelere a inovação com o Design Sprint em projetos de transformação digital! O curso aborda os conceitos e características do Design Sprint, as etapas e ferramentas de cada fase e os pilares que sustentam sua aplicação. Destinado a gestores, analistas e equipes de TI e inovação que desejam resolver problemas complexos e validar soluções digitais de forma ágil, colaborativa e centrada no usuário em apenas uma semana de trabalho intensivo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/528');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Cultura Organizacional Ágil Aplicada ao Contexto Público', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/525', 'gratuito', 'Iniciante', 'Cultura Organizacional Ágil Aplicada ao Contexto Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Construa uma cultura organizacional ágil no setor público com estratégia e gestão da mudança! O curso aborda a compreensão da cultura organizacional, a cultura ágil e sua aplicação e a gestão da mudança para a transição. Destinado a gestores, líderes de transformação e analistas que buscam cultivar uma cultura de agilidade nas organizações públicas, promovendo mentalidade de melhoria contínua, colaboração e adaptação rápida às mudanças do ambiente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/525');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Abordagem Lean aplicada à Transformação Digital na Administração Pública', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/524', 'gratuito', 'Iniciante', 'Abordagem Lean aplicada à Transformação Digital na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Aplique a abordagem Lean para eliminar desperdícios e acelerar a transformação digital! O curso aborda a filosofia Lean, a identificação de desperdícios, as técnicas e métricas Lean e sua aplicação prática na transformação digital da administração pública. Destinado a gestores, analistas e equipes de melhoria de processos que buscam aplicar o Lean no setor público para simplificar fluxos, reduzir custos e entregar mais valor ao cidadão com menos recursos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/524');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: OKR Aplicado à Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/523', 'gratuito', 'Iniciante', 'OKR Aplicado à Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 25h. Aplique a metodologia OKR para impulsionar a transformação digital na sua organização! O curso aborda cultura e agilidade organizacional, medição de desempenho com métricas ágeis, a metodologia OKR, sua aplicação prática e o uso do OKR na transformação digital. Destinado a gestores, líderes de TI e analistas que desejam alinhar equipes, priorizar iniciativas digitais e monitorar resultados com clareza e foco nos objetivos estratégicos da organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/523');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Avaliadores de Artigos Científicos', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/521', 'gratuito', 'Iniciante', 'Avaliadores de Artigos Científicos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 20h. Prepare-se para atuar como avaliador de artigos científicos com ética e rigor! O curso aborda a comunicação científica, o processo editorial com atores e fluxo de atividades e as características e responsabilidades do avaliador. Destinado a pesquisadores, professores e profissionais que buscam compreender o processo de avaliação por pares na comunicação científica e desenvolver as competências necessárias para revisar artigos com qualidade, imparcialidade e responsabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/521');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da transformação digital: mapeamento e automação de processos', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/518', 'gratuito', 'Iniciante', 'Fundamentos da transformação digital: mapeamento e automação de processos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Aplique os fundamentos da gestão de processos para impulsionar a transformação digital! O curso aborda os fundamentos da gestão de processos com foco na transformação digital e o mapeamento de processos e design de automação. Destinado a gestores, analistas e técnicos que buscam compreender como o mapeamento e a automação de processos são peças fundamentais da transformação digital, permitindo identificar gargalos e oportunidades de melhoria e eficiência nas organizações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/518');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Primeira Infância Primeiro no PPA', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/516', 'gratuito', 'Iniciante', 'Primeira Infância Primeiro no PPA — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 25h. Incorpore a primeira infância como prioridade no Plano Plurianual! O curso aborda a priorização e o planejamento de políticas públicas no ciclo orçamentário, o marco legal e institucional do PPA e as ações para o desenvolvimento da primeira infância nos instrumentos de planejamento governamental. Destinado a gestores, técnicos e analistas de planejamento e orçamento que buscam garantir a transversalidade da agenda da primeira infância nos instrumentos de planejamento. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/516');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Politicas Públicas para Pequenos Negócios - Aquisições públicas', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/514', 'gratuito', 'Iniciante', 'Gestão de Politicas Públicas para Pequenos Negócios - Aquisições públicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 40h. Amplie a participação dos pequenos negócios nas compras governamentais! O curso aborda o contexto das compras governamentais, a Lei Geral da Micro e Pequena Empresa, o planejamento de licitações com a participação das MPE e os instrumentos de apoio. Destinado a gestores, técnicos e formuladores de políticas que desejam aplicar a legislação favorável às MPE nas compras públicas, promovendo o desenvolvimento econômico e a geração de emprego local. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/514');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Compliance Concorrencial', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/513', 'gratuito', 'Iniciante', 'Compliance Concorrencial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 22h. Implemente um programa de compliance concorrencial eficaz na sua organização! O curso aborda a introdução ao compliance concorrencial, o mapeamento de riscos concorrenciais e a implementação do programa na estrutura organizacional. Destinado a gestores jurídicos, analistas de compliance e responsáveis por programas de integridade que buscam identificar e mitigar riscos de infrações à concorrência na sua organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/513');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inovações em Tecnologia Educacional', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/511', 'gratuito', 'Iniciante', 'Inovações em Tecnologia Educacional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 25h. Compreenda o contexto da inovação na educação e construa capacidade de inovar nos processos educativos! O curso aborda o contexto da inovação na educação e as estratégias para construir capacidade de inovação nas instituições educacionais. Destinado a gestores, coordenadores e profissionais da educação que buscam compreender as tendências e as ferramentas tecnológicas que estão transformando o ensino e aprender como promover a inovação de forma estruturada em suas instituições. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/511');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Rotulagem Ambiental Tipo I: Sustentabilidade e Competitividade para Produtos e Serviços Brasileiros', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/507', 'gratuito', 'Iniciante', 'Rotulagem Ambiental Tipo I: Sustentabilidade e Competitividade para Produtos e Serviços Brasileiros — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 30h. Implemente a Rotulagem Ambiental Tipo I e diferencie seus produtos no mercado com credibilidade ambiental! O curso aborda a contextualização da rotulagem, seus fundamentos, estudos de casos e a estratégia para implementação em produtos e serviços brasileiros. Destinado a gestores, produtores e técnicos que desejam obter o selo ambiental Tipo I para seus produtos, comprovando o compromisso ambiental e ganhando diferenciação competitiva no mercado nacional e internacional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/507');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso do Design em Políticas Públicas', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/506', 'gratuito', 'Iniciante', 'Uso do Design em Políticas Públicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. Aplique o design para criar políticas públicas mais eficazes e centradas nas pessoas! O curso aborda o design em políticas públicas, o design etnográfico, a criatividade e ideação e as ferramentas práticas de design aplicadas. Destinado a gestores, analistas e formuladores de políticas que buscam incorporar o design como abordagem metodológica para compreender melhor os problemas públicos, gerar soluções inovadoras e implementar políticas mais eficazes e orientadas às necessidades reais dos cida Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/506');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Políticas Públicas de Educação', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/502', 'gratuito', 'Iniciante', 'Políticas Públicas de Educação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Educação. Carga horária: 10h. Compreenda o financiamento, o planejamento e a infraestrutura das políticas públicas de educação! O curso aborda o financiamento da educação básica, o regime de colaboração, o papel dos municípios, o planejamento educacional com o PAR e a infraestrutura das escolas. Destinado a gestores, técnicos de secretarias e profissionais que atuam com políticas educacionais e buscam uma visão sistêmica dos instrumentos de financiamento, planejamento e implementação das políticas de educação básica no Brasi Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/502');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governo Aberto: Transparência e Dados Abertos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/500', 'gratuito', 'Iniciante', 'Governo Aberto: Transparência e Dados Abertos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 10h. Compreenda os fundamentos do governo aberto e implemente medidas concretas de transparência! O curso aborda o que é governo aberto, seus princípios fundamentais e como implementar medidas de abertura, participação e dados abertos. Destinado a gestores, analistas e servidores que desejam avançar na agenda de governo aberto, promovendo maior transparência, participação cidadã e uso de dados públicos na administração. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/500');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão estratégica e execução do plano de governo no dia a dia', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/496', 'gratuito', 'Iniciante', 'Gestão estratégica e execução do plano de governo no dia a dia — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 10h. Coloque a estratégia em ação e execute o plano de governo com eficácia no cotidiano! O curso aborda a estratégia em ação, a gestão de projetos e programas e o monitoramento e avaliação do plano. Destinado a gestores, coordenadores e analistas que precisam traduzir as prioridades estratégicas do governo em resultados concretos, utilizando instrumentos de gestão de projetos e monitoramento para garantir a entrega das metas assumidas perante a sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/496');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: LGPD: Como coordenar a atuação do município para a governança de dados aplicada', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/491', 'gratuito', 'Iniciante', 'LGPD: Como coordenar a atuação do município para a governança de dados aplicada — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 10h. Capacite seu município para a governança de dados pessoais em conformidade com a LGPD! O curso aborda as noções essenciais de proteção de dados, o município como agente de tratamento e a governança de dados aplicada ao contexto municipal. Destinado a gestores municipais, encarregados de dados e técnicos que precisam estruturar a conformidade com a LGPD nas prefeituras e garantir a proteção dos dados pessoais dos cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/491');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicação Pública e Comunicação de Governo', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/488', 'gratuito', 'Iniciante', 'Comunicação Pública e Comunicação de Governo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 10h. Desenvolva competências em comunicação pública e comunicação de governo! O curso aborda os conceitos básicos de comunicação pública e organizacional, comunicação na gestão, gestão de crises comunicacionais, especificidades da comunicação pública na web e gestão estratégica da comunicação. Destinado a gestores, assessores de comunicação e servidores que atuam na comunicação institucional e desejam qualificar sua atuação estratégica. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/488');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão Fiscal Municipal', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/487', 'gratuito', 'Iniciante', 'Gestão Fiscal Municipal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 10h. Domine a gestão fiscal municipal com competência e responsabilidade! O curso aborda o orçamento municipal, a arrecadação, os gastos e despesas públicas, a saúde fiscal do município e o plano de recuperação fiscal, incluindo questões práticas dos municípios. Destinado a prefeitos, secretários e técnicos municipais que precisam garantir o equilíbrio das finanças locais, a responsabilidade fiscal e a sustentabilidade financeira da gestão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/487');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova lei de licitações: Visão Geral', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/486', 'gratuito', 'Iniciante', 'Nova lei de licitações: Visão Geral — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 10h. Compreenda as principais inovações da Nova Lei de Licitações e seus impactos para os municípios! O curso aborda as inovações da Lei nº 14.133/2021 e as principais mudanças e impactos para o contexto municipal. Destinado a prefeitos, gestores municipais, agentes de contratação e vereadores que precisam de uma visão geral e objetiva das mudanças trazidas pelo novo marco legal das compras e contratações públicas para adaptar a gestão local à nova realidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/486');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ambiente e Condições para o Desenvolvimento Produtivo Local', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/485', 'gratuito', 'Iniciante', 'Ambiente e Condições para o Desenvolvimento Produtivo Local — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Desenvolvimento. Carga horária: 12h. Crie um ambiente favorável ao desenvolvimento produtivo local com inovação e parcerias! O curso aborda o desenvolvimento produtivo com apoio do Sebrae, a inovação com a agenda da OCDE e as cooperações e parcerias para o desenvolvimento municipal. Destinado a gestores, secretários e técnicos municipais que buscam estratégias e instrumentos para fomentar o desenvolvimento econômico local, apoiar o empreendedorismo e atrair investimentos para o município. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/485');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Português - Interpretação de Texto e Emprego de Regras Gramaticais', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/477', 'gratuito', 'Iniciante', 'Português - Interpretação de Texto e Emprego de Regras Gramaticais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 40h. Aprimore sua comunicação escrita com domínio da gramática e interpretação de textos! O curso aborda a gramática aplicada ao texto e as técnicas de interpretação textual. Destinado a servidores e profissionais que desejam aprimorar a redação oficial, melhorar a compreensão de documentos normativos e desenvolver uma comunicação escrita mais clara, precisa e adequada ao ambiente do serviço público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/477');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Criatividade e Inovação Aplicada ao Serviço Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/467', 'gratuito', 'Iniciante', 'Criatividade e Inovação Aplicada ao Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 25h. Desenvolva criatividade e inovação para transformar o serviço público! O curso aborda os conceitos e ferramentas de inovação, como inovar no setor público, o pensamento criativo, o processo criativo e as ferramentas e métodos disponíveis. Destinado a gestores, analistas e servidores que buscam desenvolver a mentalidade inovadora e aplicar técnicas criativas para resolver problemas, melhorar processos e criar soluções mais eficazes no contexto da administração pública. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/467');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fotografia Institucional', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/466', 'gratuito', 'Iniciante', 'Fotografia Institucional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 25h. Produza fotografias institucionais de qualidade com técnica e visão estética! O curso aborda a linguagem fotográfica e composição, os recursos do aparelho, a iluminação e as tecnologias digitais de fotografia. Destinado a servidores, comunicadores e profissionais que precisam produzir ou orientar a produção fotográfica institucional, garantindo imagens de qualidade que representem adequadamente os órgãos e eventos públicos com profissionalismo e identidade visual. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/466');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Comunicação não violenta', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/463', 'gratuito', 'Iniciante', 'Comunicação não violenta — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 20h. Desenvolva a comunicação não violenta e transforme suas relações profissionais e pessoais! O curso aborda os quatro componentes da CNV: observar, sentir, reconhecer necessidades e pedir, com aplicações práticas no cotidiano. Destinado a servidores, líderes e profissionais que desejam desenvolver uma comunicação mais empática, assertiva e construtiva, reduzindo conflitos e fortalecendo a confiança e a colaboração nas equipes e nas relações interpessoais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/463');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Design Thinking Aplicado à Educação', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/448', 'gratuito', 'Iniciante', 'Design Thinking Aplicado à Educação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 25h. Aplique o Design Thinking para inovar nos processos educacionais! O curso aborda o contexto do Design Thinking na educação, as etapas da metodologia — empatia, definição, ideação, prototipação e teste — e os eventos colaborativos e imersivos de inovação. Destinado a professores, coordenadores e gestores educacionais que desejam resolver problemas pedagógicos com criatividade, colaboração e foco nas necessidades dos estudantes e da comunidade escolar. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/448');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uso de Mídias Sociais na Comunicação Institucional', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/445', 'gratuito', 'Iniciante', 'Uso de Mídias Sociais na Comunicação Institucional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 20h. Potencialize a comunicação institucional com o uso estratégico das mídias sociais! O curso aborda a visão geral da comunicação, o panorama das redes sociais, o planejamento de conteúdo, noções de direção de criação e as principais estratégias para redes sociais. Destinado a gestores de comunicação, assessores e servidores que buscam ampliar o alcance e a eficácia da comunicação dos seus órgãos nas plataformas digitais de forma profissional e estratégica. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/445');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova Lei de Licitações: planejamento e governança', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/443', 'gratuito', 'Iniciante', 'Nova Lei de Licitações: planejamento e governança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 25h. Domine os fundamentos de planejamento e governança das contratações sob a Nova Lei de Licitações! O curso aborda as mudanças trazidas pela Lei nº 14.133/2021, a introdução ao planejamento e governança das contratações, a elaboração de Estudo Técnico Preliminar e de Termos de Referência. Destinado a gestores, agentes de contratação e servidores que precisam estruturar processos de compra mais seguros, planejados e alinhados ao novo marco legal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/443');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova Lei de Licitações: Sanções ao fornecedor', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/441', 'gratuito', 'Iniciante', 'Nova Lei de Licitações: Sanções ao fornecedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 25h. Aplique as sanções a fornecedores com segurança jurídica e proporcionalidade! O curso aborda as principais mudanças da LLCA, as infrações administrativas, as sanções ao fornecedor e as regras para sua aplicação. Destinado a gestores de contratos, agentes de contratação e juristas que precisam compreender o novo regime de sanções previsto na Lei nº 14.133/2021 para aplicar as penalidades de forma correta, proporcional e fundamentada. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/441');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova Lei de Licitações: Gestão Contratual', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/440', 'gratuito', 'Iniciante', 'Nova Lei de Licitações: Gestão Contratual — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 25h. Gerencie contratos sob a Nova Lei de Licitações com eficácia e segurança! O curso aborda os atores da fiscalização, as providências iniciais, as alterações contratuais e a responsabilidade da administração na terceirização. Destinado a fiscais e gestores de contratos que buscam compreender as mudanças trazidas pela Lei nº 14.133/2021 para a gestão contratual e garantir a execução dos contratos com qualidade, conformidade e proteção do interesse público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/440');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Nova Lei de Licitações: modalidade e seleção de fornecedores', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/439', 'gratuito', 'Iniciante', 'Nova Lei de Licitações: modalidade e seleção de fornecedores — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 25h. Domine as modalidades de licitação e os critérios de seleção de fornecedores na Nova Lei! O curso aborda as principais mudanças da Lei nº 14.133/2021, as modalidades de licitação, os critérios de julgamento e a habilitação de fornecedores. Destinado a pregoeiros, agentes de contratação e gestores de compras que precisam atualizar seu conhecimento sobre as novas modalidades e regras para conduzir processos licitatórios com mais segurança e eficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/439');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da Gestão da Logística Pública', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/437', 'gratuito', 'Iniciante', 'Fundamentos da Gestão da Logística Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Domine os fundamentos da logística pública com base na legislação vigente! O curso aborda noções básicas de licitações e logística, os princípios aplicados às licitações, o procedimento licitatório e os contratos administrativos. Destinado a servidores, gestores e técnicos que estão iniciando sua atuação na área de compras e logística pública e precisam de uma formação básica sólida para garantir a regularidade e a eficiência das contratações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/437');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Estilos de Aprendizagem', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/434', 'gratuito', 'Iniciante', 'Estilos de Aprendizagem — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. Compreenda os estilos de aprendizagem e aplique-os na tutoria e no design de cursos EaD! O curso aborda os estilos de aprendizagem, os sistemas de tutoria na EaD e estudos de caso práticos. Destinado a tutores, professores e designers instrucionais que buscam personalizar a experiência de aprendizagem nos ambientes virtuais, adaptando o conteúdo, as atividades e o suporte às diferentes formas como os estudantes processam e aprendem novas informações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/434');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração de Editais para Aquisições no Setor Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/431', 'gratuito', 'Iniciante', 'Elaboração de Editais para Aquisições no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 25h. Elabore editais de aquisição com qualidade técnica e conformidade legal! O curso aborda os aspectos gerais sobre contratação pública, o conteúdo do instrumento convocatório em seus aspectos introdutórios e o julgamento da proposta. Destinado a agentes de contratação, pregoeiros e gestores que precisam elaborar editais completos, claros e juridicamente seguros para garantir a competitividade, a transparência e a legalidade dos processos de seleção de fornecedores. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/431');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contratações Públicas Sustentáveis', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/430', 'gratuito', 'Iniciante', 'Contratações Públicas Sustentáveis — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Logística e Compras Públicas. Carga horária: 20h. Incorpore a sustentabilidade nas contratações públicas com base legal e técnica sólida! O curso aborda meio ambiente e sustentabilidade, os princípios das contratações sustentáveis, a sustentabilidade aplicada às licitações e a gestão sustentável dos contratos. Destinado a gestores, pregoeiros e agentes de contratação que desejam promover compras públicas mais responsáveis, ambientalmente corretas e alinhadas à Agenda 2030 e à legislação vigente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/430');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Contabilidade com Foco na Gestão do Orçamento Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/429', 'gratuito', 'Iniciante', 'Contabilidade com Foco na Gestão do Orçamento Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 20h. Domine a contabilidade aplicada ao orçamento público e qualifique a gestão financeira! O curso aborda os conceitos básicos, os procedimentos contábeis orçamentários de receita e despesa, a gestão de suprimentos de fundos, restos a pagar, precatórios e a conciliação bancária. Destinado a contadores, técnicos contábeis e gestores que precisam compreender e aplicar os registros contábeis orçamentários no setor público com precisão e conformidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/429');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Transformação Digital no Serviço Público', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/419', 'gratuito', 'Iniciante', 'Transformação Digital no Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Lidere a transformação digital dos serviços públicos com visão estratégica! O curso aborda a contextualização da transformação dos serviços digitais e o planejamento e desenho da transformação. Destinado a gestores, analistas e técnicos que atuam na modernização dos serviços públicos e desejam compreender os princípios, as etapas e as boas práticas da transformação digital, colocando o cidadão no centro do processo de redesenho dos serviços. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/419');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ambientes Digitais de Aprendizagem', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/418', 'gratuito', 'Iniciante', 'Ambientes Digitais de Aprendizagem — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. Compreenda os ambientes virtuais de aprendizagem e utilize-os com eficácia na educação! O curso aborda o que são os AVAs, as características da cibercultura e sua relação com esses ambientes e a tecnologia assistiva nos ambientes digitais. Destinado a professores, tutores e gestores de EaD que desejam explorar ao máximo as funcionalidades dos ambientes virtuais de aprendizagem e promover experiências educativas mais acessíveis, engajantes e eficazes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/418');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão da Inovação no Setor Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/416', 'gratuito', 'Iniciante', 'Gestão da Inovação no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 20h. Gerencie a inovação no setor público com visão estratégica e foco em resultados! O curso aborda a inovação e o contexto do setor público, as perspectivas do design thinking e como construir a capacidade de inovação nas organizações governamentais. Destinado a gestores, analistas e líderes de inovação que buscam estruturar processos e culturas de inovação no setor público, transformando a administração por meio de soluções criativas e centradas nas necessidades dos cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/416');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Projetos Educacionais', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/415', 'gratuito', 'Iniciante', 'Gestão de Projetos Educacionais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 30h. Gerencie projetos educacionais com planejamento, método e eficácia! O curso aborda o planejamento e a gestão de projetos educacionais, o desenvolvimento e a aplicação e as metodologias de gestão de projetos aplicadas à educação. Destinado a gestores, coordenadores e profissionais da educação que buscam estruturar e executar projetos educacionais com mais organização, controle de prazos e foco na entrega de resultados de aprendizagem para os estudantes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/415');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Análise de dados como suporte à tomada de decisão', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/406', 'gratuito', 'Iniciante', 'Análise de dados como suporte à tomada de decisão — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 30h. Utilize a análise de dados para apoiar decisões mais informadas e eficazes! O curso aborda a introdução à análise de dados, o pré-processamento, a análise descritiva e o desenvolvimento de painéis de Business Intelligence. Destinado a gestores, analistas e servidores que buscam desenvolver competências básicas em análise de dados e uso de ferramentas de BI para transformar dados em informações acionáveis que qualifiquem as decisões no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/406');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Instrumentos de Planejamento: PPA, LDO e LOA', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/404', 'gratuito', 'Iniciante', 'Instrumentos de Planejamento: PPA, LDO e LOA — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 14h. Domine os instrumentos de planejamento governamental e articule estratégia e orçamento! O curso aborda as políticas públicas e o planejamento governamental, o ciclo orçamentário e as especificidades do PPA, da LDO e da LOA, incluindo o SIOP. Destinado a gestores, analistas e técnicos de planejamento e orçamento que precisam compreender a articulação entre os instrumentos de planejamento e como utilizá-los para alinhar as políticas públicas com a alocação de recursos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/404');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direito à Identidade, Cidadania e Documentação', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/397', 'gratuito', 'Iniciante', 'Direito à Identidade, Cidadania e Documentação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Participação e Cidadania. Carga horária: 30h. Garanta o direito à identidade e à documentação básica para todos os cidadãos! O curso aborda o registro civil e a documentação básica no Brasil, as políticas públicas de enfrentamento ao sub-registro e as populações vulnerabilizadas. Destinado a gestores, profissionais de assistência social, saúde e educação que atuam com populações em situação de vulnerabilidade e desejam garantir o acesso à documentação como condição para o exercício pleno da cidadania. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/397');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Scrum no Contexto do Serviço Público', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/395', 'gratuito', 'Iniciante', 'Scrum no Contexto do Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 15h. Aplique a metodologia Scrum para modernizar a gestão de projetos no serviço público! O curso aborda o que é o Scrum e para que serve, os papéis na equipe, o fluxo de trabalho e como aplicar o Scrum na administração pública. Destinado a gestores, analistas e equipes de TI e projetos que desejam adotar práticas ágeis para entregar resultados com mais velocidade, flexibilidade e colaboração no contexto governamental. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/395');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Processo Legislativo Orçamentário - Orçamento Impositivo', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/392', 'gratuito', 'Iniciante', 'Processo Legislativo Orçamentário - Orçamento Impositivo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 21h. Compreenda o processo legislativo orçamentário e o papel do orçamento impositivo no Brasil! O curso aborda as características do processo legislativo orçamentário, as competências do Congresso Nacional e da CMO, as emendas parlamentares e as transferências especiais. Destinado a parlamentares, assessores, analistas de orçamento e gestores que precisam compreender o funcionamento do ciclo legislativo do orçamento público federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/392');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Crianças e Adolescentes Migrantes', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/381', 'gratuito', 'Iniciante', 'Crianças e Adolescentes Migrantes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 40h. Proteja os direitos de crianças e adolescentes em situação de migração! O curso aborda os direitos dessa população nas migrações internacionais, estratégias de integração e os mecanismos de defesa contra exploração, abuso e violência. Destinado a profissionais da assistência social, saúde, educação e segurança pública que atendem crianças e adolescentes migrantes e precisam de uma abordagem de proteção integral. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/381');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Migração e Saúde', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/380', 'gratuito', 'Iniciante', 'Migração e Saúde — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Saúde. Carga horária: 30h. Qualifique o cuidado em saúde para a população migrante com uma abordagem baseada em direitos! O curso aborda a saúde como direito internacional, a migração como determinante social de saúde, a superação dos desafios no cuidado e a humanização no atendimento. Destinado a profissionais de saúde, gestores e técnicos que atendem populações migrantes e buscam desenvolver competências para um cuidado mais equitativo, culturalmente sensível e baseado nos direitos humanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/380');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governança de TIC no contexto da transformação digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/379', 'gratuito', 'Iniciante', 'Governança de TIC no contexto da transformação digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Implemente a governança de TIC como alicerce da transformação digital! O curso aborda as bases da governança de TIC, a governança de TIC no setor público, no contexto da transformação digital e a gestão de riscos de TIC. Destinado a gestores de TI, CIOs e técnicos que buscam estruturar uma governança de TIC alinhada às estratégias da organização e às demandas da transformação digital, garantindo a segurança, a qualidade e o valor dos investimentos em tecnologia. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/379');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Segurança da Informação no contexto da transformação digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/378', 'gratuito', 'Iniciante', 'Segurança da Informação no contexto da transformação digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 20h. Implemente a segurança da informação como alicerce da transformação digital! O curso aborda a relação entre segurança e transformação digital, a política de segurança da informação, a segurança de dados e a gestão de riscos digitais. Destinado a gestores, técnicos de TI e profissionais que atuam na digitalização de processos e serviços públicos e precisam garantir a proteção das informações e a resiliência cibernética das organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/378');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligência Artificial no Contexto do Serviço Público', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/377', 'gratuito', 'Iniciante', 'Inteligência Artificial no Contexto do Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inteligência Artificial. Carga horária: 20h. Compreenda a IA e aplique-a para resolver problemas no serviço público! O curso aborda a contextualização e os conceitos sobre IA, as principais tecnologias disponíveis e a resolução de problemas nas organizações com suporte da inteligência artificial. Destinado a gestores, analistas e servidores que buscam compreender o potencial transformador da IA e identificar oportunidades práticas de aplicação para melhorar processos, serviços e decisões no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/377');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Liderança e Gestão De Equipes', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/373', 'gratuito', 'Iniciante', 'Liderança e Gestão De Equipes — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 30h. Desenvolva sua liderança e a gestão de equipes com excelência! O curso aborda a essência da liderança, as técnicas e abordagens para trabalho em equipe e o clima organizacional como propulsor das equipes. Destinado a gestores, coordenadores e líderes que buscam aprimorar sua capacidade de inspirar, engajar e coordenar equipes com mais eficácia, promovendo um ambiente de trabalho positivo, colaborativo e orientado a resultados. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/373');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos da Integridade Pública: Prevenindo a Corrupção', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/370', 'gratuito', 'Iniciante', 'Fundamentos da Integridade Pública: Prevenindo a Corrupção — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 25h. Construa uma cultura de integridade no serviço público e previna a corrupção! O curso aborda os fundamentos da integridade pública, os riscos para a integridade e as estruturas de integridade que devem ser implantadas nas organizações. Destinado a gestores, servidores e agentes de integridade que buscam compreender os fundamentos da integridade pública e implementar medidas preventivas contra a corrupção nas organizações do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/370');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Novas Tecnologias para a Transformação Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/367', 'gratuito', 'Iniciante', 'Novas Tecnologias para a Transformação Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 30h. Compreenda as principais tecnologias que impulsionam a transformação digital! O curso aborda os pilares das tecnologias disruptivas, a inteligência artificial, a Internet das Coisas, a blockchain e a computação em nuvem. Destinado a gestores, analistas e técnicos que desejam compreender o ecossistema tecnológico da transformação digital para identificar oportunidades, tomar decisões mais informadas e modernizar os serviços e processos da sua organização. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/367');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: O papel do DevOps na Transformação Digital dos Serviços Públicos', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/366', 'gratuito', 'Iniciante', 'O papel do DevOps na Transformação Digital dos Serviços Públicos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Implemente práticas DevOps para acelerar a transformação digital dos serviços públicos! O curso aborda o que é DevOps, o planejamento e os requisitos de um ambiente DevOps e a implantação com as ferramentas utilizadas. Destinado a gestores de TI, analistas e desenvolvedores que desejam adotar a cultura DevOps para integrar equipes de desenvolvimento e operações, aumentar a velocidade de entrega de software e elevar a qualidade dos serviços digitais governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/366');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Elaboração Legislativa no Executivo: Legística, Governança e Avaliação', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/360', 'gratuito', 'Iniciante', 'Elaboração Legislativa no Executivo: Legística, Governança e Avaliação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direito e Legislação. Carga horária: 30h. Domine a elaboração legislativa no Executivo com governança regulatória e técnica de legística! O curso aborda a governança legislativo-regulatória, as técnicas de elaboração de atos normativos e a avaliação de impacto legislativo-regulatório. Destinado a assessores jurídicos, analistas e gestores que participam da produção normativa e buscam qualificar a elaboração de leis e regulamentos com base em governança regulatória e avaliação de impacto. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/360');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Desenvolvendo Times de Alta Performance', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/356', 'gratuito', 'Iniciante', 'Desenvolvendo Times de Alta Performance — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 30h. Eleve o desempenho das suas equipes com competências gerenciais avançadas! O curso aborda as competências essenciais para líderes, técnicas de coaching aplicadas à gestão de pessoas e as ferramentas que caracterizam um time de alta performance. Destinado a gestores, coordenadores e líderes que desejam desenvolver equipes mais engajadas, produtivas e orientadas a resultados no contexto do serviço público e corporativo. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/356');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governança de TIC para o Governo Digital', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/348', 'gratuito', 'Iniciante', 'Governança de TIC para o Governo Digital — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 40h. Implemente a governança de TIC como pilar do governo digital! O curso aborda a transformação digital e o novo perfil do cidadão, o governo aberto e as novas tecnologias para inovação e a governança de TIC aplicada ao governo digital. Destinado a gestores de TI, dirigentes e analistas que buscam alinhar a governança tecnológica às demandas do governo digital, promovendo serviços mais acessíveis, transparentes e orientados ao cidadão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/348');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Gestão e Apuração da Ética Pública', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/347', 'gratuito', 'Iniciante', 'Introdução à Gestão e Apuração da Ética Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 24h. Compreenda a estrutura e o funcionamento das comissões de ética no serviço público! O curso aborda as estruturas das comissões de ética, as características da Comissão de Ética Pública (CEP), as formalidades do processo de apuração ética e as fases do procedimento. Destinado a membros de comissões de ética, gestores e servidores que atuam na gestão e apuração da ética pública e buscam compreender os procedimentos e as boas práticas para conduzir os processos com imparcialidade e método. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/347');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Mudança do Clima e Gestão de Risco Climático: Conceitos Fundamentais', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/346', 'gratuito', 'Iniciante', 'Mudança do Clima e Gestão de Risco Climático: Conceitos Fundamentais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 24h. Compreenda as mudanças climáticas e os fundamentos da gestão de risco climático! O curso aborda os compromissos internacionais, as políticas nacionais climáticas, os conceitos de gestão de risco associados à mudança do clima e o panorama das ferramentas disponíveis. Destinado a gestores, técnicos e formuladores de políticas que precisam de base conceitual sólida para incorporar a gestão do risco climático em suas decisões e planos de adaptação. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/346');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Learning with Python', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/338', 'gratuito', 'Iniciante', 'Learning with Python — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Start your programming journey with Python, one of the world''s most versatile languages! This course covers variables, operations and conditions, loops and functions, basic data structures, object-oriented programming and practical applications of libraries. Ideal for professionals seeking to automate tasks, enter the data science field or develop digital solutions, with no prior programming experience required. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/338');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Empresas e Direitos Humanos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/333', 'gratuito', 'Iniciante', 'Empresas e Direitos Humanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda as obrigações e responsabilidades das empresas em relação aos Direitos Humanos! O curso aborda o dever dos Estados de proteger e das empresas de respeitar os direitos humanos, o acesso a remédios e as diretrizes da ONU sobre empresas e direitos humanos. Destinado a gestores, advogados, analistas de compliance e profissionais que atuam com responsabilidade social corporativa e buscam alinhar as práticas empresariais aos padrões internacionais de direitos humanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/333');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Linguagem simples aproxima o governo das pessoas. Como usar?', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/332', 'gratuito', 'Iniciante', 'Linguagem simples aproxima o governo das pessoas. Como usar? — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 20h. Transforme a comunicação do governo com linguagem simples e cidadã! O curso aborda o que é a linguagem simples, como usá-la na prática e como disseminar a cultura de comunicação clara nos órgãos públicos. Destinado a servidores, comunicadores e gestores que buscam tornar os textos, formulários e comunicações do governo mais acessíveis, compreensíveis e úteis para todos os cidadãos, independentemente de seu nível de escolaridade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/332');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Princípios do Design Thinking e Inovação em Governo', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/326', 'gratuito', 'Iniciante', 'Princípios do Design Thinking e Inovação em Governo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 10h. Aplique os princípios do Design Thinking para inovar nos serviços e políticas de governo! O curso aborda o que é design, o Design Thinking, o modelo do duplo diamante, o design centrado no ser humano, os três princípios do design e sua aplicação no setor público. Destinado a gestores, analistas e servidores que buscam desenvolver uma mentalidade de design para criar soluções inovadoras centradas nas necessidades reais dos cidadãos nas políticas e serviços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/326');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Análise de Dados em Linguagem R', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/325', 'gratuito', 'Iniciante', 'Análise de Dados em Linguagem R — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Aprenda a analisar dados com a linguagem R do básico ao machine learning! O curso aborda a introdução à análise de dados, os fundamentos da linguagem R, uma introdução ao machine learning e a análise de dados na prática. Destinado a analistas, cientistas de dados e profissionais que desejam usar o R para explorar, visualizar e modelar dados, aplicando técnicas de análise estatística e aprendizado de máquina em problemas reais do setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/325');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Audiodescrição', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/320', 'gratuito', 'Iniciante', 'Introdução à Audiodescrição — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 40h. Amplie o acesso à comunicação e à cultura por meio da audiodescrição! O curso apresenta os fundamentos da audiodescrição, técnicas aplicadas a sites e internet, audiodescrição na cultura, em livros e publicações, além dos princípios de comunicação acessível. Essencial para profissionais de comunicação, cultura e tecnologia que desejam tornar conteúdos digitais e culturais acessíveis às pessoas com deficiência visual. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/320');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inteligência Emocional', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/318', 'gratuito', 'Intermediário', 'Inteligência Emocional — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 50h. Desenvolva a inteligência emocional e transforme suas relações profissionais e pessoais! O curso aborda a gestão das emoções pessoais, a gestão emocional nas relações interpessoais, a construção de um ambiente de trabalho positivo e a liderança positiva. Destinado a gestores, servidores e profissionais que buscam desenvolver o autoconhecimento emocional, a empatia e a capacidade de gerenciar emoções para construir relações mais saudáveis, produtivas e colaborativas no trabalho. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/318');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Primeiros passos para uso de Linguagem Simples', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/315', 'gratuito', 'Iniciante', 'Primeiros passos para uso de Linguagem Simples — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Comunicação Institucional. Carga horária: 8h. Comunique-se com clareza e empatia usando a Linguagem Simples! O curso aborda o modelo Comunica Simples, a importância da empatia na escrita, a hierarquia das informações e a escolha de palavras acessíveis ao público. Destinado a servidores, comunicadores e redatores oficiais que desejam tornar os textos institucionais — comunicados, formulários, sites — mais compreensíveis, acessíveis e orientados às necessidades reais dos cidadãos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/315');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Proteção a Direitos Humanos: Prevenção e Proibição da Tortura', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/306', 'gratuito', 'Iniciante', 'Proteção a Direitos Humanos: Prevenção e Proibição da Tortura — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda a tortura como violação grave dos direitos humanos e atue na sua prevenção! O curso aborda o conceito de tortura, as vítimas, as responsabilidades dos Poderes do Estado no combate à tortura e as articulações para prevenção e enfrentamento, com estudos de caso. Destinado a profissionais do sistema de justiça, segurança pública e direitos humanos que atuam na prevenção, identificação e enfrentamento da tortura no Brasil. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/306');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Auditoria e Controle Para Estatais', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/302', 'gratuito', 'Iniciante', 'Auditoria e Controle Para Estatais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 20h. Desenvolva competências em auditoria interna e controle nas empresas estatais! O curso aborda o histórico e a importância da auditoria interna moderna, o papel da auditoria em organizações, o Controle Interno — Estrutura Integrada — e como a auditoria pode ajudar a empresa. Destinado a auditores internos, controladores e gestores de estatais que desejam fortalecer a função de auditoria como suporte à governança e ao desempenho organizacional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/302');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Teletrabalho e Educação a Distância', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/301', 'gratuito', 'Iniciante', 'Teletrabalho e Educação a Distância — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 8h. Compreenda o teletrabalho e a educação a distância como modalidades complementares do trabalho contemporâneo! O curso aborda os conceitos de teletrabalho, as ferramentas disponíveis, os fundamentos da web, a educação online e um histórico da EaD. Destinado a servidores, gestores e educadores que buscam uma visão integrada sobre teletrabalho e EaD para adaptar suas práticas profissionais e pedagógicas ao ambiente remoto e digital. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/301');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Riscos em Processos de Trabalho (segundo o Coso)', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/300', 'gratuito', 'Iniciante', 'Gestão de Riscos em Processos de Trabalho (segundo o Coso) — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Governança. Carga horária: 20h. Implemente a gestão de riscos nos processos de trabalho com base no COSO ERM! O curso aborda as estruturas de gerenciamento e bases normativas, o COSO ERM com seus componentes de ambiente de controle, avaliação de riscos, atividades de controle, informação e comunicação e monitoramento. Destinado a auditores, controladores e gestores que desejam estruturar uma abordagem sistemática de identificação e tratamento de riscos organizacionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/300');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: A Liderança Pública em Tempos de Crise', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/299', 'gratuito', 'Iniciante', 'A Liderança Pública em Tempos de Crise — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 10h. Desenvolva sua liderança pública em contextos de crise e emergência! O curso aborda como liderar em tempos de crise, as boas práticas de enfrentamento, as diretrizes oficiais e a atenção aos agentes invisíveis. Destinado a gestores e líderes do setor público que precisam desenvolver competências para tomar decisões rápidas, comunicar com clareza e manter a coesão das equipes em situações de crise e emergência, como pandemias, desastres ou crises institucionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/299');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: MigraCidades: Aprimorando a Governança Migratória Local', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/297', 'gratuito', 'Iniciante', 'MigraCidades: Aprimorando a Governança Migratória Local — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão Federativa. Carga horária: 30h. Aprimore a governança migratória local com o MigraCidades! O curso aborda a estrutura institucional de governança, a capacitação de servidores e a sensibilização sobre direitos dos migrantes e a participação social e cultural dos migrantes na cidade. Destinado a gestores e técnicos municipais que precisam estruturar e qualificar a governança migratória local, promovendo a inclusão social e a proteção dos direitos dos migrantes no âmbito municipal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/297');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Orçamento Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/296', 'gratuito', 'Iniciante', 'Orçamento Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 40h. Domine o ciclo orçamentário e os fundamentos do orçamento público brasileiro! O curso aborda os conceitos e fundamentos, os instrumentos do processo orçamentário, a receita e a despesa orçamentária, a execução e o acompanhamento. Destinado a gestores, analistas e servidores que precisam compreender o ciclo orçamentário completo — da elaboração do PPA à execução da LOA — para atuar com qualidade na gestão dos recursos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/296');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Proteção de Dados Pessoais no Setor Público', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/290', 'gratuito', 'Iniciante', 'Proteção de Dados Pessoais no Setor Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 15h. Implemente a proteção de dados pessoais no setor público com base na LGPD! O curso aborda o tratamento de dados pessoais no setor público, o ciclo de vida dos dados, as medidas de segurança e o Relatório de Impacto à Proteção de Dados. Destinado a encarregados de dados, gestores de TI e servidores dos órgãos públicos que precisam compreender as especificidades da LGPD aplicada ao setor público e estruturar um programa de proteção de dados eficaz. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/290');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: S2ID - M0 - Todos - Acesso ao Sistema', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/284', 'gratuito', 'Iniciante', 'S2ID - M0 - Todos - Acesso ao Sistema — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Segurança e Defesa. Carga horária: 20h. Aprenda a acessar e utilizar o Sistema Integrado de Informações sobre Desastres (S2ID)! O curso aborda as funcionalidades de consulta ao sistema e os procedimentos básicos de utilização. Destinado a gestores, técnicos de defesa civil e servidores federais, estaduais e municipais que precisam consultar ou registrar informações sobre desastres e situações de emergência no sistema S2ID do governo federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/284');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Tesouro Gerencial', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/283', 'gratuito', 'Intermediário', 'Tesouro Gerencial — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 60h. Domine o Tesouro Gerencial para consultar e analisar dados orçamentários e financeiros do governo federal! O curso aborda o histórico e a arquitetura do sistema, a estrutura da informação, o acesso e a navegação, os conceitos do Tesouro Gerencial e os conceitos sobre orçamento público aplicados. Destinado a analistas, gestores e técnicos de orçamento e finanças que precisam utilizar o Tesouro Gerencial para acessar dados detalhados da execução orçamentária e financeira federal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/283');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Controles na Administração Pública', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/278', 'gratuito', 'Iniciante', 'Controles na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 30h. Compreenda os mecanismos de controle na administração pública e atue com responsabilidade! O curso aborda a prestação de contas, o controle na APF, o controle externo, o controle interno e o controle social. Destinado a gestores, auditores, servidores e conselheiros que buscam compreender o sistema de controle da administração pública e a importância da prestação de contas e da transparência para a boa governança e a integridade institucional. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/278');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Acessibilidade em espaços de uso público no Brasil', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/275', 'gratuito', 'Iniciante', 'Acessibilidade em espaços de uso público no Brasil — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 20h. Promova a acessibilidade nos espaços de uso público com fundamentação histórica e técnica! O curso aborda as lutas por inclusão das pessoas com deficiência, as relações entre espaços humanos, deficiências e atividades e os princípios de acessibilidade para a atuação profissional. Destinado a arquitetos, engenheiros, gestores urbanos e profissionais que precisam compreender e aplicar os requisitos de acessibilidade no projeto e na gestão dos espaços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/275');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Acessibilidade em espaços edificados de uso público', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/274', 'gratuito', 'Iniciante', 'Acessibilidade em espaços edificados de uso público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 20h. Promova a acessibilidade nos espaços edificados de uso público com base técnica e normativa! O curso aborda as diretrizes gerais e específicas de acessibilidade em edifícios públicos, incluindo sanitários, banheiros e vestiários. Destinado a arquitetos, engenheiros, gestores de edificações públicas e técnicos que buscam garantir que os espaços construídos estejam em conformidade com as normas de acessibilidade e sejam plenamente utilizáveis por pessoas com deficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/274');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Acessibilidade em espaços urbanos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/273', 'gratuito', 'Iniciante', 'Acessibilidade em espaços urbanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Transportes e Mobilidade Urbana. Carga horária: 16h. Promova cidades mais inclusivas e acessíveis para todos! O curso aborda os princípios de acessibilidade urbana, mobilidade e acessibilidade nos sistemas de transporte, além da acessibilidade em áreas livres públicas de lazer. Destinado a gestores, arquitetos, urbanistas e profissionais de mobilidade que desejam aplicar as normas e boas práticas de acessibilidade no planejamento e gestão dos espaços urbanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/273');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Fundamentos e Metodologia da Educação Corporativa', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/271', 'gratuito', 'Iniciante', 'Fundamentos e Metodologia da Educação Corporativa — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 40h. Estruture a educação corporativa com fundamentos pedagógicos sólidos! O curso aborda a educação na formação profissional, a aprendizagem de adultos, as tecnologias educacionais, o planejamento do ensino-aprendizagem e a relação entre educação e trabalho. Destinado a designers instrucionais, gestores de RH e profissionais de T&D que buscam construir programas de educação corporativa mais eficazes, baseados em teorias de aprendizagem e alinhados às necessidades das organizações. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/271');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governança de Dados', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/270', 'gratuito', 'Iniciante', 'Governança de Dados — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 30h. Implemente a governança de dados na administração pública com estratégia e método! O curso aborda o contexto da governança de dados, os princípios, a importância e os desafios do gerenciamento de dados, a gestão inteligente e o gerenciamento de dados abertos. Destinado a gestores, analistas e técnicos que buscam estruturar políticas, processos e responsabilidades para garantir a qualidade, a segurança e o uso estratégico dos dados nas organizações públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/270');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Uma Introdução às Migrações Internacionais no Brasil Contemporâneo', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/269', 'gratuito', 'Iniciante', 'Uma Introdução às Migrações Internacionais no Brasil Contemporâneo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 40h. Compreenda as migrações internacionais no Brasil e as bases legais para o atendimento qualificado! O curso aborda uma introdução às migrações, a sensibilização para o atendimento ao público migrante, a nova Lei de Migração e a legislação de proteção a refugiados. Destinado a servidores, técnicos e gestores que interagem com populações migrantes e precisam de base legal e humanística para oferecer um atendimento respeitoso, informado e baseado nos direitos dos migrantes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/269');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Acessibilidade em Museus', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/268', 'gratuito', 'Iniciante', 'Acessibilidade em Museus — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 20h. Torne os museus mais inclusivos e acessíveis para todos os públicos! O curso aborda os tipos de deficiências, a importância da acessibilidade universal nos museus, o histórico da acessibilidade, o roteiro de visita e circulação acessível e a experiência espacial inclusiva. Destinado a gestores, educadores e profissionais de museus que desejam promover a acessibilidade em seus espaços, garantindo que pessoas com deficiência possam desfrutar plenamente do patrimônio cultural. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/268');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Documentação de Acervo Museológico', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/265', 'gratuito', 'Iniciante', 'Documentação de Acervo Museológico — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 40h. Domine a documentação museológica e preserve o patrimônio cultural com qualidade! O curso aborda a entrada do objeto no museu, o histórico e a importância da documentação, a legislação museológica, o código de ética e os instrumentos de documentação. Destinado a museólogos, conservadores e técnicos de museus que buscam aprimorar suas práticas de catalogação, controle e documentação de acervos, garantindo a integridade e a acessibilidade do patrimônio cultural sob sua guarda. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/265');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Equilíbrio Fiscal', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/261', 'gratuito', 'Iniciante', 'Equilíbrio Fiscal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 40h. Compreenda os fundamentos do equilíbrio fiscal e seu papel na gestão responsável do Estado! O curso aborda o que são economia, mercado, governo e equilíbrio das contas públicas, impostos, o papel do Estado e como as decisões fiscais afetam todos os cidadãos. Destinado a servidores, gestores e cidadãos que desejam compreender de forma acessível como funciona o equilíbrio das contas públicas e por que ele é essencial para a sustentabilidade dos serviços públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/261');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Administração de Serviços na Nuvem de Governo', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/259', 'gratuito', 'Iniciante', 'Administração de Serviços na Nuvem de Governo — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 30h. Administre serviços governamentais na nuvem com segurança e eficiência! O curso aborda a visão geral da computação em nuvem, a infraestrutura básica, os mecanismos de segurança e o aprisionamento tecnológico. Destinado a gestores e técnicos de TI do setor público que precisam compreender e gerenciar a infraestrutura de nuvem governamental, garantindo a segurança das informações, a continuidade dos serviços e a prevenção de situações de lock-in tecnológico. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/259');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão Orçamentária e Financeira', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/257', 'gratuito', 'Iniciante', 'Gestão Orçamentária e Financeira — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 20h. Domine a gestão orçamentária e financeira do setor público com método e conformidade! O curso aborda o planejamento e o orçamento, o PPA, a LDO e a LOA, o ciclo e os princípios orçamentários, os créditos adicionais, a discussão e votação do orçamento e o controle e avaliação. Destinado a gestores, técnicos e servidores que buscam uma compreensão abrangente do ciclo orçamentário e das técnicas de gestão financeira para atuar com mais competência na administração dos recursos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/257');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Sustentabilidade na Administração Pública', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/254', 'gratuito', 'Iniciante', 'Sustentabilidade na Administração Pública — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 28h. Incorpore a sustentabilidade na gestão pública e contribua para um futuro mais equilibrado! O curso aborda o histórico das conferências internacionais sobre meio ambiente, os conceitos de sustentabilidade e ODS, a Agenda Ambiental na Administração Pública (A3P), o Plano de Logística Sustentável e as compras públicas sustentáveis, com base nos acórdãos do TCU. Destinado a servidores e gestores que desejam promover práticas sustentáveis no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/254');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Mundo Conectado – Manual de Sobrevivência', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/252', 'gratuito', 'Iniciante', 'Mundo Conectado – Manual de Sobrevivência — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 10h. Navegue com segurança no mundo digital e proteja suas informações! O curso aborda os desafios de segurança do mundo conectado, as causas e consequências do SPAM, medidas eficazes para evitá-lo e como reduzir o volume de mensagens indesejadas. Destinado a servidores, profissionais e cidadãos que desejam adotar práticas seguras no ambiente digital, proteger seus dados pessoais e profissionais e usar a internet com mais consciência e responsabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/252');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Desenho Instrucional para Soluções de Capacitações Presenciais', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/250', 'gratuito', 'Iniciante', 'Desenho Instrucional para Soluções de Capacitações Presenciais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 40h. Projete soluções de capacitação presencial com método e qualidade pedagógica! O curso aborda o ensino e a aprendizagem de adultos, a teoria experiencial de Kolb, a abordagem sistêmica do desenho instrucional e os fundamentos do design educacional. Destinado a designers instrucionais, formadores e gestores de educação corporativa que buscam estruturar cursos presenciais mais eficazes, engajantes e alinhados às necessidades de aprendizagem dos participantes. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/250');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Portal Gov.Br', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/247', 'gratuito', 'Iniciante', 'Portal Gov.Br — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 15h. Domine o Portal Gov.Br e estruture a presença digital do seu órgão com qualidade! O curso aborda o processo de migração para a plataforma, a publicação de conteúdo e a gestão do site institucional. Destinado a servidores, comunicadores e gestores de conteúdo digital que atuam na manutenção e atualização dos portais institucionais do governo federal, garantindo clareza, padronização e acessibilidade das informações para o cidadão. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/247');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Atividade Correcional - Visão Geral', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/238', 'gratuito', 'Iniciante', 'Atividade Correcional - Visão Geral — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 25h. Conheça a atividade correcional no serviço público e sua importância para a integridade institucional! O curso aborda o procedimento correcional, as sanções aplicáveis, a Lei Anticorrupção, os procedimentos de responsabilização de entes privados e canais de denúncia, com casos práticos sobre as principais infrações disciplinares. Destinado a servidores, corregedores e gestores que atuam ou têm interesse na atividade correcional no setor público. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/238');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Inovação Social para o Aperfeiçoamento de Políticas Públicas', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/234', 'gratuito', 'Iniciante', 'Inovação Social para o Aperfeiçoamento de Políticas Públicas — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Inovação. Carga horária: 40h. Aplique a inovação social para aperfeiçoar as políticas públicas! O curso aborda por que a inovação social é necessária, as riquezas e desafios do Brasil, o conceito de inovação social, como ela sustenta as políticas públicas e os critérios para avaliar e apoiar iniciativas inovadoras. Destinado a gestores, formuladores de políticas e técnicos que buscam incorporar a perspectiva da inovação social no desenho e na implementação de políticas mais eficazes e centradas nas pessoas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/234');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ética Profissional do Serviço Público na Receita Federal do Brasil', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/232', 'gratuito', 'Iniciante', 'Ética Profissional do Serviço Público na Receita Federal do Brasil — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 20h. Fortaleça os fundamentos éticos da atuação profissional na Receita Federal! O curso aborda os conceitos e regras deontológicas, os princípios basilares, o sistema de gestão da ética no serviço público e os fundamentos específicos da ética na RFB. Destinado a auditores fiscais, analistas tributários e servidores da RFB que buscam compreender e aplicar os padrões de ética profissional que devem nortear sua conduta no exercício das funções fiscais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/232');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Noções Básicas para Coordenar Cursos On-line', 'curso', 'Educação & Pedagogia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/198', 'gratuito', 'Iniciante', 'Noções Básicas para Coordenar Cursos On-line — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Educação e Docência. Carga horária: 20h. Coordene cursos online com competência e foco na qualidade da aprendizagem! O curso aborda o contexto da educação online, a evolução da EaD, o processo educativo e a função da coordenação. Destinado a professores, tutores e gestores de educação a distância que precisam compreender as bases da coordenação de cursos online para garantir a qualidade pedagógica e a satisfação dos cursistas em ambientes virtuais de aprendizagem. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/198');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Fiscal - Orçamento e Coesão Social', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/184', 'gratuito', 'Iniciante', 'Educação Fiscal - Orçamento e Coesão Social — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Política Fiscal e Tributária. Carga horária: 40h. Compreenda a educação fiscal como instrumento de cidadania e coesão social! O curso aborda o planejamento orçamentário, a execução orçamentária e financeira, as compras governamentais e a publicidade e transparência das finanças e políticas públicas. Destinado a servidores, educadores e cidadãos que buscam compreender como o orçamento público e a fiscalidade se articulam com a coesão social e a construção de uma sociedade mais justa e responsável fiscalmente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/184');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação Fiscal - Estado e Tributação', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/172', 'gratuito', 'Iniciante', 'Educação Fiscal - Estado e Tributação — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Política Fiscal e Tributária. Carga horária: 40h. Compreenda a relação entre Estado, tributação e cidadania com uma perspectiva histórica e republicana! O curso aborda o Estado Liberal à contemporaneidade brasileira, os fundamentos do Estado Republicano, a cidadania fiscal e a educação fiscal como instrumento de formação cívica. Destinado a servidores, educadores e cidadãos que buscam compreender os fundamentos históricos e filosóficos da tributação e sua relação com os deveres e direitos da cidadania democrática. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/172');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão de Finanças Pessoais', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/170', 'gratuito', 'Iniciante', 'Gestão de Finanças Pessoais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Desenvolvimento Pessoal. Carga horária: 20h. Transforme sua relação com o dinheiro e construa uma vida financeira mais equilibrada! O curso aborda a relação com o dinheiro, o orçamento pessoal e familiar, crédito e endividamento, consumo planejado, poupança, investimento, prevenção e proteção financeira. Destinado a servidores, trabalhadores e cidadãos que desejam desenvolver habilidades financeiras para organizar suas finanças, sair das dívidas e construir uma reserva com mais segurança e planejamento. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/170');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Gestão Pessoal - Base da Liderança', 'curso', 'Desenvolvimento Pessoal', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/163', 'gratuito', 'Intermediário', 'Gestão Pessoal - Base da Liderança — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Liderança. Carga horária: 50h. Construa sua liderança a partir do autoconhecimento e do desenvolvimento pessoal! O curso aborda o desenvolvimento biopsicossocial, as dimensões psicológica e comportamental, a dimensão social e o desenvolvimento integrativo, a mentalidade, a psicologia positiva, virtudes, valores e técnicas de coaching. Destinado a gestores, líderes e servidores que desejam fortalecer as bases pessoais de sua liderança com autoconhecimento, propósito e equilíbrio entre as dimensões da vida. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/163');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Lei Brasileira de Proteção de Dados Pessoais', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/153', 'gratuito', 'Iniciante', 'Introdução à Lei Brasileira de Proteção de Dados Pessoais — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Gestão da Informação e do Conhecimento. Carga horária: 10h. Compreenda os fundamentos da LGPD e atue em conformidade com a legislação! O curso aborda a introdução e os conceitos, a abrangência e aplicabilidade, os fundamentos legais, os direitos do titular, os agentes de tratamento e as hipóteses de tratamento. Destinado a servidores, gestores e técnicos que precisam compreender os princípios e requisitos da Lei Geral de Proteção de Dados para adequar as práticas da organização e garantir a proteção dos dados pessoais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/153');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Promoção dos direitos da população em situação de rua', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/149', 'gratuito', 'Iniciante', 'Promoção dos direitos da população em situação de rua — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Assistência Social. Carga horária: 30h. Fortaleça a promoção dos direitos da população em situação de rua! O curso aborda a Política Nacional para a População em Situação de Rua, os caminhos do direito, os direitos fundamentais, as ações de trabalho, saúde e educação e as estratégias de dignidade e inclusão. Destinado a gestores, técnicos e profissionais que atuam no atendimento e na formulação de políticas para populações em situação de rua e extrema vulnerabilidade social. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/149');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Governo Aberto', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/140', 'gratuito', 'Iniciante', 'Governo Aberto — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 40h. Compreenda o governo aberto e sua importância para a democracia e a inovação pública! O curso aborda a introdução ao governo aberto, o papel das TICs, a evolução do governo digital, as partes interessadas, o ciclo de elaboração de políticas e os princípios de participação e transparência. Destinado a gestores, servidores e cidadãos que desejam compreender como os princípios de abertura, transparência e participação podem transformar a relação entre Estado e sociedade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/140');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Proteção ao Denunciante e Tratamento de Denúncias em Ouvidoria', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/132', 'gratuito', 'Iniciante', 'Proteção ao Denunciante e Tratamento de Denúncias em Ouvidoria — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 20h. Conheça os mecanismos de proteção ao denunciante e as boas práticas para o tratamento de denúncias nas ouvidorias. O curso apresenta quem é o denunciante, a importância de sua proteção, a construção do sistema brasileiro de proteção e os procedimentos para recebimento e tratamento de denúncias, com foco na preservação da identidade. Ao longo do curso, você compreenderá os cuidados necessários para assegurar o tratamento adequado das denúncias e fortalecer a confiança da sociedade nas ouvidorias  Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/132');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Direitos Humanos: Uma Declaração Universal', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/130', 'gratuito', 'Iniciante', 'Direitos Humanos: Uma Declaração Universal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 20h. Compreenda os fundamentos dos Direitos Humanos e sua construção histórica até a Declaração Universal! O curso aborda a trajetória dos direitos humanos, a criação da ONU, a Declaração Universal, os direitos civis, políticos, econômicos, sociais, culturais e de solidariedade, e o exercício concreto dos direitos no Brasil. Destinado a servidores, educadores e cidadãos que desejam aprofundar seu conhecimento sobre os fundamentos e a aplicação dos direitos humanos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/130');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Educação em Direitos Humanos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/129', 'gratuito', 'Iniciante', 'Educação em Direitos Humanos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Direitos Humanos. Carga horária: 30h. Compreenda os fundamentos e a história da educação em direitos humanos e aplique-os na sua prática! O curso aborda o que são direitos humanos, os aspectos históricos da educação em DH, os documentos de referência, as políticas nacionais e como a educação em DH acontece na diversidade contemporânea. Destinado a educadores, gestores e servidores comprometidos com a promoção da dignidade humana em suas práticas profissionais e institucionais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/129');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: MROSC: Planejamento e Transparência', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/122', 'gratuito', 'Iniciante', 'MROSC: Planejamento e Transparência — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transferências Voluntárias. Carga horária: 20h. Planeje parcerias com OSC com transparência e conformidade! O curso aborda a atuação em rede de OSC, as razões para parcerias, a transição dos convênios, a implementação federativa do MROSC e os princípios de transparência. Destinado a gestores públicos e de organizações da sociedade civil que precisam compreender o Marco Regulatório das OSC e estruturar parcerias mais transparentes, eficazes e alinhadas à legislação vigente. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/122');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução ao Orçamento Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/116', 'gratuito', 'Iniciante', 'Introdução ao Orçamento Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 40h. Compreenda o orçamento público brasileiro em toda a sua extensão! O curso aborda o ciclo orçamentário, os princípios orçamentários, a Lei de Responsabilidade Fiscal, receitas e despesas públicas, dívida pública, financiamento orçamentário e política econômica e programação financeira. Essencial para servidores, gestores e cidadãos que desejam entender como o Estado arrecada, planeja e gasta os recursos públicos com transparência e responsabilidade. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/116');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Básico em Orçamento Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/115', 'gratuito', 'Iniciante', 'Básico em Orçamento Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 30h. Compreenda os fundamentos do orçamento público e sua relação com a cidadania! O curso aborda as funções e princípios orçamentários, receita e despesa pública, transparência governamental, fundamentação legal, o PPA, a LDO e a LOA e a participação social no ciclo orçamentário. Destinado a servidores, gestores e cidadãos que desejam compreender como o dinheiro público é planejado, arrecadado e aplicado no Brasil, fortalecendo o controle social. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/115');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Lei de Diretrizes Orçamentárias para Municípios', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/113', 'gratuito', 'Iniciante', 'Lei de Diretrizes Orçamentárias para Municípios — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 30h. Domine a Lei de Diretrizes Orçamentárias municipal com segurança e competência! O curso aborda o sistema orçamentário com PPA, LDO e LOA, a estrutura da LDO, as metas e prioridades, as diretrizes de política fiscal e as disposições gerais. Destinado a gestores, secretários de finanças e técnicos municipais que precisam compreender e elaborar a LDO com qualidade, garantindo sua consistência com o planejamento municipal e as exigências da legislação fiscal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/113');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Gestão de Projetos', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/104', 'gratuito', 'Iniciante', 'Introdução à Gestão de Projetos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Estratégia e Planejamento. Carga horária: 20h. Inicie sua jornada na gestão de projetos com uma base sólida e abrangente! O curso aborda a história do gerenciamento de projetos, fontes de conhecimento, as diferenças entre projeto e operação, o gerenciamento de projetos, programas e portfólios, o ciclo de vida e o papel do gerente de projetos. Destinado a servidores e profissionais que buscam compreender os fundamentos da gestão de projetos para planejar e executar iniciativas com mais método e eficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/104');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Impactos da Mudança do Clima para a Gestão Municipal', 'curso', 'Ciências Biológicas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/97', 'gratuito', 'Iniciante', 'Impactos da Mudança do Clima para a Gestão Municipal — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Políticas de Sustentabilidade e Clima. Carga horária: 20h. Compreenda os impactos da mudança do clima para a gestão municipal e prepare seu município! O curso aborda o efeito estufa, as conferências climáticas, o Plano Nacional de Adaptação, os relatórios de avaliação e os impactos esperados para os municípios brasileiros. Destinado a prefeitos, secretários e técnicos municipais que buscam compreender os riscos climáticos para o território e incorporar a adaptação às mudanças do clima no planejamento e nas políticas locais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/97');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Estatística', 'curso', 'Inteligência Artificial & Dados', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/96', 'gratuito', 'Iniciante', 'Estatística — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Análise e Ciência de Dados. Carga horária: 20h. Domine os fundamentos da estatística e aplique-os na análise de dados e avaliação de projetos! O curso aborda estatística descritiva, distribuição de frequências, medidas de posição e dispersão, probabilidades e técnicas de amostragem, incluindo dimensionamento de amostras e análise de riscos. Essencial para analistas, gestores e servidores que precisam interpretar dados com rigor estatístico para embasar decisões e avaliar resultados de políticas públicas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/96');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ciclo de Gestão do Investimento Público', 'curso', 'Gestão & Negócios', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/95', 'gratuito', 'Iniciante', 'Ciclo de Gestão do Investimento Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Orçamento e Finanças. Carga horária: 20h. Compreenda o ciclo de gestão do investimento público e tome decisões mais fundamentadas! O curso aborda o ciclo institucional, a seleção preliminar de projetos, a avaliação ex ante, a revisão independente e a seleção de projetos para investimento. Destinado a analistas, gestores e técnicos de planejamento que buscam compreender as etapas do ciclo de gestão do investimento público para melhorar a qualidade da seleção e implementação dos projetos governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/95');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: eMAG Desenvolvedor', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/42', 'gratuito', 'Iniciante', 'eMAG Desenvolvedor — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 30h. Construa aplicações web acessíveis e inclusivas com o eMAG! O curso aborda os tipos de deficiências e uso de tecnologias assistivas, além das diretrizes de acessibilidade para desenvolvimento de conteúdos web, avaliação de acessibilidade e ferramentas para implementação. Destinado a desenvolvedores, analistas de sistemas e profissionais de TI do setor público que desejam garantir o acesso igualitário aos serviços digitais governamentais. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/42');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: eMAG Conteudista', 'curso', 'Tecnologia', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/41', 'gratuito', 'Iniciante', 'eMAG Conteudista — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transformação e Governo Digital. Carga horária: 20h. Crie conteúdos web acessíveis e inclusivos com as diretrizes do eMAG! O curso aborda a acessibilidade na web, os tipos de deficiências, o uso de tecnologias assistivas, as diretrizes de desenvolvimento de conteúdos acessíveis e a avaliação de acessibilidade. Destinado a redatores, comunicadores e produtores de conteúdo do setor público que desejam garantir que os textos, imagens e materiais publicados na web sejam acessíveis a todos os usuários, incluindo pessoas com deficiência. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/41');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Controles Institucional e Social dos Gastos Públicos', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/12', 'gratuito', 'Iniciante', 'Controles Institucional e Social dos Gastos Públicos — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 30h. Compreenda os mecanismos de controle dos gastos públicos e fortaleça a cidadania fiscal! O curso aborda o controle institucional e o controle social dos gastos, o controle exercido pela cidadania e pelos Conselhos Municipais e a qualidade do gasto público. Destinado a servidores, conselheiros e cidadãos que desejam compreender como as instituições e a sociedade podem fiscalizar e qualificar o uso dos recursos públicos. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/12');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Introdução à Libras', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/11', 'gratuito', 'Intermediário', 'Introdução à Libras — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Diversidade, Inclusão e Equidade. Carga horária: 60h. Aprenda Libras e contribua para uma sociedade mais inclusiva! O curso apresenta a cultura surda, perspectiva socioantropológica e legislação sobre a Língua Brasileira de Sinais. Nas aulas práticas, você desenvolve habilidades com o alfabeto manual, pronomes, expressões faciais, família, calendário, números, ambientes domésticos, transportes, animais, classificadores e profissões. Um primeiro passo essencial para comunicar-se com respeito com pessoas surdas. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/11');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Regulamentação da Lei de Acesso à Informação nos Municípios', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/8', 'gratuito', 'Iniciante', 'Regulamentação da Lei de Acesso à Informação nos Municípios — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Transparência e Controle. Carga horária: 20h. Regulamente a Lei de Acesso à Informação no seu município com segurança jurídica! O curso aborda o direito de acesso à informação, a abrangência da LAI e os procedimentos para regulamentação municipal da lei. Destinado a gestores, juristas e técnicos municipais que buscam compreender os requisitos da LAI e estruturar a regulamentação local, garantindo que os cidadãos possam exercer o direito de acesso às informações produzidas e custodiadas pelo poder público municipal. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/8');
INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'EV.G: Ética e Serviço Público', 'curso', 'Ciências Humanas', 'Escola Virtual de Governo (EV.G / ENAP)', 'https://www.escolavirtual.gov.br/curso/4', 'gratuito', 'Iniciante', 'Ética e Serviço Público — Curso gratuito e online oferecido pela Escola Virtual de Governo (EV.G / ENAP). Área Temática: Ética e Integridade. Carga horária: 20h. Fortaleça os fundamentos éticos essenciais para o exercício da função pública! O curso aborda os conceitos de ética, relativismo, filosofia moral, ética e política, a ética da vida pública, os dilemas éticos, a integridade, a impessoalidade e a probidade administrativa, com exercícios e orientações do Código de Ética Profissional. Destinado a todos os servidores públicos que buscam compreender e aplicar os princípios éticos no seu trabalho. Com emissão de certificado oficial gratuito de conclusão reconhecido pelo Governo Federal.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://www.escolavirtual.gov.br/curso/4');
