INSERT INTO cursos (titulo, tipo, area, plataforma, url, licenca, nivel, descricao) SELECT 'Trilha Completa Code IoT: Internet das Coisas (Samsung & LSI-TEC / USP)', 'curso', 'Tecnologia & Guias Digitais', 'Code IoT', 'https://codeiot.org.br/', 'gratuito', 'Iniciante', 'Jornada completa de formação em Internet das Coisas desenvolvida pela Samsung em parceria com o LSI-TEC e a USP. Abrange desde os fundamentos de redes e sensores até a programação em blocos (Scratch), circuitos eletrônicos, computação física com Arduino, desenvolvimento de aplicativos móveis no App Inventor e integração de sistemas em nuvem para cidades inteligentes e automação residencial. Certificação oficial gratuita.' WHERE NOT EXISTS (SELECT 1 FROM cursos WHERE url = 'https://codeiot.org.br/');
